{
  "name": "Gerenciador de Territórios da Congregação",
  "description": "Um sistema completo para gerenciar territórios de congregação, incluindo solicitação, atribuição, controle de prazo e relatórios. Construído com React e Firebase para uma experiência moderna e responsiva."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React from 'react';
import { AuthProvider, useAuth } from './context/AuthContext';
import LoginPage from './components/LoginPage';
import AdminDashboard from './components/AdminDashboard';
import PublisherDashboard from './components/PublisherDashboard';
import Header from './components/Header';

const AppContent: React.FC = () => {
  const { user, loading } = useAuth();

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="w-16 h-16 border-4 border-blue-500 border-dashed rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {user ? <Header /> : null}
      <main className="p-4 sm:p-6 md:p-8">
        {!user ? (
          <LoginPage />
        ) : user.role === 'admin' ? (
          <AdminDashboard />
        ) : (
          <PublisherDashboard />
        )}
      </main>
    </div>
  );
};

const App: React.FC = () => {
  return (
    <AuthProvider>
      <AppContent />
    </AuthProvider>
  );
};

export default App;

export enum TerritoryStatus {
  AVAILABLE = 'disponível',
  REQUESTED = 'solicitado',
  IN_USE = 'em uso',
  CLOSED = 'fechado',
}

export interface User {
  id: string;
  email: string;
  role: 'admin' | 'publicador';
}

export interface TerritoryHistory {
  userId: string;
  userName: string;
  completedDate: Date;
}

export interface Territory {
  id: string;
  name: string;
  status: TerritoryStatus;
  pdfUrl: string;
  assignedTo?: string | null;
  assignedToName?: string | null;
  assignmentDate?: Date | null;
  dueDate?: Date | null;
  history: TerritoryHistory[];
}

export enum RequestStatus {
    PENDING = 'pendente',
    APPROVED = 'aprovado',
    REJECTED = 'rejeitado'
}

export interface TerritoryRequest {
    id: string;
    territoryId: string;
    territoryName: string;
    userId: string;
    userName: string;
    requestDate: Date;
    status: RequestStatus;
}

export interface Report {
    id: string;
    territoryId: string;
    territoryName: string;
    userId: string;
    userName: string;
    reportDate: Date;
    notes: string;
}

import React, { createContext, useState, useEffect, useContext, ReactNode } from 'react';
import { User } from '../types';
import { apiLogin, apiLogout } from '../services/api';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, pass: string) => Promise<void>;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Simulate checking for a logged-in user on component mount
    const storedUser = localStorage.getItem('user');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
    setLoading(false);
  }, []);

  const login = async (email: string, pass: string) => {
    setLoading(true);
    try {
      const loggedInUser = await apiLogin(email, pass);
      setUser(loggedInUser);
      localStorage.setItem('user', JSON.stringify(loggedInUser));
    } catch (error) {
      console.error("Login failed:", error);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const logout = () => {
    apiLogout();
    setUser(null);
    localStorage.removeItem('user');
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import { useContext } from 'react';
import { AuthContext } from '../context/AuthContext';

// This is a re-export for convenience, the actual implementation is in AuthContext.tsx
export { useAuth } from '../context/AuthContext';

import { User, Territory, TerritoryStatus, RequestStatus, TerritoryRequest, Report } from '../types';

// --- MOCK DATABASE ---
const MOCK_USERS: User[] = [
  { id: 'admin1', email: 'admin@example.com', role: 'admin' },
  { id: 'pub1', email: 'publicador1@example.com', role: 'publicador' },
  { id: 'pub2', email: 'publicador2@example.com', role: 'publicador' },
];

let MOCK_TERRITORIES: Territory[] = [
  { id: 't1', name: 'Centro A-1', status: TerritoryStatus.AVAILABLE, pdfUrl: '#', history: [] },
  { id: 't2', name: 'Centro A-2', status: TerritoryStatus.AVAILABLE, pdfUrl: '#', history: [] },
  { id: 't3', name: 'Bairro Sul B-1', status: TerritoryStatus.IN_USE, pdfUrl: '#', assignedTo: 'pub1', assignedToName: 'publicador1@example.com', assignmentDate: new Date(new Date().setDate(new Date().getDate() - 10)), dueDate: new Date(new Date().setDate(new Date().getDate() + 20)), history: [] },
  { id: 't4', name: 'Bairro Sul B-2', status: TerritoryStatus.REQUESTED, pdfUrl: '#', history: [] },
  { id: 't5', name: 'Zona Leste C-1', status: TerritoryStatus.CLOSED, pdfUrl: '#', history: [{ userId: 'pub2', userName: 'publicador2@example.com', completedDate: new Date() }] },
  { id: 't6', name: 'Zona Norte D-5', status: TerritoryStatus.IN_USE, pdfUrl: '#', assignedTo: 'pub2', assignedToName: 'publicador2@example.com', assignmentDate: new Date(new Date().setDate(new Date().getDate() - 28)), dueDate: new Date(new Date().setDate(new Date().getDate() + 2)), history: [] },
];

let MOCK_REQUESTS: TerritoryRequest[] = [
    { id: 'req1', territoryId: 't4', territoryName: 'Bairro Sul B-2', userId: 'pub2', userName: 'publicador2@example.com', requestDate: new Date(), status: RequestStatus.PENDING },
];

let MOCK_REPORTS: Report[] = [];

// --- MOCK API FUNCTIONS ---
const simulateDelay = (ms: number) => new Promise(res => setTimeout(res, ms));

export const apiLogin = async (email: string, pass: string): Promise<User> => {
  await simulateDelay(500);
  console.log(`Attempting login for: ${email}`);
  const user = MOCK_USERS.find(u => u.email === email);
  if (user && pass === '123456') { // Simple password check
    return { ...user };
  }
  throw new Error('Credenciais inválidas');
};

export const apiLogout = () => {
  console.log('User logged out');
};

export const fetchAllTerritories = async (): Promise<Territory[]> => {
  await simulateDelay(800);
  return [...MOCK_TERRITORIES];
};

export const fetchPublisherData = async (userId: string): Promise<{ myTerritory: Territory | null, availableTerritories: Territory[], hasPendingRequest: boolean }> => {
    await simulateDelay(800);
    const myTerritory = MOCK_TERRITORIES.find(t => t.assignedTo === userId && t.status === TerritoryStatus.IN_USE) || null;
    const availableTerritories = MOCK_TERRITORIES.filter(t => t.status === TerritoryStatus.AVAILABLE);
    const hasPendingRequest = MOCK_REQUESTS.some(r => r.userId === userId && r.status === RequestStatus.PENDING);
    return { myTerritory, availableTerritories, hasPendingRequest };
};

export const requestTerritory = async (territoryId: string, userId: string): Promise<void> => {
    await simulateDelay(500);
    const user = MOCK_USERS.find(u => u.id === userId);
    const territory = MOCK_TERRITORIES.find(t => t.id === territoryId);
    if (!user || !territory) throw new Error("Usuário ou território não encontrado.");

    territory.status = TerritoryStatus.REQUESTED;
    MOCK_REQUESTS.push({
        id: `req${Date.now()}`,
        territoryId: territory.id,
        territoryName: territory.name,
        userId: user.id,
        userName: user.email,
        requestDate: new Date(),
        status: RequestStatus.PENDING
    });
};

export const fetchAllRequests = async (): Promise<TerritoryRequest[]> => {
    await simulateDelay(600);
    return MOCK_REQUESTS.filter(r => r.status === RequestStatus.PENDING);
};

export const processRequest = async (requestId: string, approve: boolean): Promise<void> => {
    await simulateDelay(700);
    const request = MOCK_REQUESTS.find(r => r.id === requestId);
    if (!request) throw new Error("Solicitação não encontrada");

    const territory = MOCK_TERRITORIES.find(t => t.id === request.territoryId);
    if (!territory) throw new Error("Território não encontrado");

    if (approve) {
        request.status = RequestStatus.APPROVED;
        territory.status = TerritoryStatus.IN_USE;
        territory.assignedTo = request.userId;
        territory.assignedToName = request.userName;
        const assignmentDate = new Date();
        territory.assignmentDate = assignmentDate;
        territory.dueDate = new Date(assignmentDate.setDate(assignmentDate.getDate() + 30));
    } else {
        request.status = RequestStatus.REJECTED;
        territory.status = TerritoryStatus.AVAILABLE;
    }
};

export const submitReport = async (userId: string, territoryId: string, notes: string): Promise<void> => {
    await simulateDelay(700);
    const user = MOCK_USERS.find(u => u.id === userId);
    const territory = MOCK_TERRITORIES.find(t => t.id === territoryId);
    if (!user || !territory) throw new Error("Usuário ou território não encontrado.");

    MOCK_REPORTS.push({
        id: `rep${Date.now()}`,
        territoryId: territory.id,
        territoryName: territory.name,
        userId: user.id,
        userName: user.email,
        reportDate: new Date(),
        notes: notes
    });

    territory.status = TerritoryStatus.CLOSED;
    territory.history.push({ userId: user.id, userName: user.email, completedDate: new Date() });
    territory.assignedTo = null;
    territory.assignedToName = null;
    territory.assignmentDate = null;
    territory.dueDate = null;
};

export const uploadTerritory = async (name: string, file: File): Promise<void> => {
    await simulateDelay(1000);
    const newTerritory: Territory = {
        id: `t${Date.now()}`,
        name: name,
        status: TerritoryStatus.AVAILABLE,
        pdfUrl: '#', // In a real app, this would be the Firebase Storage URL
        history: []
    };
    MOCK_TERRITORIES.unshift(newTerritory);
    console.log(`Uploaded ${file.name} for territory ${name}`);
};

export const formatDate = (date: Date | undefined | null): string => {
  if (!date) return 'N/A';
  return new Date(date).toLocaleDateString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  });
};

export const getDaysRemaining = (dueDate: Date | undefined | null): number | null => {
    if (!dueDate) return null;
    const today = new Date();
    const due = new Date(dueDate);
    const diffTime = due.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays;
}

export const getDeadlineColorInfo = (dueDate: Date | undefined | null): { textColor: string, bgColor: string, label: string } => {
  const daysRemaining = getDaysRemaining(dueDate);

  if (daysRemaining === null || daysRemaining < 0) {
    return { textColor: 'text-white', bgColor: 'bg-red-600', label: 'Atrasado' };
  }
  if (daysRemaining <= 5) { // 30-26 = 4, so <= 5 for 26-30 range
    return { textColor: 'text-white', bgColor: 'bg-orange-500', label: `Vence em ${daysRemaining} dias` };
  }
  if (daysRemaining <= 14) { // 30-16 = 14
    return { textColor: 'text-gray-800', bgColor: 'bg-yellow-400', label: `Vence em ${daysRemaining} dias` };
  }
  return { textColor: 'text-gray-800', bgColor: 'bg-green-400', label: `Vence em ${daysRemaining} dias` };
};

