export default LoginPage;

import React, { useState, useEffect, useCallback } from 'react';
import { Territory, TerritoryRequest } from '../types';
import { fetchAllTerritories, fetchAllRequests, processRequest, uploadTerritory } from '../services/api';
import { formatDate, getDeadlineColorInfo } from '../utils/helpers';
import { TerritoryStatus } from '../types';

const UploadTerritoryModal: React.FC<{ onClose: () => void; onUpload: (name: string, file: File) => void; }> = ({ onClose, onUpload }) => {
    const [name, setName] = useState('');
    const [file, setFile] = useState<File | null>(null);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (name && file) {
            onUpload(name, file);
        }
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
            <div className="bg-white rounded-lg p-8 w-full max-w-md">
                <h2 className="text-2xl font-bold mb-4">Carregar Novo Território</h2>
                <form onSubmit={handleSubmit}>
                    <div className="mb-4">
                        <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="territory-name">Nome do Território</label>
                        <input id="territory-name" type="text" value={name} onChange={e => setName(e.target.value)} required className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline" />
                    </div>
                    <div className="mb-6">
                        <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="territory-file">Arquivo PDF do Mapa</label>
                        <input id="territory-file" type="file" accept=".pdf" onChange={e => setFile(e.target.files ? e.target.files[0] : null)} required className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline" />
                    </div>
                    <div className="flex items-center justify-end gap-4">
                        <button type="button" onClick={onClose} className="bg-gray-500 hover:bg-gray-600 text-white font-bold py-2 px-4 rounded">Cancelar</button>
                        <button type="submit" className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded">Carregar</button>
                    </div>
                </form>
            </div>
        </div>
    );
};


const AdminDashboard: React.FC = () => {
    const [territories, setTerritories] = useState<Territory[]>([]);
    const [requests, setRequests] = useState<TerritoryRequest[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [actionLoading, setActionLoading] = useState<string | null>(null);

    const fetchData = useCallback(async () => {
        setLoading(true);
        setError('');
        try {
            const [territoriesData, requestsData] = await Promise.all([
                fetchAllTerritories(),
                fetchAllRequests(),
            ]);
            setTerritories(territoriesData);
            setRequests(requestsData);
        } catch (err) {
            setError('Falha ao carregar os dados. Tente novamente mais tarde.');
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    const handleProcessRequest = async (requestId: string, approve: boolean) => {
        setActionLoading(requestId);
        try {
            await processRequest(requestId, approve);
            await fetchData(); // Refresh data
        } catch (err) {
            setError('Falha ao processar a solicitação.');
        } finally {
            setActionLoading(null);
        }
    };

    const handleUpload = async (name: string, file: File) => {
        setLoading(true);
        setIsModalOpen(false);
        try {
            await uploadTerritory(name, file);
            await fetchData();
        } catch(err) {
            setError("Falha ao carregar o território.");
        } finally {
            setLoading(false);
        }
    }

    if (loading && territories.length === 0) {
        return <div className="text-center p-10">Carregando dados do administrador...</div>;
    }

    if (error) {
        return <div className="text-center p-10 text-red-500">{error}</div>;
    }

    return (
        <div className="container mx-auto">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-3xl font-bold text-gray-800">Painel do Administrador</h1>
                <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded-lg shadow-md transition transform hover:scale-105">
                    + Novo Território
                </button>
            </div>

            {isModalOpen && <UploadTerritoryModal onClose={() => setIsModalOpen(false)} onUpload={handleUpload} />}

            {/* Requests Section */}
            <section className="mb-8">
                <h2 className="text-2xl font-semibold text-gray-700 mb-4">Solicitações Pendentes ({requests.length})</h2>
                {requests.length > 0 ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {requests.map(req => (
                            <div key={req.id} className="bg-white p-5 rounded-lg shadow-md border-l-4 border-yellow-500">
                                <h3 className="font-bold text-lg">{req.territoryName}</h3>
                                <p className="text-sm text-gray-600">Solicitado por: {req.userName}</p>
                                <p className="text-sm text-gray-500">Data: {formatDate(req.requestDate)}</p>
                                <div className="mt-4 flex gap-4">
                                    <button
                                        onClick={() => handleProcessRequest(req.id, true)}
                                        disabled={actionLoading === req.id}
                                        className="bg-green-500 hover:bg-green-600 text-white font-semibold py-1 px-3 rounded text-sm w-full disabled:bg-green-300"
                                    >
                                        {actionLoading === req.id ? '...' : 'Aprovar'}
                                    </button>
                                    <button
                                        onClick={() => handleProcessRequest(req.id, false)}
                                        disabled={actionLoading === req.id}
                                        className="bg-red-500 hover:bg-red-600 text-white font-semibold py-1 px-3 rounded text-sm w-full disabled:bg-red-300"
                                    >
                                        {actionLoading === req.id ? '...' : 'Rejeitar'}
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <p className="text-gray-500">Nenhuma solicitação pendente no momento.</p>
                )}
            </section>

            {/* All Territories Section */}
            <section>
                <h2 className="text-2xl font-semibold text-gray-700 mb-4">Todos os Territórios ({territories.length})</h2>
                 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                    {territories.map(t => {
                        const colorInfo = getDeadlineColorInfo(t.dueDate);
                        return (
                            <div key={t.id} className="bg-white rounded-lg shadow-lg overflow-hidden transform hover:-translate-y-1 transition-transform duration-300">
                                <div className={`p-5 ${t.status === TerritoryStatus.IN_USE ? colorInfo.bgColor : 'bg-gray-200'}`}>
                                    <h3 className={`font-bold text-xl ${t.status === TerritoryStatus.IN_USE ? colorInfo.textColor : 'text-gray-800'}`}>{t.name}</h3>
                                </div>
                                <div className="p-5 space-y-3 text-sm">
                                    <p><strong>Status:</strong> <span className="font-semibold capitalize">{t.status}</span></p>
                                    {t.status === TerritoryStatus.IN_USE && t.assignedToName && (
                                        <>
                                            <p><strong>Publicador:</strong> {t.assignedToName}</p>
                                            <p><strong>Data de Vencimento:</strong> {formatDate(t.dueDate)}</p>
                                            <div className="w-full bg-gray-200 rounded-full h-2.5">
