const PublisherDashboard: React.FC = () => {
    const { user } = useAuth();
    const [myTerritory, setMyTerritory] = useState<Territory | null>(null);
    const [available, setAvailable] = useState<Territory[]>([]);
    const [hasPendingRequest, setHasPendingRequest] = useState(false);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [isReportModalOpen, setIsReportModalOpen] = useState(false);
    const [actionLoading, setActionLoading] = useState<string | null>(null);

    const fetchData = useCallback(async () => {
        if (!user) return;
        setLoading(true);
        setError('');
        try {
            const data = await fetchPublisherData(user.id);
            setMyTerritory(data.myTerritory);
            setAvailable(data.availableTerritories);
            setHasPendingRequest(data.hasPendingRequest);
        } catch (err) {
            setError('Falha ao carregar dados. Tente novamente.');
        } finally {
            setLoading(false);
        }
    }, [user]);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    const handleRequest = async (territoryId: string) => {
        if (!user) return;
        setActionLoading(territoryId);
        try {
            await requestTerritory(territoryId, user.id);
            await fetchData();
        } catch (err) {
            setError('Não foi possível solicitar o território.');
        } finally {
            setActionLoading(null);
        }
    };

    const handleSubmitReport = async (notes: string) => {
        if (!user || !myTerritory) return;
        try {
            await submitReport(user.id, myTerritory.id, notes);
            setIsReportModalOpen(false);
            await fetchData();
        } catch (err) {
            setError('Falha ao enviar o relatório.');
        }
    };

    if (loading) {
        return <div className="text-center p-10">Carregando painel...</div>;
    }

    if (error) {
        return <div className="text-center p-10 text-red-500">{error}</div>;
    }

    return (
        <div className="container mx-auto">
            <h1 className="text-3xl font-bold text-gray-800 mb-6">Painel do Publicador</h1>

            {isReportModalOpen && myTerritory && <ReportModal territory={myTerritory} onClose={() => setIsReportModalOpen(false)} onSubmit={handleSubmitReport} />}

            {/* My Territory Section */}
            <section className="mb-8">
                <h2 className="text-2xl font-semibold text-gray-700 mb-4">Meu Território Ativo</h2>
                {myTerritory ? (
                    (() => {
                        const colorInfo = getDeadlineColorInfo(myTerritory.dueDate);
                        const daysRemaining = getDaysRemaining(myTerritory.dueDate) ?? 0;
                        const progress = Math.max(0, 100 - (daysRemaining / 30) * 100);

                        return (
                            <div className={`bg-white rounded-xl shadow-lg overflow-hidden border-l-8 ${colorInfo.bgColor.replace('bg-', 'border-')}`}>
                                <div className="p-6 sm:p-8">
                                    <div className="sm:flex sm:items-start sm:justify-between">
                                        <div>
                                            <h3 className="text-2xl font-bold text-gray-900">{myTerritory.name}</h3>
                                            <p className="text-gray-600 mt-1">Data de vencimento: {formatDate(myTerritory.dueDate)}</p>
                                        </div>
                                        <div className={`mt-4 sm:mt-0 px-3 py-1 text-sm font-bold rounded-full ${colorInfo.bgColor} ${colorInfo.textColor}`}>
                                            {colorInfo.label}
                                        </div>
                                    </div>
                                    <div className="mt-6">
                                        <div className="w-full bg-gray-200 rounded-full h-4">
                                            <div className={`${colorInfo.bgColor} h-4 rounded-full transition-all duration-500`} style={{ width: `${progress}%` }}></div>
                                        </div>
                                    </div>
                                    <div className="mt-6 flex flex-col sm:flex-row gap-4">
                                        <a href={myTerritory.pdfUrl} target="_blank" rel="noopener noreferrer" className="w-full sm:w-auto text-center bg-gray-800 hover:bg-gray-900 text-white font-bold py-3 px-6 rounded-lg transition-colors">
                                            Ver Mapa (PDF)
                                        </a>
                                        <button onClick={() => setIsReportModalOpen(true)} className="w-full sm:w-auto text-center bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-6 rounded-lg transition-colors">
                                            Fechar e Relatar
                                        </button>
                                    </div>
                                </div>
                            </div>
                        )
                    })()
                ) : hasPendingRequest ? (
                    <div className="bg-yellow-100 border-l-4 border-yellow-500 text-yellow-700 p-4 rounded-md" role="alert">
                        <p className="font-bold">Solicitação Enviada</p>
                        <p>Você tem uma solicitação de território pendente. Aguarde a aprovação do administrador.</p>
                    </div>
                ) : (
                    <p className="text-gray-500 bg-gray-100 p-4 rounded-md">Você não tem um território ativo. Solicite um da lista abaixo.</p>
                )}
            </section>

            {/* Available Territories Section */}
            <section>
                <h2 className="text-2xl font-semibold text-gray-700 mb-4">Territórios Disponíveis</h2>
                {(!myTerritory && !hasPendingRequest) ? (
                    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
                        {available.map(t => (
                            <div key={t.id} className="bg-white p-5 rounded-lg shadow-md flex flex-col justify-between">
                                <h3 className="font-bold text-lg mb-4">{t.name}</h3>
                                <button
                                    onClick={() => handleRequest(t.id)}
                                    disabled={actionLoading === t.id}
                                    className="w-full bg-green-500 hover:bg-green-600 text-white font-semibold py-2 px-4 rounded-lg transition-colors disabled:bg-green-300"
                                >
                                    {actionLoading === t.id ? 'Solicitando...' : 'Solicitar'}
                                </button>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="bg-gray-100 p-6 rounded-lg text-center">
                        <p className="text-gray-600">Você precisa fechar seu território atual antes de solicitar um novo.</p>
                    </div>
                )}
            </section>
        </div>
    );
};

