rules_version = '2';

service cloud.firestore {
  match /databases/{database}/documents {

    // Helper function to check for admin role
    function isAdmin() {
      return get(/databases/$(database)/documents/users/$(request.auth.uid)).data.role == 'admin';
    }

    // Users can only read their own profile, admins can read any.
    match /users/{userId} {
      allow read: if request.auth.uid == userId || isAdmin();
      // Allow user creation, but not role change
      allow create: if request.auth.uid == userId;
      allow update: if request.auth.uid == userId && request.resource.data.role == resource.data.role;
    }

    // Territories
    match /territories/{territoryId} {
      // Admins can do anything. Publishers can only read.
      allow read: if request.auth.uid != null;
      allow write: if isAdmin();

      // A publisher CANNOT directly assign a territory to themselves. This must be done via a request approved by an admin.
    }

    // Territory Requests
    match /requests/{requestId} {
      allow read: if request.auth.uid != null; // Admin will see all, filtered on client. Publisher will see theirs.

      // Publishers can create requests for themselves if they don't have an active territory.
      allow create: if request.auth.uid == request.resource.data.userId
                     && request.resource.data.status == 'pending'
                     && !exists(/databases/$(database)/documents/territories?where("assignedTo", "==", request.auth.uid));

      // Only admins can approve or reject (update status).
      allow update: if isAdmin();
    }

    // Reports
    match /reports/{reportId} {
        // Publishers can read their own reports, admins can read all.
        allow read: if isAdmin() || get(/databases/$(database)/documents/reports/$(reportId)).data.userId == request.auth.uid;

        // Publishers can create reports only for territories assigned to them.
        allow create: if request.auth.uid == request.resource.data.userId
                       && get(/databases/$(database)/documents/territories/$(request.resource.data.territoryId)).data.assignedTo == request.auth.uid;
    }
  }
}

const functions = require('firebase-functions');
const admin = require('firebase-admin');
admin.initializeApp();

// NOTE: This file demonstrates the structure and logic for Cloud Functions.
// You would need to set up FCM (Firebase Cloud Messaging) and store user device tokens
// in Firestore to send push notifications.

/**
 * Sends a notification to all admin users.
 * @param {object} payload The notification payload.
 */
async function notifyAdmins(payload) {
    // 1. Get all users with the 'admin' role.
    const usersSnapshot = await admin.firestore().collection('users').where('role', '==', 'admin').get();

    // 2. Get the FCM tokens for each admin.
    const tokens = [];
    usersSnapshot.forEach(userDoc => {
        const userData = userDoc.data();
        if (userData.fcmToken) {
            tokens.push(userData.fcmToken);
        }
    });

    // 3. Send the notification.
    if (tokens.length > 0) {
        return admin.messaging().sendToDevice(tokens, payload);
    }
    return null;
}

/**
 * Sends a notification to a specific user.
 * @param {string} userId The ID of the user to notify.
 * @param {object} payload The notification payload.
 */
async function notifyUser(userId, payload) {
    const userDoc = await admin.firestore().collection('users').doc(userId).get();
    if (userDoc.exists) {
        const fcmToken = userDoc.data().fcmToken;
        if (fcmToken) {
            return admin.messaging().sendToDevice(fcmToken, payload);
        }
    }
    return null;
}


// --- Cloud Function Triggers ---

// 1. Notify admin of a new territory request.
exports.onTerritoryRequest = functions.firestore
    .document('requests/{requestId}')
    .onCreate(async (snap, context) => {
        const request = snap.data();
        const payload = {
            notification: {
                title: 'Nova Solicitação de Território',
                body: `${request.userName} solicitou o território ${request.territoryName}.`,
                icon: 'default',
                click_action: 'FLUTTER_NOTIFICATION_CLICK' // Or your app's main activity
            }
        };
        return notifyAdmins(payload);
    });

// 2. Notify admin of a submitted report.
exports.onReportSubmitted = functions.firestore
    .document('reports/{reportId}')
    .onCreate(async (snap, context) => {
        const report = snap.data();
        const payload = {
            notification: {
                title: 'Relatório Enviado',
                body: `${report.userName} enviou o relatório para o território ${report.territoryName}.`
            }
        };
        return notifyAdmins(payload);
    });

// 3. Notify publisher when their request is approved.
exports.onTerritoryApproved = functions.firestore
    .document('requests/{requestId}')
    .onUpdate(async (change, context) => {
        const newValue = change.after.data();
        const oldValue = change.before.data();

        if (newValue.status === 'aprovado' && oldValue.status !== 'aprovado') {
             const payload = {
                notification: {
                    title: 'Território Aprovado!',
                    body: `Sua solicitação para o território ${newValue.territoryName} foi aprovada.`
                }
            };
            return notifyUser(newValue.userId, payload);
        }
        return null;
    });

// 4. Cron job to check for deadlines (runs daily).
exports.checkDeadlines = functions.pubsub.schedule('every 24 hours').onRun(async (context) => {
    const territoriesRef = admin.firestore().collection('territories');
    const now = new Date();

    // Find territories nearing their due date
    const fiveDaysFromNow = new Date();
    fiveDaysFromNow.setDate(now.getDate() + 5);

    const snapshot = await territoriesRef
        .where('status', '==', 'em uso')
        .where('dueDate', '<=', fiveDaysFromNow)
        .get();

    if (snapshot.empty) {
        console.log('No territories nearing deadline.');
        return null;
    }

    const promises = [];
    snapshot.forEach(doc => {
        const territory = doc.data();
        const dueDate = territory.dueDate.toDate();
        const diffDays = Math.ceil((dueDate - now) / (1000 * 60 * 60 * 24));

        let message;
        if (diffDays <= 0) {
            message = `O prazo para o seu território ${territory.name} venceu! Por favor, envie o relatório.`;
        } else if (diffDays <= 5) {
            message = `Atenção: O prazo para o território ${territory.name} vence em ${diffDays} dias.`;
        }

        if (message) {
            const payload = { notification: { title: 'Aviso de Prazo de Território', body: message } };
            promises.push(notifyUser(territory.assignedTo, payload));
        }
    });

    return Promise.all(promises);
});

