import React, { useState, useEffect, useCallback } from 'react';
import { Territory, TerritoryRequest } from '../types';
import { fetchAllTerritories, fetchAllRequests, processRequest, uploadTerritory } from '../services/api';
// FIX: Import `getDaysRemaining` to resolve the "Cannot find name 'getDaysRemaining'" error.
import { formatDate, getDeadlineColorInfo, getDaysRemaining } from '../utils/helpers';
