const AdminDashboard: React.FC = () => {
    const [territories, setTerritories] = useState<Territory[]>([]);
    const [requests, setRequests] = useState<TerritoryRequest[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
    const [editingTerritory, setEditingTerritory] = useState<Territory | null>(null);
    const [deletingTerritory, setDeletingTerritory] = useState<Territory | null>(null);
    const [actionLoading, setActionLoading] = useState<string | null>(null);

    const fetchData = useCallback(async () => {
        setLoading(true);
        setError('');
        try {
            const [territoriesData, requestsData] = await Promise.all([
                fetchAllTerritories(),
                fetchAllRequests(),
            ]);
            setTerritories(territoriesData);
            setRequests(requestsData);
        } catch (err) {
            setError('Falha ao carregar os dados. Tente novamente mais tarde.');
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    const handleProcessRequest = async (requestId: string, approve: boolean) => {
        setActionLoading(requestId);
        try {
            await processRequest(requestId, approve);
            await fetchData();
        } catch (err) {
            setError('Falha ao processar a solicitação.');
        } finally {
            setActionLoading(null);
        }
    };

    const handleUpload = async (name: string, file: File) => {
        setLoading(true);
        setIsUploadModalOpen(false);
        try {
            await uploadTerritory(name, file);
            await fetchData();
        } catch(err) {
            setError("Falha ao carregar o território.");
        } finally {
            setLoading(false);
        }
    }

    const handleUpdate = async (territoryId: string, newName: string) => {
        try {
            await updateTerritory(territoryId, newName);
            setEditingTerritory(null);
            await fetchData();
        } catch(err) {
            setError("Falha ao atualizar o território.");
        }
    };

    const handleDelete = async () => {
        if (!deletingTerritory) return;
        setActionLoading(deletingTerritory.id);
        try {
            await deleteTerritory(deletingTerritory.id);
            setDeletingTerritory(null);
            await fetchData();
        } catch(err) {
            setError("Falha ao excluir o território.");
        } finally {
            setActionLoading(null);
        }
    };


    if (loading && territories.length === 0) {
        return <div className="text-center p-10">Carregando dados do administrador...</div>;
    }

    if (error) {
        return <div className="text-center p-10 text-red-500">{error}</div>;
    }

    return (
        <div className="container mx-auto">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-3xl font-bold text-gray-800">Painel do Administrador</h1>
                <button onClick={() => setIsUploadModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded-lg shadow-md transition transform hover:scale-105">
                    + Novo Território
                </button>
            </div>

            {isUploadModalOpen && <UploadTerritoryModal onClose={() => setIsUploadModalOpen(false)} onUpload={handleUpload} />}
            {editingTerritory && <EditTerritoryModal territory={editingTerritory} onClose={() => setEditingTerritory(null)} onSave={handleUpdate} />}
            {deletingTerritory && <ConfirmationModal 
                title="Excluir Território"
                message={`Tem certeza que deseja excluir o território "${deletingTerritory.name}"? Esta ação não pode ser desfeita.`}
                onClose={() => setDeletingTerritory(null)} 
                onConfirm={handleDelete} 
            />}

            {/* Requests Section */}
            <section className="mb-8">
                <h2 className="text-2xl font-semibold text-gray-700 mb-4">Solicitações Pendentes ({requests.length})</h2>
                {requests.length > 0 ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {requests.map(req => (
                            <div key={req.id} className="bg-white p-5 rounded-lg shadow-md border-l-4 border-yellow-500">
                                <h3 className="font-bold text-lg">{req.territoryName}</h3>
                                <p className="text-sm text-gray-600">Solicitado por: {req.userName}</p>
                                <p className="text-sm text-gray-500">Data: {formatDate(req.requestDate)}</p>
                                <div className="mt-4 flex gap-4">
                                    <button
                                        onClick={() => handleProcessRequest(req.id, true)}
                                        disabled={actionLoading === req.id}
                                        className="bg-green-500 hover:bg-green-600 text-white font-semibold py-1 px-3 rounded text-sm w-full disabled:bg-green-300"
                                    >
                                        {actionLoading === req.id ? '...' : 'Aprovar'}
                                    </button>
                                    <button
                                        onClick={() => handleProcessRequest(req.id, false)}
                                        disabled={actionLoading === req.id}
                                        className="bg-red-500 hover:bg-red-600 text-white font-semibold py-1 px-3 rounded text-sm w-full disabled:bg-red-300"
                                    >
                                        {actionLoading === req.id ? '...' : 'Rejeitar'}
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <p className="text-gray-500">Nenhuma solicitação pendente no momento.</p>
                )}
            </section>

            {/* All Territories Section */}
            <section>
                <h2 className="text-2xl font-semibold text-gray-700 mb-4">Todos os Territórios ({territories.length})</h2>
                 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                    {territories.map(t => {
                        const colorInfo = getDeadlineColorInfo(t.dueDate);
                        return (
                            <div key={t.id} className="bg-white rounded-lg shadow-lg overflow-hidden flex flex-col justify-between transform hover:-translate-y-1 transition-transform duration-300">
                                <div>
                                    <div className={`p-5 ${t.status === TerritoryStatus.IN_USE ? colorInfo.bgColor : 'bg-gray-200'}`}>
                                        <h3 className={`font-bold text-xl ${t.status === TerritoryStatus.IN_USE ? colorInfo.textColor : 'text-gray-800'}`}>{t.name}</h3>
                                    </div>
                                    <div className="p-5 space-y-3 text-sm">
                                        <p><strong>Status:</strong> <span className="font-semibold capitalize">{t.status}</span></p>
                                        {t.status === TerritoryStatus.IN_USE && t.assignedToName && (
                                            <>
                                                <p><strong>Publicador:</strong> {t.assignedToName}</p>
                                                <p><strong>Data de Vencimento:</strong> {formatDate(t.dueDate)}</p>
                                                <div className="w-full bg-gray-200 rounded-full h-2.5">
                                                    <div className={`${colorInfo.bgColor} h-2.5 rounded-full`} style={{ width: `${(30 - (getDaysRemaining(t.dueDate) || 0)) / 30 * 100}%` }}></div>
                                                </div>
                                                <p className={`text-xs font-bold ${colorInfo.textColor.replace('text-white', 'text-gray-800')}`}>{colorInfo.label}</p>
                                            </>
                                        )}
                                        {t.status === TerritoryStatus.REQUESTED && (
                                            <p className="text-yellow-600 font-semibold">Aguardando aprovação</p>
                                        )}
                                        {t.status === TerritoryStatus.CLOSED && (
                                            <p className="text-gray-600 font-semibold">Fechado em {formatDate(t.history[t.history.length-1]?.completedDate)}</p>
                                        )}
                                    </div>
                                </div>
                                <div className="px-5 pb-4 mt-2 border-t pt-3 flex justify-end gap-4">
                                    <button onClick={() => setEditingTerritory(t)} className="text-sm font-medium text-blue-600 hover:text-blue-800 transition-colors">Editar</button>
                                    <button onClick={() => setDeletingTerritory(t)} className="text-sm font-medium text-red-600 hover:text-red-800 transition-colors">Excluir</button>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </section>
        </div>
    );
};

