import React, { createContext, useState, useEffect, useContext, ReactNode } from 'react';
import { User as FirebaseUser, onAuthStateChanged, signOut, signInWithEmailAndPassword, createUserWithEmailAndPassword } from 'firebase/auth';
import { doc, getDoc, setDoc, query, where, getDocs, collection } from 'firebase/firestore';
import { User } from '../types';
import { auth, db } from '../firebase/config';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, pass: string) => Promise<void>;
  logout: () => Promise<void>;
  signUp: (name: string, email: string, pass: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser: FirebaseUser | null) => {
      if (firebaseUser) {
        // User is signed in, get their profile from Firestore.
        const userDocRef = doc(db, 'users', firebaseUser.uid);
        const userDocSnap = await getDoc(userDocRef);
        if (userDocSnap.exists()) {
          setUser({ id: firebaseUser.uid, ...userDocSnap.data() } as User);
        } else {
          // This case might happen if the user document wasn't created properly.
          // For safety, log them out.
          await signOut(auth);
          setUser(null);
        }
      } else {
        // User is signed out.
        setUser(null);
      }
      setLoading(false);
    });

    // Cleanup subscription on unmount
    return () => unsubscribe();
  }, []);

  const login = async (email: string, pass: string) => {
    await signInWithEmailAndPassword(auth, email, pass);
    // onAuthStateChanged will handle setting the user state
  };

  const logout = async () => {
    await signOut(auth);
  };

  const signUp = async (name: string, email: string, pass: string) => {
    // 1. Check if email is in the authorized_users collection
    const authorizedUsersRef = collection(db, "authorized_users");
    const q = query(authorizedUsersRef, where("email", "==", email));
    const querySnapshot = await getDocs(q);

    if (querySnapshot.empty) {
        throw new Error("Seu email não está autorizado. Entre em contato com o responsável pelo território.");
    }

    // 2. Create user in Firebase Authentication
    const userCredential = await createUserWithEmailAndPassword(auth, email, pass);
    const firebaseUser = userCredential.user;

    // 3. Create user document in Firestore
    const userDocRef = doc(db, 'users', firebaseUser.uid);
    await setDoc(userDocRef, {
        name: name,
        email: email,
        role: 'publicador',
    });

    // onAuthStateChanged will handle setting the user state
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, signUp }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import { Timestamp } from 'firebase/firestore';

export const formatDate = (date: Date | Timestamp | undefined | null): string => {
  if (!date) return 'N/A';
  const jsDate = date instanceof Timestamp ? date.toDate() : date;
  return new jsDate.toLocaleDateString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  });
};

export const getDaysRemaining = (dueDate: Date | Timestamp | undefined | null): number | null => {
    if (!dueDate) return null;
    const today = new Date();
    today.setHours(0, 0, 0, 0); // Normalize today to the start of the day
    const due = dueDate instanceof Timestamp ? dueDate.toDate() : dueDate;
    due.setHours(0, 0, 0, 0); // Normalize due date

    const diffTime = due.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays;
}

export const getDeadlineColorInfo = (dueDate: Date | Timestamp | undefined | null): { textColor: string, bgColor: string, label: string } => {
  const daysRemaining = getDaysRemaining(dueDate);

  if (daysRemaining === null || daysRemaining < 0) {
    return { textColor: 'text-white', bgColor: 'bg-red-600', label: 'Atrasado' };
  }
  if (daysRemaining <= 5) {
    return { textColor: 'text-white', bgColor: 'bg-orange-500', label: `Vence em ${daysRemaining} dias` };
  }
  if (daysRemaining <= 15) {
    return { textColor: 'text-gray-800', bgColor: 'bg-yellow-400', label: `Vence em ${daysRemaining} dias` };
  }
  return { textColor: 'text-gray-800', bgColor: 'bg-green-400', label: `Vence em ${daysRemaining} dias` };
};

