    const [error, setError] = useState('');
    const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
    const [editingTerritory, setEditingTerritory] = useState<Territory | null>(null);
    const [deletingTerritory, setDeletingTerritory] = useState<Territory | null>(null);
    const [actionLoading, setActionLoading] = useState<string | null>(null);

    useEffect(() => {
        setLoading(true);
        const territoriesQuery = query(collection(db, 'territories'), orderBy('createdAt', 'desc'));
        const requestsQuery = query(collection(db, 'requests'), where('status', '==', 'pendente'), orderBy('requestDate', 'asc'));

        const unsubTerritories = onSnapshot(territoriesQuery, (snapshot) => {
            const territoriesData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Territory));
            setTerritories(territoriesData);
            setLoading(false);
        }, (err) => {
            console.error(err);
            setError('Falha ao carregar territórios.');
            setLoading(false);
        });

        const unsubRequests = onSnapshot(requestsQuery, (snapshot) => {
            const requestsData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as TerritoryRequest));
            setRequests(requestsData);
        }, (err) => {
            console.error(err);
            setError('Falha ao carregar solicitações.');
        });

        return () => {
            unsubTerritories();
            unsubRequests();
        };
    }, []);

    const handleProcessRequest = async (request: TerritoryRequest, approve: boolean) => {
        setActionLoading(request.id);
        const territoryRef = doc(db, 'territories', request.territoryId);
        const requestRef = doc(db, 'requests', request.id);

        try {
            const batch = writeBatch(db);
            if (approve) {
                const assignmentDate = Timestamp.now();
                const dueDate = new Timestamp(assignmentDate.seconds + 30 * 24 * 60 * 60, assignmentDate.nanoseconds);
                batch.update(territoryRef, { 
                    status: TerritoryStatus.IN_USE,
                    assignedTo: request.userId,
                    assignedToName: request.userName,
                    assignmentDate: assignmentDate,
                    dueDate: dueDate
                });
                batch.update(requestRef, { status: 'aprovado' });
            } else {
                batch.update(territoryRef, { status: TerritoryStatus.AVAILABLE });
                batch.update(requestRef, { status: 'rejeitado' });
            }
            await batch.commit();
        } catch (err) {
            console.error(err);
            setError('Falha ao processar a solicitação.');
        } finally {
            setActionLoading(null);
        }
    };

    const handleUpload = async (name: string, file: File) => {
        const storageRef = ref(storage, `territories/${Date.now()}_${file.name}`);
        try {
            const snapshot = await uploadBytes(storageRef, file);
            const downloadURL = await getDownloadURL(snapshot.ref);

            await addDoc(collection(db, 'territories'), {
                name,
                pdfUrl: downloadURL,
                status: TerritoryStatus.AVAILABLE,
                createdAt: serverTimestamp(),
                history: []
            });
        } catch (err) {
            console.error(err);
            setError("Falha ao carregar o território.");
        }
    };

    const handleUpdate = async (territoryId: string, newName: string) => {
        const territoryRef = doc(db, 'territories', territoryId);
        try {
            await updateDoc(territoryRef, { name: newName });
        } catch(err) {
            console.error(err);
            setError("Falha ao atualizar o território.");
        }
    };

    const handleDelete = async () => {
        if (!deletingTerritory) return;
        setActionLoading(deletingTerritory.id);
        const territoryRef = doc(db, 'territories', deletingTerritory.id);
        const fileRef = ref(storage, deletingTerritory.pdfUrl);

        try {
            await deleteObject(fileRef); // Delete PDF from Storage
            await deleteDoc(territoryRef); // Delete doc from Firestore
        } catch(err) {
            console.error(err);
            setError("Falha ao excluir o território. Pode ser que o arquivo PDF não exista mais.");
            // Still try to delete from Firestore if storage fails
            try { await deleteDoc(territoryRef); } catch (e) {}
        } finally {
            setDeletingTerritory(null);
            setActionLoading(null);
        }
    };

    if (loading) {
        return <div className="text-center p-10">Carregando dados do administrador...</div>;
    }

    return (
        <div className="container mx-auto">
             {error && <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 rounded-md mb-6" role="alert">{error}</div>}
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-3xl font-bold text-gray-800">Painel do Administrador</h1>
                <button onClick={() => setIsUploadModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded-lg shadow-md transition transform hover:scale-105">
                    + Novo Território
                </button>
            </div>

            {isUploadModalOpen && <UploadTerritoryModal onClose={() => setIsUploadModalOpen(false)} onUpload={handleUpload} />}
            {editingTerritory && <EditTerritoryModal territory={editingTerritory} onClose={() => setEditingTerritory(null)} onSave={handleUpdate} />}
            {deletingTerritory && <ConfirmationModal 
                title="Excluir Território"
                message={`Tem certeza que deseja excluir o território "${deletingTerritory.name}"? Esta ação não pode ser desfeita.`}
                onClose={() => setDeletingTerritory(null)} 
                onConfirm={handleDelete}
                confirmText="Confirmar Exclusão"
            />}

            {/* Requests Section */}
            <section className="mb-8">
                <h2 className="text-2xl font-semibold text-gray-700 mb-4">Solicitações Pendentes ({requests.length})</h2>
                {requests.length > 0 ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {requests.map(req => (
                            <div key={req.id} className="bg-white p-5 rounded-lg shadow-md border-l-4 border-yellow-500">
                                <h3 className="font-bold text-lg">{req.territoryName}</h3>
                                <p className="text-sm text-gray-600">Solicitado por: {req.userName}</p>
                                <p className="text-sm text-gray-500">Data: {formatDate(req.requestDate)}</p>
                                <div className="mt-4 flex gap-4">
                                    <button onClick={() => handleProcessRequest(req, true)} disabled={actionLoading === req.id} className="bg-green-500 hover:bg-green-600 text-white font-semibold py-1 px-3 rounded text-sm w-full disabled:bg-green-300">
                                        {actionLoading === req.id ? '...' : 'Aprovar'}
                                    </button>
                                    <button onClick={() => handleProcessRequest(req, false)} disabled={actionLoading === req.id} className="bg-red-500 hover:bg-red-600 text-white font-semibold py-1 px-3 rounded text-sm w-full disabled:bg-red-300">
                                        {actionLoading === req.id ? '...' : 'Rejeitar'}
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <p className="text-gray-500">Nenhuma solicitação pendente no momento.</p>
                )}
            </section>

            {/* All Territories Section */}
            <section>
                <h2 className="text-2xl font-semibold text-gray-700 mb-4">Todos os Territórios ({territories.length})</h2>
                 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                    {territories.map(t => {
                        const colorInfo = getDeadlineColorInfo(t.dueDate);
                        return (
                            <div key={t.id} className="bg-white rounded-lg shadow-lg overflow-hidden flex flex-col justify-between transform hover:-translate-y-1 transition-transform duration-300">
                                <div>
                                    <div className={`p-5 ${t.status === TerritoryStatus.IN_USE ? colorInfo.bgColor : 'bg-gray-200'}`}>
                                        <h3 className={`font-bold text-xl ${t.status === TerritoryStatus.IN_USE ? colorInfo.textColor : 'text-gray-800'}`}>{t.name}</h3>
                                    </div>
                                    <div className="p-5 space-y-3 text-sm">
                                        <p><strong>Status:</strong> <span className="font-semibold capitalize">{t.status}</span></p>
                                        {t.status === TerritoryStatus.IN_USE && t.assignedToName && (
                                            <>
                                                <p><strong>Publicador:</strong> {t.assignedToName}</p>
                                                <p><strong>Data de Vencimento:</strong> {formatDate(t.dueDate)}</p>
                                                <p className={`text-xs font-bold ${colorInfo.textColor.replace('text-white', 'text-gray-800').replace('text-gray-800', 'text-current')}`}>{colorInfo.label}</p>
                                            </>
                                        )}
                                        {t.status === TerritoryStatus.REQUESTED && (
                                            <p className="text-yellow-600 font-semibold">Aguardando aprovação</p>
                                        )}
                                        {t.status === TerritoryStatus.CLOSED && t.history.length > 0 && (
                                            <p className="text-gray-600 font-semibold">Fechado em {formatDate(t.history[t.history.length-1]?.completedDate)}</p>
                                        )}
                                    </div>
                                </div>
                                <div className="px-5 pb-4 mt-2 border-t pt-3 flex justify-end gap-4">
                                    <button onClick={() => setEditingTerritory(t)} className="text-sm font-medium text-blue-600 hover:text-blue-800 transition-colors">Editar</button>
                                    <button onClick={() => setDeletingTerritory(t)} disabled={t.status === TerritoryStatus.IN_USE || t.status === TerritoryStatus.REQUESTED} className="text-sm font-medium text-red-600 hover:text-red-800 transition-colors disabled:text-gray-400 disabled:cursor-not-allowed">Excluir</button>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </section>
        </div>
    );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { Territory, TerritoryStatus } from '../types';
import { useAuth } from '../hooks/useAuth';
import { db } from '../firebase/config';
import { 
    collection, query, where, onSnapshot, addDoc, serverTimestamp, writeBatch, doc
} from 'firebase/firestore';
import { formatDate, getDeadlineColorInfo, getDaysRemaining } from '../utils/helpers';

const ReportModal: React.FC<{ territory: Territory; onClose: () => void; onSubmit: (notes: string) => Promise<void>; }> = ({ territory, onClose, onSubmit }) => {
    const [notes, setNotes] = useState('');
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        await onSubmit(notes);
        setLoading(false);
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-lg p-6 sm:p-8 w-full max-w-lg shadow-xl">
                <h2 className="text-2xl font-bold mb-2 text-gray-800">Fechar Território: {territory.name}</h2>
                <p className="text-gray-600 mb-6">Por favor, preencha o relatório para fechar este território.</p>
                <form onSubmit={handleSubmit}>
                    <div className="mb-4">
                        <label htmlFor="report-notes" className="block text-gray-700 text-sm font-bold mb-2">Observações</label>
                        <textarea
                            id="report-notes"
                            value={notes}
                            onChange={e => setNotes(e.target.value)}
                            required
                            rows={4}
                            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 bg-gray-50 leading-tight focus:outline-none focus:shadow-outline"
                            placeholder="Descreva o trabalho realizado, anote 'não trabalhados', etc."
                        />
                    </div>
                    <div className="flex items-center justify-end gap-4 mt-8">
                        <button type="button" onClick={onClose} className="bg-gray-500 hover:bg-gray-600 text-white font-bold py-2 px-4 rounded-lg transition-colors">Cancelar</button>
                        <button type="submit" disabled={loading} className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded-lg transition-colors disabled:bg-blue-300">
                            {loading ? 'Enviando...' : 'Enviar Relatório e Fechar'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

const PublisherDashboard: React.FC = () => {
    const { user } = useAuth();
    const [myTerritory, setMyTerritory] = useState<Territory | null>(null);
    const [available, setAvailable] = useState<Territory[]>([]);
    const [hasPendingRequest, setHasPendingRequest] = useState(false);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [isReportModalOpen, setIsReportModalOpen] = useState(false);
    const [actionLoading, setActionLoading] = useState<string | null>(null);

    useEffect(() => {
        if (!user) {
            setLoading(false);
            return;
        }

        setLoading(true);
        const territoriesQuery = query(collection(db, 'territories'));

        const unsubscribe = onSnapshot(territoriesQuery, (snapshot) => {
            const allTerritories = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Territory));

            const myActiveTerritory = allTerritories.find(t => t.assignedTo === user.id && t.status === TerritoryStatus.IN_USE) || null;
            const availableTerritories = allTerritories.filter(t => t.status === TerritoryStatus.AVAILABLE);
            const myRequestedTerritory = allTerritories.some(t => t.status === TerritoryStatus.REQUESTED && t.assignedTo === user.id)

            setMyTerritory(myActiveTerritory);
            setAvailable(availableTerritories);

            // Check for pending requests separately
            const requestsQuery = query(collection(db, 'requests'), where('userId', '==', user.id), where('status', '==', 'pendente'));
            const unsubRequests = onSnapshot(requestsQuery, (reqSnapshot) => {
                setHasPendingRequest(!reqSnapshot.empty);
            });

            setLoading(false);
            return () => unsubRequests();
        }, (err) => {
            console.error(err);
            setError('Falha ao carregar dados. Tente novamente.');
            setLoading(false);
        });

        return () => unsubscribe();
    }, [user]);

    const handleRequest = async (territory: Territory) => {
        if (!user) return;
        setActionLoading(territory.id);

        const territoryRef = doc(db, 'territories', territory.id);
        const requestsRef = collection(db, 'requests');

        try {
            const batch = writeBatch(db);
            // Update territory status
            batch.update(territoryRef, { status: TerritoryStatus.REQUESTED });

            // Create a new request document
            batch.set(doc(requestsRef), {
                territoryId: territory.id,
                territoryName: territory.name,
                userId: user.id,
                userName: user.name,
                requestDate: serverTimestamp(),
                status: 'pendente'
            });

            await batch.commit();
        } catch (err) {
            console.error(err);
            setError('Não foi possível solicitar o território.');
        } finally {
            setActionLoading(null);
        }
    };

    const handleSubmitReport = async (notes: string) => {
        if (!user || !myTerritory) return;

        const territoryRef = doc(db, 'territories', myTerritory.id);
        const reportsRef = collection(db, 'reports');

        try {
            const batch = writeBatch(db);

            // Update the territory
            batch.update(territoryRef, {
                status: TerritoryStatus.CLOSED,
                assignedTo: null,
                assignedToName: null,
                assignmentDate: null,
                dueDate: null,
                history: [
                    ...myTerritory.history,
                    { userId: user.id, userName: user.name, completedDate: serverTimestamp() }
                ]
            });

            // Create a new report
            batch.set(doc(reportsRef), {
                territoryId: myTerritory.id,
                territoryName: myTerritory.name,
                userId: user.id,
                userName: user.name,
                reportDate: serverTimestamp(),
                notes: notes
            });

            await batch.commit();
            setIsReportModalOpen(false);

        } catch (err) {
            console.error(err);
            setError('Falha ao enviar o relatório.');
        }
    };

    if (loading) {
        return <div className="text-center p-10">Carregando painel...</div>;
    }

    if (error) {
        return <div className="text-center p-10 text-red-500">{error}</div>;
    }

    return (
        <div className="container mx-auto">
            <h1 className="text-3xl font-bold text-gray-800 mb-6">Painel do Publicador</h1>

            {isReportModalOpen && myTerritory && <ReportModal territory={myTerritory} onClose={() => setIsReportModalOpen(false)} onSubmit={handleSubmitReport} />}

            {/* My Territory Section */}
            <section className="mb-8">
                <h2 className="text-2xl font-semibold text-gray-700 mb-4">Meu Território Ativo</h2>
                {myTerritory ? (
                    (() => {
                        const colorInfo = getDeadlineColorInfo(myTerritory.dueDate);
                        const daysRemaining = getDaysRemaining(myTerritory.dueDate) ?? 0;
                        const progress = Math.max(0, 100 - (daysRemaining / 30) * 100);

                        return (
                            <div className={`bg-white rounded-xl shadow-lg overflow-hidden border-l-8 ${colorInfo.bgColor.replace('bg-', 'border-')}`}>
                                <div className="p-6 sm:p-8">
                                    <div className="sm:flex sm:items-start sm:justify-between">
                                        <div>
                                            <h3 className="text-2xl font-bold text-gray-900">{myTerritory.name}</h3>
                                            <p className="text-gray-600 mt-1">Data de vencimento: {formatDate(myTerritory.dueDate)}</p>
                                        </div>
                                        <div className={`mt-4 sm:mt-0 px-3 py-1 text-sm font-bold rounded-full ${colorInfo.bgColor} ${colorInfo.textColor}`}>
                                            {colorInfo.label}
                                        </div>
                                    </div>
                                    <div className="mt-6">
                                        <div className="w-full bg-gray-200 rounded-full h-4">
                                            <div className={`${colorInfo.bgColor} h-4 rounded-full transition-all duration-500`} style={{ width: `${progress}%` }}></div>
                                        </div>
                                    </div>
                                    <div className="mt-6 flex flex-col sm:flex-row gap-4">
                                        <a href={myTerritory.pdfUrl} target="_blank" rel="noopener noreferrer" className="w-full sm:w-auto text-center bg-gray-800 hover:bg-gray-900 text-white font-bold py-3 px-6 rounded-lg transition-colors">
                                            Ver Mapa (PDF)
                                        </a>
                                        <button onClick={() => setIsReportModalOpen(true)} className="w-full sm:w-auto text-center bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-6 rounded-lg transition-colors">
                                            Fechar e Relatar
                                        </button>
                                    </div>
                                </div>
                            </div>
                        )
                    })()
                ) : hasPendingRequest ? (
                    <div className="bg-yellow-100 border-l-4 border-yellow-500 text-yellow-700 p-4 rounded-md" role="alert">
                        <p className="font-bold">Solicitação Enviada</p>
                        <p>Você tem uma solicitação de território pendente. Aguarde a aprovação do administrador.</p>
                    </div>
                ) : (
                    <p className="text-gray-500 bg-gray-100 p-4 rounded-md">Você não tem um território ativo. Solicite um da lista abaixo.</p>
                )}
            </section>

            {/* Available Territories Section */}
            <section>
                <h2 className="text-2xl font-semibold text-gray-700 mb-4">Territórios Disponíveis</h2>
                {(!myTerritory && !hasPendingRequest) ? (
                    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
                        {available.length > 0 ? available.map(t => (
                            <div key={t.id} className="bg-white p-5 rounded-lg shadow-md flex flex-col justify-between">
                                <h3 className="font-bold text-lg mb-4">{t.name}</h3>
                                <button
                                    onClick={() => handleRequest(t)}
                                    disabled={actionLoading === t.id}
                                    className="w-full bg-green-500 hover:bg-green-600 text-white font-semibold py-2 px-4 rounded-lg transition-colors disabled:bg-green-300"
                                >
                                    {actionLoading === t.id ? 'Solicitando...' : 'Solicitar'}
                                </button>
                            </div>
                        )) : (
                            <p className="text-gray-500 col-span-full">Nenhum território disponível no momento.</p>
                        )}
                    </div>
                ) : (
                     <div className="bg-gray-100 p-6 rounded-lg text-center">
                        <p className="text-gray-600">Você precisa fechar seu território atual ou aguardar a aprovação da sua solicitação antes de pedir um novo.</p>
                    </div>
                )}
            </section>
        </div>
    );
};

export default PublisherDashboard;

