};

export const processRequest = async (requestId: string, approve: boolean): Promise<void> => {
    await simulateDelay(700);
    const requestIndex = MOCK_REQUESTS.findIndex(r => r.id === requestId);
    if (requestIndex === -1) throw new Error("Solicitação não encontrada");

    const request = MOCK_REQUESTS[requestIndex];
    const territory = MOCK_TERRITORIES.find(t => t.id === request.territoryId);
    if (!territory) throw new Error("Território não encontrado");

    if (approve) {
        request.status = RequestStatus.APPROVED;
        territory.status = TerritoryStatus.IN_USE;
        territory.assignedTo = request.userId;
        territory.assignedToName = request.userName;
        const assignmentDate = new Date();
        territory.assignmentDate = assignmentDate;
        territory.dueDate = new Date(new Date(assignmentDate).setDate(assignmentDate.getDate() + 30));
    } else {
        request.status = RequestStatus.REJECTED;
        territory.status = TerritoryStatus.AVAILABLE;
    }

    // Move processed request out of pending list
    MOCK_REQUESTS.splice(requestIndex, 1);

    saveToLocalStorage('mock_territories', MOCK_TERRITORIES);
    saveToLocalStorage('mock_requests', MOCK_REQUESTS);
};

