  console.log('User logged out');
};

export const fetchAllTerritories = async (): Promise<Territory[]> => {
  await simulateDelay(800);
  return [...MOCK_TERRITORIES].sort((a,b) => b.createdAt.getTime() - a.createdAt.getTime());
};

export const fetchPublisherData = async (userId: string): Promise<{ myTerritory: Territory | null, availableTerritories: Territory[], hasPendingRequest: boolean }> => {
    await simulateDelay(800);
    const myTerritory = MOCK_TERRITORIES.find(t => t.assignedTo === userId && t.status === TerritoryStatus.IN_USE) || null;
    const availableTerritories = MOCK_TERRITORIES.filter(t => t.status === TerritoryStatus.AVAILABLE);
    const hasPendingRequest = MOCK_REQUESTS.some(r => r.userId === userId && r.status === RequestStatus.PENDING);
    return { myTerritory, availableTerritories, hasPendingRequest };
};

export const requestTerritory = async (territoryId: string, user: User): Promise<void> => {
    await simulateDelay(500);
    const territory = MOCK_TERRITORIES.find(t => t.id === territoryId);
    if (!user || !territory) throw new Error("Usuário ou território não encontrado.");

    territory.status = TerritoryStatus.REQUESTED;
    const newRequest = {
        id: `req${Date.now()}`,
        territoryId: territory.id,
        territoryName: territory.name,
        userId: user.id,
        userName: user.name,
        requestDate: new Date(),
        status: RequestStatus.PENDING
    };
    MOCK_REQUESTS.push(newRequest);
    saveToLocalStorage('mock_territories', MOCK_TERRITORIES);
    saveToLocalStorage('mock_requests', MOCK_REQUESTS);
};

export const fetchAllRequests = async (): Promise<TerritoryRequest[]> => {
    await simulateDelay(600);
    return MOCK_REQUESTS.filter(r => r.status === RequestStatus.PENDING).sort((a,b) => a.requestDate.getTime() - b.requestDate.getTime());
};

export const processRequest = async (requestId: string, approve: boolean): Promise<void> => {
    await simulateDelay(700);
    const requestIndex = MOCK_REQUESTS.findIndex(r => r.id === requestId);
    if (requestIndex === -1) throw new Error("Solicitação não encontrada");

    const request = MOCK_REQUESTS[requestIndex];
    const territory = MOCK_TERRITORIES.find(t => t.id === request.territoryId);
    if (!territory) throw new Error("Território não encontrado");

    if (approve) {
        request.status = RequestStatus.APPROVED;
        territory.status = TerritoryStatus.IN_USE;
        territory.assignedTo = request.userId;
        territory.assignedToName = request.userName;
        const assignmentDate = new Date();
        territory.assignmentDate = assignmentDate;
        territory.dueDate = new Date(new Date(assignmentDate).setDate(assignmentDate.getDate() + 30));
    } else {
        request.status = RequestStatus.REJECTED;
        territory.status = TerritoryStatus.AVAILABLE;
    }

    // Move processed request out of pending list
    MOCK_REQUESTS.splice(requestIndex, 1);

    saveToLocalStorage('mock_territories', MOCK_TERRITORIES);
    saveToLocalStorage('mock_requests', MOCK_REQUESTS);
};

export const submitReport = async (user: User, territory: Territory, notes: string): Promise<void> => {
    await simulateDelay(700);

    MOCK_REPORTS.push({
        id: `rep${Date.now()}`,
        territoryId: territory.id,
        territoryName: territory.name,
        userId: user.id,
        userName: user.name,
        reportDate: new Date(),
        notes: notes
    });

    const territoryToUpdate = MOCK_TERRITORIES.find(t => t.id === territory.id);
    if(!territoryToUpdate) throw new Error("Território não encontrado para fechar.");

    territoryToUpdate.status = TerritoryStatus.CLOSED;
    territoryToUpdate.history.push({ userId: user.id, userName: user.name, completedDate: new Date() });
    territoryToUpdate.assignedTo = null;
    territoryToUpdate.assignedToName = null;
    territoryToUpdate.assignmentDate = null;
    territoryToUpdate.dueDate = null;

    saveToLocalStorage('mock_territories', MOCK_TERRITORIES);
    saveToLocalStorage('mock_reports', MOCK_REPORTS);
};

export const uploadTerritory = async (name: string, file: File): Promise<void> => {
    await simulateDelay(1000);
    const pdfUrl = await fileToDataUrl(file);
    const newTerritory: Territory = {
        id: `t${Date.now()}`,
        name: name,
        status: TerritoryStatus.AVAILABLE,
        pdfUrl: pdfUrl,
        createdAt: new Date(),
        history: []
    };
    MOCK_TERRITORIES.unshift(newTerritory);
    saveToLocalStorage('mock_territories', MOCK_TERRITORIES);
};

export const updateTerritory = async (territoryId: string, newName: string): Promise<void> => {
    await simulateDelay(600);
    const territory = MOCK_TERRITORIES.find(t => t.id === territoryId);
    if (territory) {
        territory.name = newName;
        saveToLocalStorage('mock_territories', MOCK_TERRITORIES);
    } else {
        throw new Error("Território não encontrado para atualização.");
    }
};

export const deleteTerritory = async (territoryId: string): Promise<void> => {
    await simulateDelay(500);
    const index = MOCK_TERRITORIES.findIndex(t => t.id === territoryId);
    if (index > -1) {
        MOCK_TERRITORIES.splice(index, 1);
        saveToLocalStorage('mock_territories', MOCK_TERRITORIES);
    } else {
        throw new Error("Território não encontrado para exclusão.");
    }
};

