export const fetchAllTerritories = async (): Promise<Territory[]> => {
  await simulateDelay(800);
  return [...MOCK_TERRITORIES].sort((a,b) => b.createdAt.getTime() - a.createdAt.getTime());
};

export const fetchPublisherData = async (userId: string): Promise<{ myTerritory: Territory | null, hasPendingRequest: boolean }> => {
    await simulateDelay(800);
    const myTerritory = MOCK_TERRITORIES.find(t => t.assignedTo === userId && t.status === TerritoryStatus.IN_USE) || null;
    const hasPendingRequest = MOCK_REQUESTS.some(r => r.userId === userId && r.status === RequestStatus.PENDING);
    return { myTerritory, hasPendingRequest };
};

export const requestTerritory = async (user: User): Promise<void> => {
    await simulateDelay(500);
    if (!user) throw new Error("Usuário não encontrado.");
    if (MOCK_REQUESTS.some(r => r.userId === user.id && r.status === RequestStatus.PENDING)) {
        throw new Error("Você já tem uma solicitação pendente.");
    }
    const newRequest: TerritoryRequest = {
        id: `req${Date.now()}`,
        userId: user.id,
        userName: user.name,
        requestDate: new Date(),
        status: RequestStatus.PENDING
    };
    MOCK_REQUESTS.push(newRequest);
    saveToLocalStorage('mock_requests', MOCK_REQUESTS);
};

export const fetchAllRequests = async (): Promise<TerritoryRequest[]> => {
    await simulateDelay(600);
    return MOCK_REQUESTS.filter(r => r.status === RequestStatus.PENDING).sort((a,b) => a.requestDate.getTime() - b.requestDate.getTime());
};

export const assignTerritoryToRequest = async (requestId: string, territoryId: string): Promise<void> => {
    await simulateDelay(700);
    const requestIndex = MOCK_REQUESTS.findIndex(r => r.id === requestId);
    if (requestIndex === -1) throw new Error("Solicitação não encontrada");

    const request = MOCK_REQUESTS[requestIndex];
    const territory = MOCK_TERRITORIES.find(t => t.id === territoryId);
    if (!territory) throw new Error("Território não encontrado");
    if (territory.status !== TerritoryStatus.AVAILABLE) throw new Error("Este território não está disponível para atribuição.");

    territory.status = TerritoryStatus.IN_USE;
    territory.assignedTo = request.userId;
    territory.assignedToName = request.userName;
    const assignmentDate = new Date();
    territory.assignmentDate = assignmentDate;
    territory.dueDate = new Date(new Date(assignmentDate).setDate(assignmentDate.getDate() + 30));

    MOCK_REQUESTS.splice(requestIndex, 1);

    saveToLocalStorage('mock_territories', MOCK_TERRITORIES);
    saveToLocalStorage('mock_requests', MOCK_REQUESTS);
};

export const rejectRequest = async (requestId: string): Promise<void> => {
    await simulateDelay(500);
    const requestIndex = MOCK_REQUESTS.findIndex(r => r.id === requestId);
    if (requestIndex === -1) throw new Error("Solicitação não encontrada");

    MOCK_REQUESTS.splice(requestIndex, 1);
    saveToLocalStorage('mock_requests', MOCK_REQUESTS);
}


export const submitReport = async (user: User, territory: Territory, notes: string): Promise<void> => {
    await simulateDelay(700);

    MOCK_REPORTS.push({
        id: `rep${Date.now()}`,
        territoryId: territory.id,
        territoryName: territory.name,
        userId: user.id,
        userName: user.name,
        reportDate: new Date(),
        notes: notes
    });

    const territoryToUpdate = MOCK_TERRITORIES.find(t => t.id === territory.id);
    if(!territoryToUpdate) throw new Error("Território não encontrado para fechar.");

    territoryToUpdate.status = TerritoryStatus.CLOSED;
    territoryToUpdate.history.push({ userId: user.id, userName: user.name, completedDate: new Date(), notes: notes });
    territoryToUpdate.assignedTo = null;
    territoryToUpdate.assignedToName = null;
    territoryToUpdate.assignmentDate = null;
    territoryToUpdate.dueDate = null;

    saveToLocalStorage('mock_territories', MOCK_TERRITORIES);
    saveToLocalStorage('mock_reports', MOCK_REPORTS);
};

export const uploadTerritory = async (name: string, file: File): Promise<void> => {
    await simulateDelay(1000);
    const pdfUrl = await fileToDataUrl(file);
    const newTerritory: Territory = {
        id: `t${Date.now()}`,
        name: name,
        status: TerritoryStatus.AVAILABLE,
        pdfUrl: pdfUrl,
        createdAt: new Date(),
        history: []
    };
    MOCK_TERRITORIES.unshift(newTerritory);
    saveToLocalStorage('mock_territories', MOCK_TERRITORIES);
};

export const updateTerritory = async (territoryId: string, data: { name?: string; permanentNotes?: string; }): Promise<void> => {
    await simulateDelay(600);
    const territory = MOCK_TERRITORIES.find(t => t.id === territoryId);
    if (territory) {
        if(data.name) territory.name = data.name;
        if(data.permanentNotes !== undefined) territory.permanentNotes = data.permanentNotes;
        saveToLocalStorage('mock_territories', MOCK_TERRITORIES);
    } else {
        throw new Error("Território não encontrado para atualização.");
    }
};

export const deleteTerritory = async (territoryId: string): Promise<void> => {
    await simulateDelay(500);
    const index = MOCK_TERRITORIES.findIndex(t => t.id === territoryId);
    if (index > -1) {
        MOCK_TERRITORIES.splice(index, 1);
        saveToLocalStorage('mock_territories', MOCK_TERRITORIES);
    } else {
        throw new Error("Território não encontrado para exclusão.");
    }
};

// --- NOTIFICATIONS API ---
const generateNotifications = (user: User) => {
    const adminUser = MOCK_USERS.find(u => u.role === 'admin');
    if (!adminUser) return;

    if (user.role === 'admin') {
        MOCK_REQUESTS.forEach(req => {
            const notificationId = `notif_req_${req.id}`;
            if (!MOCK_NOTIFICATIONS.some(n => n.id === notificationId)) {
                MOCK_NOTIFICATIONS.push({
                    id: notificationId,
                    message: `${req.userName} solicitou um novo território.`,
                    type: 'info',
                    read: false,
                    createdAt: req.requestDate
                });
            }
        });
    }

    const userTerritories = MOCK_TERRITORIES.filter(t => t.assignedTo === user.id);
    userTerritories.forEach(t => {
        const daysRemaining = getDaysRemaining(t.dueDate);
        if (daysRemaining !== null && daysRemaining <= 7) {
            const notificationId = `notif_due_${t.id}_${daysRemaining}`;
             if (!MOCK_NOTIFICATIONS.some(n => n.id === notificationId)) {
                 MOCK_NOTIFICATIONS.push({
                    id: notificationId,
                    message: `Seu território "${t.name}" vence em ${daysRemaining} dia(s).`,
                    type: daysRemaining <= 0 ? 'warning' : 'info',
                    read: false,
                    createdAt: new Date()
                });
             }
        }
    });

    saveToLocalStorage('mock_notifications', MOCK_NOTIFICATIONS);
};


export const fetchNotifications = async (user: User): Promise<Notification[]> => {
    await simulateDelay(300);
    generateNotifications(user); // Simulate real-time generation

    let userNotifications: Notification[];
    if (user.role === 'admin') {
        // Admin sees all notifications
        userNotifications = [...MOCK_NOTIFICATIONS];
    } else {
        // Publisher only sees notifications about their territories
        const territoryIds = MOCK_TERRITORIES.filter(t => t.assignedTo === user.id).map(t => t.id);
        userNotifications = MOCK_NOTIFICATIONS.filter(n => territoryIds.some(tId => n.id.includes(tId)));
    }

    return userNotifications.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
};

export const markNotificationsAsRead = async (notificationIds: string[]): Promise<void> => {
    await simulateDelay(200);
    MOCK_NOTIFICATIONS.forEach(n => {
        if (notificationIds.includes(n.id)) {
            n.read = true;
        }
    });
    saveToLocalStorage('mock_notifications', MOCK_NOTIFICATIONS);
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useAuth } from '../hooks/useAuth';
