const simulateDelay = (ms: number) => new Promise(res => setTimeout(res, ms));

export const apiLogin = async (email: string, pass: string): Promise<User> => {
  await simulateDelay(500);
  const user = MOCK_USERS.find(u => u.email === email);
  if (user && pass === '123456') { // Simple password check
    return { ...user };
  }
  throw new Error('Credenciais inválidas');
};

export const apiSignUp = async (name: string, email: string, pass: string): Promise<User> => {
    await simulateDelay(600);
    if (!MOCK_AUTHORIZED_EMAILS.includes(email)) {
        throw new Error("Seu email não está autorizado. Entre em contato com o responsável pelo território.");
    }
    if (MOCK_USERS.some(u => u.email === email)) {
        throw new Error("Este email já está em uso.");
    }

    const role = email === 'admin@example.com' ? 'admin' : 'publicador';

    const newUser: User = {
        id: `user${Date.now()}`,
        name: name,
        email: email,
