// Import the functions you need from the SDKs you need
import { initializeApp } from "firebase/app";
import { getFirestore } from "firebase/firestore";
import { getAuth } from "firebase/auth";
import { getStorage } from "firebase/storage";

// TODO: Add SDKs for Firebase products that you want to use
// https://firebase.google.com/docs/web/setup#available-libraries

// Your web app's Firebase configuration
// ATENÇÃO: Substitua este objeto pelas credenciais do seu projeto no Firebase Console
const firebaseConfig = {
  apiKey: "SUA_API_KEY",
  authDomain: "SEU_AUTH_DOMAIN",
  projectId: "SEU_PROJECT_ID",
  storageBucket: "SEU_STORAGE_BUCKET",
  messagingSenderId: "SEU_MESSAGING_SENDER_ID",
  appId: "SEU_APP_ID"
};

// Initialize Firebase
const app = initializeApp(firebaseConfig);

export const db = getFirestore(app);
export const auth = getAuth(app);
export const storage = getStorage(app);

import { auth, db, storage } from '../firebase/config';
import { 
    createUserWithEmailAndPassword, 
    signInWithEmailAndPassword, 
    signOut 
} from "firebase/auth";
import { 
    collection, 
    doc, 
    getDoc, 
    setDoc, 
    addDoc, 
    getDocs, 
    query, 
    where, 
    Timestamp,
    orderBy,
    updateDoc,
    deleteDoc,
    writeBatch
} from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL, deleteObject } from "firebase/storage";
import { User, Territory, TerritoryStatus, RequestStatus, TerritoryRequest, Report, Notification, TerritoryHistory } from '../types';

// --- AUTH FUNCTIONS ---

export const apiLogin = async (email: string, pass: string): Promise<User> => {
    const userCredential = await signInWithEmailAndPassword(auth, email, pass);
    const userDoc = await getDoc(doc(db, "users", userCredential.user.uid));
    if (!userDoc.exists()) {
        throw new Error("Perfil de usuário não encontrado.");
    }
    return { id: userCredential.user.uid, ...userDoc.data() } as User;
};

export const apiSignUp = async (name: string, email: string, pass: string): Promise<User> => {
    const userCredential = await createUserWithEmailAndPassword(auth, email, pass);
    const role = email === 'admin@example.com' ? 'admin' : 'publicador'; // Simple role assignment
    const newUser: Omit<User, 'id'> = {
        name,
        email,
        role,
    };
    await setDoc(doc(db, "users", userCredential.user.uid), newUser);
    return { id: userCredential.user.uid, ...newUser };
};

export const apiLogout = async (): Promise<void> => {
    await signOut(auth);
};


// --- DATA TRANSFORMATION ---
const fromFirestoreToTerritory = (doc: any): Territory => {
    const data = doc.data();
    return {
        ...data,
        id: doc.id,
        createdAt: (data.createdAt as Timestamp)?.toDate(),
        assignmentDate: (data.assignmentDate as Timestamp)?.toDate(),
        dueDate: (data.dueDate as Timestamp)?.toDate(),
        history: data.history?.map((h: any) => ({
            ...h,
            completedDate: (h.completedDate as Timestamp)?.toDate(),
        })) || [],
    } as Territory;
}


// --- TERRITORY FUNCTIONS ---

export const fetchAllTerritories = async (): Promise<Territory[]> => {
    // Cooldown logic
    const now = Timestamp.now();
    const sixtyDaysAgo = new Timestamp(now.seconds - (60 * 24 * 60 * 60), now.nanoseconds);

    const q = query(
        collection(db, "territories"),
        where("status", "==", TerritoryStatus.CLOSED),
        where("history.0.completedDate", "<", sixtyDaysAgo)
    );

    const querySnapshot = await getDocs(q);
    const batch = writeBatch(db);
    querySnapshot.forEach(docSnap => {
        batch.update(docSnap.ref, { status: TerritoryStatus.AVAILABLE });
    });
    await batch.commit();

    // Fetch all territories again after update
    const allTerritoriesSnapshot = await getDocs(query(collection(db, "territories"), orderBy("createdAt", "desc")));
    return allTerritoriesSnapshot.docs.map(fromFirestoreToTerritory);
};


export const uploadTerritory = async (name: string, file: File): Promise<void> => {
    const storageRef = ref(storage, `territories/${Date.now()}_${file.name}`);
    const uploadResult = await uploadBytes(storageRef, file);
    const pdfUrl = await getDownloadURL(uploadResult.ref);

    const newTerritory = {
        name,
        pdfUrl,
        status: TerritoryStatus.AVAILABLE,
        createdAt: Timestamp.now(),
        history: [],
        assignedTo: null,
        assignedToName: null,
        assignmentDate: null,
        dueDate: null,
        permanentNotes: ""
    };
    await addDoc(collection(db, "territories"), newTerritory);
};


export const fetchPublisherData = async (userId: string): Promise<{ myTerritory: Territory | null, hasPendingRequest: boolean }> => {
    const territoryQuery = query(
        collection(db, "territories"),
        where("assignedTo", "==", userId),
        where("status", "==", TerritoryStatus.IN_USE)
    );

    const requestQuery = query(
        collection(db, "requests"),
        where("userId", "==", userId),
        where("status", "==", RequestStatus.PENDING)
    );

    const [territorySnapshot, requestSnapshot] = await Promise.all([
        getDocs(territoryQuery),
        getDocs(requestQuery)
    ]);

    const myTerritory = territorySnapshot.empty ? null : fromFirestoreToTerritory(territorySnapshot.docs[0]);
    const hasPendingRequest = !requestSnapshot.empty;

    return { myTerritory, hasPendingRequest };
};

export const submitReport = async (user: User, territory: Territory, notes: string): Promise<void> => {
    const territoryRef = doc(db, "territories", territory.id);

    const newHistoryEntry: TerritoryHistory = {
        userId: user.id,
        userName: user.name,
        completedDate: new Date(),
        notes
    };

    // Add to history array (note: Firestore doesn't have a simple array push, you replace the array)
    const updatedHistory = [newHistoryEntry, ...territory.history];

    await updateDoc(territoryRef, {
        status: TerritoryStatus.CLOSED,
        assignedTo: null,
        assignedToName: null,
        assignmentDate: null,
        dueDate: null,
        history: updatedHistory
    });
};


export const updateTerritory = async (territoryId: string, data: { name?: string; permanentNotes?: string; }): Promise<void> => {
    const territoryRef = doc(db, "territories", territoryId);
    await updateDoc(territoryRef, data);
};

export const deleteTerritory = async (territoryId: string): Promise<void> => {
    // Note: You might want to delete the PDF from Storage as well
    const territoryRef = doc(db, "territories", territoryId);
    await deleteDoc(territoryRef);
};


// --- REQUEST FUNCTIONS ---

export const requestTerritory = async (user: User): Promise<void> => {
    // Check for existing pending requests for this user
    const q = query(collection(db, "requests"), where("userId", "==", user.id), where("status", "==", RequestStatus.PENDING));
    const existingRequests = await getDocs(q);
    if (!existingRequests.empty) {
        throw new Error("Você já tem uma solicitação pendente.");
    }

    const newRequest = {
        userId: user.id,
        userName: user.name,
        requestDate: Timestamp.now(),
        status: RequestStatus.PENDING
    };
    await addDoc(collection(db, "requests"), newRequest);
};


export const fetchAllRequests = async (): Promise<TerritoryRequest[]> => {
    const q = query(collection(db, "requests"), where("status", "==", RequestStatus.PENDING), orderBy("requestDate", "asc"));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data(),
        requestDate: (doc.data().requestDate as Timestamp).toDate(),
    } as TerritoryRequest));
};

export const assignTerritoryToRequest = async (requestId: string, territoryId: string): Promise<void> => {
    const requestRef = doc(db, "requests", requestId);
    const territoryRef = doc(db, "territories", territoryId);

    const requestDoc = await getDoc(requestRef);
    if (!requestDoc.exists()) throw new Error("Solicitação não encontrada");
    const requestData = requestDoc.data();

    const assignmentDate = Timestamp.now();
    const dueDate = new Timestamp(assignmentDate.seconds + (30 * 24 * 60 * 60), assignmentDate.nanoseconds);

    const batch = writeBatch(db);
    batch.update(territoryRef, {
        status: TerritoryStatus.IN_USE,
        assignedTo: requestData.userId,
        assignedToName: requestData.userName,
        assignmentDate,
        dueDate
    });
    batch.delete(requestRef);

    await batch.commit();
};

export const rejectRequest = async (requestId: string): Promise<void> => {
    await deleteDoc(doc(db, "requests", requestId));
};


// --- NOTIFICATION FUNCTIONS (Simplified for Firebase) ---

export const fetchNotifications = async (user: User): Promise<Notification[]> => {
    // This would be more robust with Cloud Functions to generate notifications.
    // Here's a simplified client-side simulation.
    let notifications: Notification[] = [];
    if (user.role === 'admin') {
        const requests = await fetchAllRequests();
        requests.forEach(req => {
            notifications.push({
                id: `notif_req_${req.id}`,
                message: `${req.userName} solicitou um novo território.`,
                type: 'info',
                read: false, // In a real app, 'read' status would be stored in Firestore
                createdAt: req.requestDate
            });
        });
    }

    const territoryQuery = query(
        collection(db, "territories"),
        where("assignedTo", "==", user.id),
        where("status", "==", TerritoryStatus.IN_USE)
    );
    const territorySnapshot = await getDocs(territoryQuery);
    territorySnapshot.forEach(doc => {
        const territory = fromFirestoreToTerritory(doc);
        const dueDate = territory.dueDate;
        if(dueDate) {
            const daysRemaining = Math.ceil((dueDate.getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24));
            if (daysRemaining <= 7) {
                 notifications.push({
                    id: `notif_due_${territory.id}`,
                    message: `Seu território "${territory.name}" vence em ${daysRemaining} dia(s).`,
                    type: daysRemaining <= 0 ? 'warning' : 'info',
                    read: false,
                    createdAt: new Date()
                });
            }
        }
    });

    return notifications.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
};

// This is just a mock as we are not storing notification status
export const markNotificationsAsRead = async (notificationIds: string[]): Promise<void> => {
    console.log("Marked as read (client-side):", notificationIds);
    return Promise.resolve();
};

import React, { createContext, useState, useEffect, useContext, ReactNode } from 'react';
import { User } from '../types';
import { apiLogin, apiLogout, apiSignUp } from '../services/api';
import { auth, db } from '../firebase/config';
import { onAuthStateChanged, User as FirebaseUser } from 'firebase/auth';
import { doc, getDoc } from 'firebase/firestore';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, pass: string) => Promise<void>;
  logout: () => Promise<void>;
  signUp: (name: string, email: string, pass: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser: FirebaseUser | null) => {
      if (firebaseUser) {
        // User is signed in, get their profile from Firestore
        const userDocRef = doc(db, 'users', firebaseUser.uid);
        const userDoc = await getDoc(userDocRef);
        if (userDoc.exists()) {
          setUser({ id: firebaseUser.uid, ...userDoc.data() } as User);
        } else {
          // Profile doesn't exist, something is wrong. Log them out.
          await apiLogout();
          setUser(null);
        }
      } else {
        // User is signed out
        setUser(null);
      }
      setLoading(false);
    });

    // Cleanup subscription on unmount
    return () => unsubscribe();
  }, []);


  const login = async (email: string, pass: string) => {
    await apiLogin(email, pass);
    // onAuthStateChanged will handle setting the user state
  };

  const logout = async () => {
    await apiLogout();
     // onAuthStateChanged will handle setting the user state
  };

  const signUp = async (name: string, email: string, pass: string) => {
    await apiSignUp(name, email, pass);
     // onAuthStateChanged will handle setting the user state
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, signUp }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

const CACHE_NAME = 'territory-manager-v1';
const urlsToCache = [
  '/',
  '/index.html',
  // Adicione aqui outros arquivos estáticos que você queira cachear
  // Ex: '/styles.css', '/icon.svg'
  // Os scripts do esm.sh e tailwind são carregados de CDN, então não os colocamos aqui.
];

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => {
        console.log('Opened cache');
        return cache.addAll(urlsToCache);
      })
  );
});

self.addEventListener('fetch', event => {
  event.respondWith(
    caches.match(event.request)
      .then(response => {
        // Cache hit - return response
        if (response) {
          return response;
        }

        return fetch(event.request).then(
          response => {
            // Check if we received a valid response
            if(!response || response.status !== 200 || response.type !== 'basic') {
              return response;
            }

            // IMPORTANT: Clone the response. A response is a stream
            // and because we want the browser to consume the response
            // as well as the cache consuming the response, we need
            // to clone it so we have two streams.
            const responseToCache = response.clone();

            caches.open(CACHE_NAME)
              .then(cache => {
                cache.put(event.request, responseToCache);
              });

            return response;
          }
        );
      })
    );
});

self.addEventListener('activate', event => {
  const cacheWhitelist = [CACHE_NAME];
  event.waitUntil(
    caches.keys().then(cacheNames => {
      return Promise.all(
        cacheNames.map(cacheName => {
          if (cacheWhitelist.indexOf(cacheName) === -1) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
});

