// Supabase dates are ISO strings. We need to convert them to Date objects.
const fromSupabaseToTerritory = (data: any): Territory => ({
    ...data,
    created_at: new Date(data.created_at),
    assignment_date: data.assignment_date ? new Date(data.assignment_date) : null,
    due_date: data.due_date ? new Date(data.due_date) : null,
    history: data.history?.map((h: any) => ({
        ...h,
        completedDate: new Date(h.completedDate),
    })) || [],
});

