export const fetchAllTerritories = async (): Promise<Territory[]> => {
    // Cooldown logic
    const sixtyDaysAgo = new Date(Date.now() - 60 * 24 * 60 * 60 * 1000).toISOString();

    const { error: updateError } = await supabase
        .from('territories')
        .update({ status: TerritoryStatus.AVAILABLE })
        .eq('status', TerritoryStatus.CLOSED)
        .lt('history[0]->>completedDate', sixtyDaysAgo); // Note: This query assumes history is not null and has at least one entry.

    if (updateError) console.error("Error updating territory cooldown:", updateError.message);

    // Fetch all territories
    const { data, error } = await supabase
        .from('territories')
        .select('*')
        .order('created_at', { ascending: false });

    if (error) throw new Error(error.message);
    return data.map(fromSupabaseToTerritory);
};

