        .select('name, email, role')
        .eq('auth_id', authUserId)
        .single();

    if (error) {
        console.error("Error fetching user profile:", error);
        return null;
    }
    return data;
};

# Gerenciador de Territórios da Congregação

Sistema PWA integrado com Supabase para gerenciamento de territórios.

## 🚀 Configuração Rápida (SQL Supabase)

Para o sistema funcionar, vá ao painel do seu projeto Supabase, clique em **SQL Editor** e execute o script abaixo:

```sql
-- 1. Tabela de Perfis de Usuários
CREATE TABLE users (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  auth_id uuid UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE,
  name text NOT NULL,
  email text NOT NULL,
  role text DEFAULT 'publicador' CHECK (role IN ('admin', 'publicador'))
);

-- 2. Tabela de Territórios
CREATE TABLE territories (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  status text DEFAULT 'disponivel',
  pdf_url text,
  created_at timestamptz DEFAULT now(),
  assigned_to uuid REFERENCES users(id),
  assigned_to_name text,
  assignment_date timestamptz,
  due_date timestamptz,
  history jsonb DEFAULT '[]'::jsonb,
  permanent_notes text
);

-- 3. Tabela de Solicitações
CREATE TABLE requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid REFERENCES users(id) ON DELETE CASCADE,
  user_name text NOT NULL,
  request_date timestamptz DEFAULT now(),
  status text DEFAULT 'pendente'
);

-- 4. Habilitar Segurança (RLS)
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
ALTER TABLE territories ENABLE ROW LEVEL SECURITY;
ALTER TABLE requests ENABLE ROW LEVEL SECURITY;

-- 5. Políticas de Segurança (Exemplos Básicos)
-- Territórios: Todos podem ler, apenas admins escrevem
CREATE POLICY "Leitura pública para autenticados" ON territories FOR SELECT USING (auth.role() = 'authenticated');
CREATE POLICY "Admin pode tudo nos territórios" ON territories ALL USING (
  EXISTS (SELECT 1 FROM users WHERE auth_id = auth.uid() AND role = 'admin')
);

-- Usuários: Ler próprio perfil
CREATE POLICY "Usuário lê próprio perfil" ON users FOR SELECT USING (auth_id = auth.uid());
CREATE POLICY "Admin lê todos perfis" ON users FOR SELECT USING (
  EXISTS (SELECT 1 FROM users WHERE auth_id = auth.uid() AND role = 'admin')
);

-- Solicitações: Publicador cria e lê as suas, Admin vê todas e deleta
CREATE POLICY "Publicador cria solicitações" ON requests FOR INSERT WITH CHECK (auth.role() = 'authenticated');
CREATE POLICY "Usuário vê suas solicitações" ON requests FOR SELECT USING (user_id IN (SELECT id FROM users WHERE auth_id = auth.uid()));
CREATE POLICY "Admin gerencia solicitações" ON requests ALL USING (
  EXISTS (SELECT 1 FROM users WHERE auth_id = auth.uid() AND role = 'admin')
);

-- 6. Bucket de Storage (Configure via interface do Supabase)
-- Crie um bucket chamado 'maps' e defina como PUBLIC.
```

## Como Instalar no Celular
Como é um PWA, basta abrir a URL no navegador do celular (Chrome no Android ou Safari no iOS) e clicar em **"Adicionar à tela de início"**. O ícone do mapa colorido aparecerá como um aplicativo nativo.

