// --- AUTH FUNCTIONS ---

export const apiLogin = async (email: string, pass: string): Promise<void> => {
    const { error } = await supabase.auth.signInWithPassword({ email, password: pass });
    if (error) throw new Error(error.message);
};

export const apiSignUp = async (name: string, email: string, pass: string): Promise<void> => {
    const { data: authData, error: authError } = await supabase.auth.signUp({ 
        email, 
        password: pass 
    });

    if (authError) throw new Error(authError.message);
    if (!authData.user) throw new Error("Cadastro falhou, usuário não criado.");

    const { count } = await supabase
        .from('users')
        .select('*', { count: 'exact', head: true });

    const role = (count === 0 || email.toLowerCase() === 'admin@example.com') ? 'admin' : 'publicador';

    const { error: profileError } = await supabase
        .from('users')
        .insert({
            auth_id: authData.user.id,
            name,
            email: email.toLowerCase(),
            role
        });

    if (profileError) {
        console.error("Erro ao criar perfil:", profileError);
    }
};

export const apiLogout = async (): Promise<void> => {
    const { error } = await supabase.auth.signOut();
    if (error) throw new Error(error.message);
};

// --- AI FUNCTIONS ---

export const generateAppIllustration = async (): Promise<string | null> => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: {
                parts: [
                    {
                        text: 'A clean, modern, high-quality isometric 3D illustration of a city map with stylized territory markers in blue and green. Professional aesthetic, soft lighting, minimalist background, suitable for a mobile app dashboard. High resolution, 4k, digital art style.',
                    },
                ],
            },
            config: {
                imageConfig: {
                    aspectRatio: "1:1"
                }
            },
        });

        for (const part of response.candidates[0].content.parts) {
            if (part.inlineData) {
                return `data:image/png;base64,${part.inlineData.data}`;
            }
        }
        return null;
    } catch (error) {
        console.error("Error generating AI image:", error);
        return null;
    }
};

