const ReportModal: React.FC<{ territory: Territory; onClose: () => void; onSubmit: (notes: string) => Promise<void>; }> = ({ territory, onClose, onSubmit }) => {
    const [notes, setNotes] = useState('');
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        await onSubmit(notes);
        setLoading(false);
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-lg p-6 sm:p-8 w-full max-w-lg shadow-xl">
                <h2 className="text-2xl font-bold mb-2 text-gray-800">Fechar Território: {territory.name}</h2>
                <p className="text-gray-600 mb-6">Por favor, preencha o relatório para fechar este território.</p>
                <form onSubmit={handleSubmit}>
                    <div className="mb-4">
                        <label htmlFor="report-notes" className="block text-gray-700 text-sm font-bold mb-2">Observações</label>
                        <textarea
                            id="report-notes"
                            value={notes}
                            onChange={e => setNotes(e.target.value)}
                            required
                            rows={4}
                            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 bg-gray-50 leading-tight focus:outline-none focus:shadow-outline"
                            placeholder="Descreva o trabalho realizado, anote 'não trabalhados', etc. Estas notas ficarão visíveis para o próximo publicador."
                        />
                    </div>
                    <div className="flex items-center justify-end gap-4 mt-8">
                        <button type="button" onClick={onClose} className="bg-gray-500 hover:bg-gray-600 text-white font-bold py-2 px-4 rounded-lg transition-colors">Cancelar</button>
                        <button type="submit" disabled={loading} className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded-lg transition-colors disabled:bg-blue-300">
                            {loading ? 'Enviando...' : 'Enviar Relatório e Fechar'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

const PublisherDashboard: React.FC = () => {
    const { user } = useAuth();
    const [myTerritory, setMyTerritory] = useState<Territory | null>(null);
    const [hasPendingRequest, setHasPendingRequest] = useState(false);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [isReportModalOpen, setIsReportModalOpen] = useState(false);
    const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
    const [actionLoading, setActionLoading] = useState(false);

    const fetchData = useCallback(async () => {
        if (!user) return;
        setError('');
        try {
            const { myTerritory, hasPendingRequest } = await fetchPublisherData(user.id);
            setMyTerritory(myTerritory);
            setHasPendingRequest(hasPendingRequest);
        } catch (err) {
            setError('Falha ao carregar os dados. Tente novamente mais tarde.');
        } finally {
            setLoading(false);
        }
    }, [user]);

    useEffect(() => {
        setLoading(true);
        fetchData();
    }, [fetchData]);

    const handleRequest = async () => {
        if (!user) return;
        setActionLoading(true);
        try {
            await requestTerritory(user);
            await fetchData();
        } catch (err: any) {
            console.error(err);
            setError(err.message || 'Não foi possível solicitar o território.');
        } finally {
            setActionLoading(false);
        }
    };

    const handleSubmitReport = async (notes: string) => {
        if (!user || !myTerritory) return;
        try {
            await submitReport(user, myTerritory, notes);
            setIsReportModalOpen(false);
            await fetchData();
        } catch (err) {
            console.error(err);
            setError('Falha ao enviar o relatório.');
        }
    };

    const handleShareWhatsApp = () => {
        if (!myTerritory) return;
        const message = `Olá! Segue o mapa do território "${myTerritory.name}" para o trabalho de campo:\n\nLink do Mapa: ${myTerritory.pdfUrl}\n\nPor favor, utilize este link para visualizar o território.`;
        const whatsappUrl = `https://wa.me/?text=${encodeURIComponent(message)}`;
        window.open(whatsappUrl, '_blank');
    };

    if (loading) {
        return <div className="text-center p-10">Carregando painel...</div>;
    }

    return (
        <div className="container mx-auto">
            <h1 className="text-3xl font-bold text-gray-800 mb-6">Painel do Publicador</h1>

            {error && <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 rounded-md mb-6" role="alert">{error}</div>}

            {isReportModalOpen && myTerritory && <ReportModal territory={myTerritory} onClose={() => setIsReportModalOpen(false)} onSubmit={handleSubmitReport} />}
            {isHistoryModalOpen && myTerritory && <TerritoryHistoryModal territory={myTerritory} onClose={() => setIsHistoryModalOpen(false)} />}

            {/* My Territory Section */}
            <section className="mb-8">
                <h2 className="text-2xl font-semibold text-gray-700 mb-4">Meu Território Ativo</h2>
                {myTerritory ? (
                    (() => {
                        const colorInfo = getDeadlineColorInfo(myTerritory.dueDate);
                        const daysRemaining = getDaysRemaining(myTerritory.dueDate) ?? 0;
                        const progress = Math.max(0, 100 - (daysRemaining / 30) * 100);

                        return (
                            <div className={`bg-white rounded-xl shadow-lg overflow-hidden border-l-8 ${colorInfo.bgColor.replace('bg-', 'border-')}`}>
                                <div className="p-6 sm:p-8">
                                    <div className="sm:flex sm:items-start sm:justify-between">
                                        <div>
                                            <h3 className="text-2xl font-bold text-gray-900">{myTerritory.name}</h3>
                                            <p className="text-gray-600 mt-1">Data de vencimento: {formatDate(myTerritory.dueDate)}</p>
                                        </div>
                                        <div className={`mt-4 sm:mt-0 px-3 py-1 text-sm font-bold rounded-full ${colorInfo.bgColor} ${colorInfo.textColor}`}>
                                            {colorInfo.label}
                                        </div>
                                    </div>

                                    {myTerritory.permanentNotes && (
                                        <div className="mt-4 text-sm text-yellow-800 bg-yellow-100 p-3 rounded-lg">
                                            <strong className="font-bold">Nota Permanente do Território:</strong> {myTerritory.permanentNotes}
                                        </div>
                                    )}

                                    <div className="mt-6">
                                        <div className="w-full bg-gray-200 rounded-full h-4">
                                            <div className={`${colorInfo.bgColor} h-4 rounded-full transition-all duration-500`} style={{ width: `${progress}%` }}></div>
                                        </div>
                                    </div>
                                    <div className="mt-6 grid grid-cols-1 sm:grid-cols-2 gap-4">
                                        <a href={myTerritory.pdfUrl} target="_blank" rel="noopener noreferrer" className="text-center bg-gray-800 hover:bg-gray-900 text-white font-bold py-3 px-6 rounded-lg transition-colors flex items-center justify-center gap-2">
                                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7" />
                                            </svg>
                                            Ver Mapa (PDF)
                                        </a>
                                        <button onClick={handleShareWhatsApp} className="text-center bg-green-500 hover:bg-green-600 text-white font-bold py-3 px-6 rounded-lg transition-colors flex items-center justify-center gap-2">
                                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 fill-current" viewBox="0 0 448 512">
                                                <path d="M380.9 97.1C339 55.1 283.2 32 223.9 32c-122.4 0-222 99.6-222 222 0 39.1 10.2 77.3 29.6 111L0 480l117.7-30.9c32.7 17.8 69.4 27.2 106.2 27.2 122.4 0 222-99.6 222-222 0-59.3-23-115.1-65-157.1zM223.9 445.5c-33.1 0-65.5-8.9-93.6-25.7l-6.7-4-69.6 18.3 18.7-67.9-4.4-7c-18.4-29.4-28.1-63.3-28.1-98.2 0-101.7 82.8-184.5 184.5-184.5 49.3 0 95.6 19.2 130.4 54.1 34.8 34.9 54 81.2 54 130.4 0 101.7-82.8 184.5-184.5 184.5zm101.2-138.2c-5.5-2.8-32.8-16.2-37.9-18-5.1-1.9-8.8-2.8-12.5 2.8-3.7 5.6-14.3 18-17.6 21.8-3.2 3.7-6.5 4.2-12 1.4-5.5-2.8-23.4-8.6-44.6-27.6-16.5-14.7-27.6-32.8-30.8-38.4-3.2-5.6-.3-8.6 2.5-11.4 2.5-2.5 5.5-6.5 8.3-9.7 2.8-3.2 3.7-5.5 5.5-9.2 1.9-3.7.9-6.9-.5-9.7-1.4-2.8-12.5-30.1-17.1-41.2-4.5-10.8-9.1-9.3-12.5-9.5-3.2-.2-6.9-.2-10.6-.2-3.7 0-9.7 1.4-14.8 6.9-5.1 5.6-19.4 19-19.4 46.3 0 27.3 19.9 53.7 22.6 57.4 2.8 3.7 39.1 59.7 94.8 83.8 13.2 5.8 23.5 9.2 31.5 11.8 13.3 4.2 25.4 3.6 35 2.2 10.7-1.5 32.8-13.4 37.4-26.4 4.6-13 4.6-24.1 3.2-26.4-1.3-2.5-5-3.9-10.5-6.6z" />
                                            </svg>
                                            Encaminhar por WhatsApp
                                        </button>
                                        <button onClick={() => setIsHistoryModalOpen(true)} className="text-center bg-gray-100 hover:bg-gray-200 text-gray-800 font-bold py-3 px-6 rounded-lg transition-colors">
                                            Ver Histórico
                                        </button>
                                        <button onClick={() => setIsReportModalOpen(true)} className="text-center bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-6 rounded-lg transition-colors">
                                            Fechar e Relatar
                                        </button>
                                    </div>
                                </div>
                            </div>
                        )
                    })()
                ) : hasPendingRequest ? (
                    <div className="bg-yellow-100 border-l-4 border-yellow-500 text-yellow-700 p-4 rounded-md" role="alert">
                        <p className="font-bold">Solicitação Enviada</p>
                        <p>Você tem uma solicitação de território pendente. Aguarde a aprovação do administrador.</p>
                    </div>
                ) : (
                    <div className="bg-gray-100 p-8 rounded-lg text-center">
                        <h3 className="text-xl font-semibold text-gray-800">Pronto para trabalhar?</h3>
                        <p className="text-gray-600 mt-2 mb-6">Você não tem um território ativo no momento. Clique abaixo para solicitar um.</p>
                        <button
                            onClick={handleRequest}
                            disabled={actionLoading}
                            className="bg-green-500 hover:bg-green-600 text-white font-bold py-3 px-6 rounded-lg transition-colors disabled:bg-green-300 text-lg shadow-md"
                        >
                            {actionLoading ? 'Enviando Solicitação...' : 'Solicitar um Território'}
                        </button>
                    </div>
                )}
            </section>
        </div>
    );
};

