    const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
    const [actionLoading, setActionLoading] = useState(false);

    const fetchData = useCallback(async () => {
        if (!user) return;
        setError('');
        try {
            const { myTerritory, hasPendingRequest } = await fetchPublisherData(user.id);
            setMyTerritory(myTerritory);
            setHasPendingRequest(hasPendingRequest);
        } catch (err) {
            setError('Falha ao carregar os dados. Tente novamente mais tarde.');
        } finally {
            setLoading(false);
        }
    }, [user]);

    useEffect(() => {
        setLoading(true);
        fetchData();
    }, [fetchData]);

    const handleRequest = async () => {
        if (!user) return;
        setActionLoading(true);
        try {
            await requestTerritory(user);
            await fetchData();
        } catch (err: any) {
            console.error(err);
            setError(err.message || 'Não foi possível solicitar o território.');
        } finally {
            setActionLoading(false);
