// --- REQUEST FUNCTIONS ---

export const requestTerritory = async (user: User): Promise<void> => {
    const { data: existing, error: checkError } = await supabase
        .from('requests')
        .select('id')
        .eq('user_id', user.id)
        .eq('status', RequestStatus.PENDING);

    if (checkError) throw new Error(checkError.message);
    if (existing && existing.length > 0) throw new Error("Você já tem uma solicitação pendente.");

    const { error } = await supabase
        .from('requests')
        .insert({
            user_id: user.id,
            user_name: user.name,
            status: RequestStatus.PENDING
        });

    if (error) throw new Error(error.message);
};

export const fetchAllRequests = async (): Promise<TerritoryRequest[]> => {
    const { data, error } = await supabase
        .from('requests')
        .select('*')
        .eq('status', RequestStatus.PENDING)
        .order('request_date', { ascending: true });

    if (error) throw new Error(error.message);
    return (data || []).map(r => ({
        id: r.id,
        userId: r.user_id,
        userName: r.user_name,
        status: r.status,
        requestDate: new Date(r.request_date),
    }));
};

export const assignTerritoryToRequest = async (requestId: string, territoryId: string): Promise<void> => {
    const { data: request, error: requestError } = await supabase
        .from('requests')
        .select('user_id, user_name')
        .eq('id', requestId)
        .single();

    if (requestError || !request) throw new Error("Solicitação não encontrada");

    const assignmentDate = new Date();
    const dueDate = new Date(assignmentDate.getTime() + 30 * 24 * 60 * 60 * 1000);

    const { error: territoryError } = await supabase
        .from('territories')
        .update({
            status: TerritoryStatus.IN_USE,
            assigned_to: request.user_id,
            assigned_to_name: request.user_name,
            assignment_date: assignmentDate.toISOString(),
            due_date: dueDate.toISOString()
        })
        .eq('id', territoryId);

    if (territoryError) throw new Error(territoryError.message);

    await rejectRequest(requestId);
};

export const rejectRequest = async (requestId: string): Promise<void> => {
    const { error } = await supabase
        .from('requests')
        .delete()
        .eq('id', requestId);

    if (error) throw new Error(error.message);
};

// --- NOTIFICATION FUNCTIONS ---

export const fetchNotifications = async (user: User): Promise<Notification[]> => {
    let notifications: Notification[] = [];
    if (user.role === 'admin') {
        try {
            const requests = await fetchAllRequests();
            requests.forEach(req => {
                notifications.push({
                    id: `notif_req_${req.id}`,
                    message: `${req.userName} solicitou um novo território.`,
                    type: 'info',
                    read: false,
                    createdAt: req.requestDate
                });
            });
        } catch (e) {}
    }

    const { data } = await supabase
        .from('territories')
        .select('*')
        .eq('assigned_to', user.id)
        .eq('status', TerritoryStatus.IN_USE);

    if (data) {
        data.forEach(t => {
            const territory = fromSupabaseToTerritory(t);
            if (territory.dueDate) {
                const daysRemaining = Math.ceil((territory.dueDate.getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24));
                if (daysRemaining <= 7) {
                     notifications.push({
                        id: `notif_due_${territory.id}`,
                        message: `Seu território "${territory.name}" vence em ${daysRemaining} dia(s).`,
                        type: daysRemaining <= 0 ? 'warning' : 'info',
                        read: false,
                        createdAt: new Date()
                    });
                }
            }
        });
    }

    return notifications.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
};

export const markNotificationsAsRead = async (notificationIds: string[]): Promise<void> => {
    return Promise.resolve();
};

import React, { createContext, useState, useEffect, useContext, ReactNode } from 'react';
import { User } from '../types';
import { apiLogin, apiLogout, apiSignUp } from '../services/api';
import { supabase, getUserProfile } from '../supabase/client';
import { Session } from '@supabase/supabase-js';


interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, pass: string) => Promise<void>;
  logout: () => Promise<void>;
  signUp: (name: string, email: string, pass: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const getInitialSession = async () => {
        try {
            const { data: { session }, error } = await supabase.auth.getSession();
            if (error) {
                console.error("Erro ao buscar sessão inicial:", error);
            }
            await handleAuthStateChange(session);
        } catch (e) {
            console.error("Falha catastrófica na inicialização do Auth:", e);
        } finally {
            setLoading(false);
        }
    };

    getInitialSession();

    const { data: authListener } = supabase.auth.onAuthStateChange(async (_event, session) => {
        await handleAuthStateChange(session);
    });

    return () => {
      authListener.subscription.unsubscribe();
    };
  }, []);

  const handleAuthStateChange = async (session: Session | null) => {
     try {
        if (session?.user) {
            let profile = await getUserProfile(session.user.id);

            if (!profile) {
                const { count, error: countError } = await supabase.from('users').select('*', { count: 'exact', head: true });
                if (countError) console.warn("Erro ao contar usuários:", countError);

                const role = (count === 0 || session.user.email?.toLowerCase() === 'admin@example.com') ? 'admin' : 'publicador';

                await supabase.from('users').insert({
                    auth_id: session.user.id,
                    name: session.user.user_metadata?.name || 'Usuário',
                    email: session.user.email?.toLowerCase(),
                    role
                });

                profile = await getUserProfile(session.user.id);
            }

            if (profile) {
                setUser({ id: session.user.id, ...profile });
            } else {
                setUser(null);
            }
        } else {
            setUser(null);
        }
     } catch (e) {
         console.error("Erro ao processar mudança de estado de autenticação:", e);
         setUser(null);
     }
  }


  const login = async (email: string, pass: string) => {
    await apiLogin(email, pass);
  };

  const logout = async () => {
    try {
      await apiLogout();
    } catch (err) {
      console.warn("Sign out API failed, forcing local logout", err);
    } finally {
      setUser(null);
      if (typeof window !== 'undefined') {
          localStorage.clear();
          sessionStorage.clear();
      }
    }
  };

  const signUp = async (name: string, email: string, pass: string) => {
    const response = await apiSignUp(name, email, pass);
    if (response && response.session) {
      await handleAuthStateChange(response.session);
    }
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, signUp }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

