service cloud.firestore {
  match /databases/{database}/documents {

    // Função auxiliar para verificar se o usuário é admin
    function isAdmin() {
      return request.auth != null && get(/databases/$(database)/documents/users/$(request.auth.uid)).data.role == 'admin';
    }

    // Usuários
    match /users/{userId} {
      // O próprio usuário pode ler e atualizar seus dados básicos
      // Admins podem ler e atualizar qualquer usuário (para mudar roles)
      allow read: if request.auth != null && (request.auth.uid == userId || isAdmin());
      allow update: if request.auth != null && (request.auth.uid == userId || isAdmin());
      // Qualquer um autenticado pode criar seu perfil inicial no cadastro
      allow create: if request.auth != null;
    }

    // Territórios
    match /territories/{territoryId} {
      // Qualquer usuário autenticado pode listar e ver detalhes dos mapas
      allow read: if request.auth != null;
      // Apenas administradores podem criar, editar ou excluir territórios
      allow write: if isAdmin();
    }

    // Solicitações
    match /requests/{requestId} {
      // Usuários veem suas próprias solicitações. Admins veem todas.
      allow read: if request.auth != null && (resource.data.userId == request.auth.uid || isAdmin());
      // Qualquer usuário autenticado pode criar uma solicitação
      allow create: if request.auth != null;
      // Admins podem atualizar (aprovar) ou deletar
      allow update, delete: if isAdmin();
    }

    // Notificações
    match /notifications/{notificationId} {
      // Usuários só podem ler e marcar como lidas suas próprias notificações
      allow read, update: if request.auth != null && resource.data.userId == request.auth.uid;
      // Apenas o sistema (admin) cria notificações
      allow create: if isAdmin();
    }
  }
}

