import React, { createContext, useState, useEffect, useContext, ReactNode } from 'react';
import { User } from '../types';
import { apiLogin, apiLogout, apiSignUp } from '../services/api';
import { auth, db } from '../firebase/config';
import { onAuthStateChanged } from 'firebase/auth';
import { doc, getDoc, getDocs, collection, query, limit } from 'firebase/firestore';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, pass: string) => Promise<void>;
  logout: () => Promise<void>;
  signUp: (name: string, email: string, pass: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      setLoading(true);
      if (firebaseUser) {
        try {
          // Tentativa de buscar o documento com retry caso seja um cadastro novo
          let userDoc = await getDoc(doc(db, 'users', firebaseUser.uid));

          if (!userDoc.exists()) {
             // Se acabou de cadastrar, o doc pode levar milissegundos para aparecer
             await new Promise(r => setTimeout(r, 1000));
             userDoc = await getDoc(doc(db, 'users', firebaseUser.uid));
          }

          if (userDoc.exists()) {
            setUser({ ...userDoc.data(), id: userDoc.id } as User);
          } else {
            // Verificação de segurança: se não há outros usuários, este deve ser admin
            const usersSnap = await getDocs(query(collection(db, 'users'), limit(1)));
            const fallbackRole = usersSnap.empty ? 'admin' : 'publicador';

            const fallback: User = {
              id: firebaseUser.uid,
              name: firebaseUser.displayName || 'Usuário',
              email: firebaseUser.email || '',
              role: fallbackRole as 'admin' | 'publicador'
            };
            setUser(fallback);
          }
        } catch (error) {
          console.error("Erro ao carregar perfil:", error);
          setUser(null);
        }
      } else {
        setUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const login = async (email: string, pass: string) => {
    const userData = await apiLogin(email, pass);
    setUser(userData);
  };

  const logout = async () => {
    await apiLogout();
    setUser(null);
  };

  const signUp = async (name: string, email: string, pass: string) => {
    const userData = await apiSignUp(name, email, pass);
    setUser(userData);
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, signUp }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // Função auxiliar para verificar se o usuário é Admin
    // Evitamos o uso de exists() dentro de isAdmin para prevenir loops de permissão
    function isAdmin() {
      return request.auth != null && 
        get(/databases/$(database)/documents/users/$(request.auth.uid)).data.role == 'admin';
    }

    match /users/{userId} {
      // Permite ler o próprio perfil
      allow get: if request.auth != null && request.auth.uid == userId;
      // Permite que admins leiam qualquer perfil
      allow get: if request.auth != null && isAdmin();
      // Permite listar usuários (necessário para checar primeiro admin e painel admin)
      allow list: if request.auth != null; 
      // Permite criar o próprio perfil
      allow create: if request.auth != null && request.auth.uid == userId;
      // Permite atualizar o próprio perfil ou se for admin
      allow update: if request.auth != null && (request.auth.uid == userId || isAdmin());
    }

    match /territories/{territoryId} {
      allow read: if request.auth != null;
      allow write: if isAdmin();
    }

    match /requests/{requestId} {
      allow read: if request.auth != null && (resource.data.userId == request.auth.uid || isAdmin());
      allow create: if request.auth != null && request.resource.data.userId == request.auth.uid;
      allow update, delete: if isAdmin();
    }

    match /notifications/{notificationId} {
      // Regra de leitura (get + list)
      allow read: if request.auth != null && (resource.data.userId == request.auth.uid || isAdmin());
      // Regra de atualização (marcar como lido)
      allow update: if request.auth != null && resource.data.userId == request.auth.uid;
      // Apenas admins criam notificações
      allow create: if isAdmin();
    }
  }
}

