export const fetchAllTerritories = async (): Promise<Territory[]> => {
    try {
        const q = query(collection(db, 'territories'));
        const querySnapshot = await getDocs(q);

        const list = querySnapshot.docs.map(doc => {
            const data = doc.data();
            return {
                ...data,
                id: doc.id,
                name: data.name || 'Sem Nome',
                createdAt: data.createdAt?.toDate() || new Date(),
                assignmentDate: data.assignmentDate?.toDate() || null,
                dueDate: data.dueDate?.toDate() || null,
                history: (data.history || []).map((h: any) => ({
                    ...h,
                    completedDate: h.completedDate?.toDate() || new Date()
                }))
            } as Territory;
        });

        // Correção localeCompare: garantindo que name sempre exista como string
        return list.sort((a, b) => (a.name || '').localeCompare(b.name || '', undefined, { numeric: true }));
    } catch (error) {
        console.error("Erro ao buscar territórios:", error);
        throw error;
    }
};

export const uploadTerritory = async (name: string, file: File): Promise<void> => {
    try {
        const fileName = `${Date.now()}_${file.name}`;
        const storageRef = ref(storage, `maps/${fileName}`);

        console.log("Iniciando upload para Firebase Storage...");
        const snapshot = await uploadBytes(storageRef, file);
        const pdfUrl = await getDownloadURL(snapshot.ref);
        console.log("Upload concluído. URL:", pdfUrl);

        const newTerritory = {
            name,
            status: TerritoryStatus.AVAILABLE,
            pdfUrl,
            createdAt: Timestamp.now(),
            history: [],
            permanentNotes: '',
            assignedTo: null,
            assignedToName: null,
            assignmentDate: null,
            dueDate: null
        };

        await addDoc(collection(db, 'territories'), newTerritory);
    } catch (error: any) {
        console.error("Erro detalhado no upload:", error);
        if (error.code === 'storage/unauthorized') {
            throw new Error("Sem permissão para o Storage. Verifique as regras de segurança.");
        } else if (error.code === 'storage/retry-limit-exceeded') {
            throw new Error("Falha na rede ou limite de cota do Firebase atingido.");
        }
        throw new Error("Erro ao salvar arquivo. Verifique se o Firebase Storage está ativado no console.");
    }
};

