            requestDate: doc.data().requestDate?.toDate() || new Date()
        } as TerritoryRequest));

        return list.sort((a, b) => b.requestDate.getTime() - a.requestDate.getTime());
    } catch (error) {
        console.error("Erro ao buscar solicitações:", error);
        throw error;
    }
