const AdminDashboard: React.FC = () => {
    const { user: currentUser } = useAuth();
    const [territories, setTerritories] = useState<Territory[]>([]);
    const [requests, setRequests] = useState<TerritoryRequest[]>([]);
    const [users, setUsers] = useState<User[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [activeTab, setActiveTab] = useState<'territorios' | 'usuarios'>('territorios');

    const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
    const [uploadError, setUploadError] = useState<string | null>(null);
    const [editingTerritory, setEditingTerritory] = useState<Territory | null>(null);
    const [deletingTerritory, setDeletingTerritory] = useState<Territory | null>(null);
    const [assigningRequest, setAssigningRequest] = useState<TerritoryRequest | null>(null);
    const [actionLoading, setActionLoading] = useState<string | null>(null);
    const [viewingHistory, setViewingHistory] = useState<Territory | null>(null);
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState<TerritoryStatus | ''>('');


    const fetchData = useCallback(async () => {
        setError('');
        try {
            const [territoriesData, requestsData, usersData] = await Promise.allSettled([
                fetchAllTerritories(),
                fetchAllRequests(),
                fetchAllUsers()
            ]);

            if (territoriesData.status === 'fulfilled') setTerritories(territoriesData.value);
            if (requestsData.status === 'fulfilled') setRequests(requestsData.value);
            if (usersData.status === 'fulfilled') setUsers(usersData.value);

            if (territoriesData.status === 'rejected' || requestsData.status === 'rejected' || usersData.status === 'rejected') {
                console.warn("Alguns dados não foram carregados completamente.");
            }
        } catch (err) {
            setError('Falha ao conectar com o banco de dados.');
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    const handleUpload = async (name: string, file: File) => {
        setActionLoading('uploading');
        setUploadError(null);
        try {
            await uploadTerritory(name, file);
            await fetchData();
            setIsUploadModalOpen(false);
        } catch(err: any) {
            setUploadError(err.message);
        } finally {
            setActionLoading(null);
        }
    };

    const handleAddLink = async (name: string, url: string) => {
        setActionLoading('uploading');
        setUploadError(null);
        try {
            await createTerritory(name, url);
            await fetchData();
            setIsUploadModalOpen(false);
        } catch(err: any) {
            setUploadError("Falha ao salvar o link.");
        } finally {
            setActionLoading(null);
        }
    };

    const handleUpdate = async (territoryId: string, data: { name: string, permanentNotes: string }) => {
        try {
            await updateTerritory(territoryId, data);
            await fetchData();
        } catch(err) {
            setError("Falha ao atualizar.");
        }
    };

    const handleDelete = async () => {
        if (!deletingTerritory) return;
        try {
            await deleteTerritory(deletingTerritory.id);
            await fetchData();
        } finally {
            setDeletingTerritory(null);
        }
    };

    const handleToggleUserRole = async (user: User) => {
        if (user.id === currentUser?.id) return;
        const newRole = user.role === 'admin' ? 'user' : 'admin';
        try {
            await updateUserRole(user.id, newRole);
            await fetchData();
        } catch (err) {
            setError("Erro ao mudar cargo.");
        }
    };

    const filteredTerritories = useMemo(() => {
        return territories
            .filter(t => (t.name || '').toLowerCase().includes(searchTerm.toLowerCase()))
            .filter(t => statusFilter ? t.status === statusFilter : true);
    }, [territories, searchTerm, statusFilter]);

    const availableTerritoriesForAssignment = useMemo(() => {
        return territories
            .filter(t => t.status === TerritoryStatus.AVAILABLE)
            .sort((a, b) => (a.name || '').localeCompare(b.name || '', undefined, { numeric: true, sensitivity: 'base' }));
    }, [territories]);

    if (loading) return <div className="text-center p-10 font-bold text-blue-600">Carregando sistema...</div>;

    return (
        <div className="container mx-auto">
             {error && <div className="bg-red-100 text-red-700 p-4 rounded-md mb-6">{error}</div>}

            <div className="flex flex-col sm:flex-row justify-between items-center mb-6 gap-4">
                <h1 className="text-3xl font-black text-gray-800 tracking-tight">Painel Administrativo</h1>
                <div className="flex bg-gray-200 p-1 rounded-xl">
                    <button onClick={() => setActiveTab('territorios')} className={`px-4 py-2 text-sm font-bold rounded-lg ${activeTab === 'territorios' ? 'bg-white text-blue-600 shadow' : 'text-gray-600'}`}>Territórios</button>
                    <button onClick={() => setActiveTab('usuarios')} className={`px-4 py-2 text-sm font-bold rounded-lg ${activeTab === 'usuarios' ? 'bg-white text-blue-600 shadow' : 'text-gray-600'}`}>Usuários</button>
                </div>
            </div>

            {activeTab === 'territorios' ? (
                <>
                    <div className="flex justify-between items-center mb-6">
                        <h2 className="text-xl font-bold text-gray-700">Gestão de Mapas</h2>
                        <button onClick={() => setIsUploadModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2.5 px-6 rounded-xl shadow-lg transition transform active:scale-95">+ Adicionar Mapa</button>
                    </div>

                    {isUploadModalOpen && <UploadTerritoryModal 
                        onClose={() => setIsUploadModalOpen(false)} 
                        onUpload={handleUpload} 
                        onAddLink={handleAddLink}
                        isLoading={actionLoading === 'uploading'} 
                        error={uploadError} 
                    />}

                    {editingTerritory && <EditTerritoryModal territory={editingTerritory} onClose={() => setEditingTerritory(null)} onSave={handleUpdate} />}
                    {deletingTerritory && <ConfirmationModal title="Excluir?" message="Deseja mesmo excluir este território?" onClose={() => setDeletingTerritory(null)} onConfirm={handleDelete} />}

                    {/* All Territories List */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-10">
                        {filteredTerritories.map(t => {
                            const colorInfo = getDeadlineColorInfo(t.dueDate);
                            return (
                                <div key={t.id} className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden flex flex-col justify-between">
                                    <div className={`p-4 ${t.status === TerritoryStatus.IN_USE ? colorInfo.bgColor : 'bg-gray-100'}`}>
                                        <h3 className={`font-black truncate ${t.status === TerritoryStatus.IN_USE ? colorInfo.textColor : 'text-gray-700'}`}>{t.name}</h3>
                                    </div>
                                    <div className="p-4 space-y-2 text-xs">
                                        <p><strong>Status:</strong> <span className="capitalize">{t.status}</span></p>
                                        {t.assignedToName && <p><strong>Com:</strong> {t.assignedToName}</p>}
                                        <div className="pt-3 flex justify-between border-t border-gray-50">
                                            <button onClick={() => setEditingTerritory(t)} className="text-blue-600 font-bold hover:underline">Editar</button>
                                            <button onClick={() => setDeletingTerritory(t)} className="text-red-500 font-bold hover:underline">Excluir</button>
