                    <table className="min-w-full divide-y divide-gray-100">
                        <thead className="bg-gray-50">
                            <tr>
                                <th className="px-6 py-4 text-left text-xs font-bold text-gray-400 uppercase">Nome</th>
                                <th className="px-6 py-4 text-left text-xs font-bold text-gray-400 uppercase">E-mail</th>
                                <th className="px-6 py-4 text-right text-xs font-bold text-gray-400 uppercase">Ações</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {users.map(u => (
                                <tr key={u.id}>
                                    <td className="px-6 py-4 font-bold text-sm text-gray-800">{u.name}</td>
