const AdminDashboard: React.FC = () => {
    const [territories, setTerritories] = useState<Territory[]>([]);
    const [requests, setRequests] = useState<TerritoryRequest[]>([]);
    const [users, setUsers] = useState<User[]>([]);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState<'territories' | 'users'>('territories');
    const [searchTerm, setSearchTerm] = useState('');
    const [filterStatus, setFilterStatus] = useState<string>('all');

    // Modais
    const [selectedTerritory, setSelectedTerritory] = useState<Territory | null>(null);
    const [modalType, setModalType] = useState<'assign' | 'history' | 'add' | 'notes' | null>(null);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const [t, r, u] = await Promise.all([
                fetchAllTerritories(),
                fetchAllRequests(),
                fetchAllUsers()
            ]);
            setTerritories(t);
            setRequests(r);
            setUsers(u);
        } catch (error) {
            console.error("Erro ao carregar dados:", error);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        loadData();
    }, [loadData]);

    const stats = useMemo(() => ({
        total: territories.length,
        inUse: territories.filter(t => t.status === TerritoryStatus.IN_USE).length,
        available: territories.filter(t => t.status === TerritoryStatus.AVAILABLE).length,
        pendingRequests: requests.length
    }), [territories, requests]);

    const filteredTerritories = useMemo(() => {
        return territories.filter(t => {
            const matchesSearch = (t.name || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
                                 (t.assignedToName || '').toLowerCase().includes(searchTerm.toLowerCase());
            const matchesFilter = filterStatus === 'all' || t.status === filterStatus;
            return matchesSearch && matchesFilter;
        });
    }, [territories, searchTerm, filterStatus]);

    const handleAssign = async (userId: string, userName: string) => {
        if (!selectedTerritory) return;
        try {
            const dueDate = new Date();
            dueDate.setDate(dueDate.getDate() + 30);
            await updateTerritory(selectedTerritory.id, {
                status: TerritoryStatus.IN_USE,
                assignedTo: userId,
                assignedToName: userName,
                assignmentDate: new Date(),
                dueDate: dueDate
            });
            setModalType(null);
            loadData();
        } catch (e) { alert("Erro ao atribuir."); }
    };

    const handleDeallocate = async (t: Territory) => {
        if (!window.confirm(`Liberar o território ${t.name}?`)) return;
        try {
            await updateTerritory(t.id, {
                status: TerritoryStatus.AVAILABLE,
                assignedTo: null,
                assignedToName: null,
                assignmentDate: null,
                dueDate: null
            });
            loadData();
        } catch (e) { alert("Erro ao liberar."); }
    };

    const handleDelete = async (id: string) => {
        if (!window.confirm("Excluir este território permanentemente?")) return;
        await deleteTerritory(id);
        loadData();
    };

    const handleApproveRequest = async (req: TerritoryRequest, territoryId: string) => {
        try {
            await assignTerritoryToRequest(req.id, territoryId);
            loadData();
        } catch (e) { alert("Erro ao aprovar."); }
    };

    const handleRejectRequest = async (id: string) => {
        await rejectRequest(id);
        loadData();
