                                {t.status === TerritoryStatus.IN_USE ? (
                                    <div className="space-y-4">
                                        <div className="flex items-center gap-3 bg-blue-50 p-3 rounded-2xl">
                                            <div className="h-10 w-10 bg-blue-600 rounded-full flex items-center justify-center text-white font-black text-sm">{t.assignedToName?.charAt(0)}</div>
                                            <div>
                                                <p className="text-sm font-black text-gray-800 leading-none">{t.assignedToName}</p>
