                                        <div className="flex gap-2 pt-2">
                                            <a href={t.pdfUrl} target="_blank" rel="noopener noreferrer" className="flex-1 py-3 bg-gray-900 text-white text-xs font-black rounded-xl text-center hover:bg-black transition-all">ABRIR PDF</a>
                                            <button onClick={() => handleDeallocate(t)} className="flex-1 py-3 bg-white border border-gray-200 text-gray-600 text-xs font-black rounded-xl hover:bg-gray-50 transition-all">LIBERAR</button>
                                        </div>
                                    </div>
                                ) : (
                                    <div className="py-4">
                                        <div className="h-24 flex items-center justify-center bg-gray-50 rounded-3xl mb-4 border-2 border-dashed border-gray-100">
                                            <svg className="h-8 w-8 text-gray-200" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                                        </div>
                                        <button onClick={() => { setSelectedTerritory(t); setModalType('assign'); }} className="w-full py-4 bg-emerald-600 text-white font-black rounded-2xl hover:bg-emerald-700 shadow-lg shadow-emerald-50 transition-all active:scale-95">ATRIBUIR AGORA</button>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            ) : (
                <div className="bg-white rounded-3xl overflow-hidden shadow-sm border border-gray-100">
                    <table className="w-full">
                        <thead>
                            <tr className="bg-gray-50 text-left">
                                <th className="px-6 py-4 text-xs font-black text-gray-400 uppercase tracking-widest">Usuário</th>
                                <th className="px-6 py-4 text-xs font-black text-gray-400 uppercase tracking-widest">E-mail</th>
                                <th className="px-6 py-4 text-xs font-black text-gray-400 uppercase tracking-widest">Cargo</th>
                                <th className="px-6 py-4 text-xs font-black text-gray-400 uppercase tracking-widest text-right">Ações</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-50">
                            {users.map(u => (
                                <tr key={u.id} className="hover:bg-gray-50 transition-colors">
                                    <td className="px-6 py-4 font-bold text-gray-800">{u.name}</td>
                                    <td className="px-6 py-4 text-sm text-gray-500">{u.email}</td>
                                    <td className="px-6 py-4">
                                        <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase ${u.role === 'admin' ? 'bg-blue-100 text-blue-700' : 'bg-gray-100 text-gray-600'}`}>
                                            {u.role}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <button onClick={() => handleToggleAdmin(u)} className="text-xs font-black text-blue-600 hover:underline">
                                            {u.role === 'admin' ? 'Remover Admin' : 'Tornar Admin'}
                                        </button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}

            {/* Modais de Controle */}
            {modalType === 'history' && selectedTerritory && <TerritoryHistoryModal territory={selectedTerritory} onClose={() => setModalType(null)} />}
            {modalType === 'assign' && selectedTerritory && <AssignModal territory={selectedTerritory} users={users} onClose={() => setModalType(null)} onAssign={handleAssign} />}
            {modalType === 'add' && <AddMapModal onClose={() => setModalType(null)} onAdded={loadData} />}
        </div>
    );
};

export default AdminDashboard;

