// --- REQUESTS & ASSIGNMENTS ---

export const fetchAllRequests = async (): Promise<TerritoryRequest[]> => {
    try {
        const q = query(collection(db, 'requests'), where('status', '==', RequestStatus.PENDING));
        const querySnapshot = await getDocs(q);
        return querySnapshot.docs.map(doc => ({
            ...doc.data(),
            id: doc.id,
            requestDate: doc.data().requestDate?.toDate() || new Date()
        } as TerritoryRequest)).sort((a, b) => b.requestDate.getTime() - a.requestDate.getTime());
    } catch (error) {
        console.error("Erro ao buscar solicitações:", error);
        throw error;
    }
};

export const requestTerritory = async (user: User): Promise<void> => {
    const q = query(collection(db, 'requests'), where('userId', '==', user.id), where('status', '==', RequestStatus.PENDING));
    const existing = await getDocs(q);
    if (!existing.empty) throw new Error("Você já possui uma solicitação pendente.");

    await addDoc(collection(db, 'requests'), {
        userId: user.id,
        userName: user.name,
        requestDate: Timestamp.now(),
        status: RequestStatus.PENDING
    });
};

export const assignTerritoryToRequest = async (requestId: string, territoryId: string): Promise<void> => {
    await runTransaction(db, async (transaction) => {
        const requestRef = doc(db, 'requests', requestId);
        const territoryRef = doc(db, 'territories', territoryId);
        const requestDoc = await transaction.get(requestRef);
        const territoryDoc = await transaction.get(territoryRef);

        if (!requestDoc.exists() || !territoryDoc.exists()) throw new Error("Erro de dados.");

        const reqData = requestDoc.data();
        const dueDate = new Date();
        dueDate.setDate(dueDate.getDate() + 30); 

        transaction.update(territoryRef, {
            status: TerritoryStatus.IN_USE,
            assignedTo: reqData.userId,
            assignedToName: reqData.userName,
            assignmentDate: Timestamp.now(),
            dueDate: Timestamp.fromDate(dueDate)
        });
        transaction.update(requestRef, { status: RequestStatus.APPROVED });

        const notifRef = doc(collection(db, 'notifications'));
        transaction.set(notifRef, {
            userId: reqData.userId,
            message: `Território ${territoryDoc.data().name} atribuído com sucesso.`,
            type: 'success',
            read: false,
            createdAt: Timestamp.now()
        });
    });
};

export const rejectRequest = async (requestId: string): Promise<void> => {
    await updateDoc(doc(db, 'requests', requestId), { status: RequestStatus.REJECTED });
};

export const submitReport = async (user: User, territory: Territory, notes: string): Promise<void> => {
    const territoryRef = doc(db, 'territories', territory.id);

    const historyEntry = {
        userId: user.id,
        userName: user.name,
        completedDate: Timestamp.now(),
        notes: notes.trim()
    };

    const currentHistory = (territory.history || []).map(h => ({
        ...h,
        completedDate: Timestamp.fromDate(h.completedDate instanceof Date ? h.completedDate : new Date(h.completedDate))
    }));

    await updateDoc(territoryRef, {
        status: TerritoryStatus.AVAILABLE,
        assignedTo: null,
        assignedToName: null,
        assignmentDate: null,
        dueDate: null,
        history: [...currentHistory, historyEntry]
    });
};

// --- NOTIFICATIONS ---

export const fetchNotifications = async (user: User): Promise<Notification[]> => {
    const q = query(collection(db, 'notifications'), where('userId', '==', user.id));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => ({
        ...doc.data(),
        id: doc.id,
        createdAt: doc.data().createdAt?.toDate() || new Date()
    } as Notification)).sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime()).slice(0, 20);
};

export const markNotificationsAsRead = async (ids: string[]): Promise<void> => {
    for (const id of ids) {
        await updateDoc(doc(db, 'notifications', id), { read: true });
    }
};

// --- PUBLISHER DATA ---

export const fetchPublisherData = async (userId: string): Promise<{ myTerritory: Territory | null, hasPendingRequest: boolean }> => {
    const territoriesQ = query(collection(db, 'territories'), where('assignedTo', '==', userId), where('status', '==', TerritoryStatus.IN_USE));
    const territorySnapshot = await getDocs(territoriesQ);
    const myTerritory = !territorySnapshot.empty ? { 
        ...territorySnapshot.docs[0].data(), 
        id: territorySnapshot.docs[0].id,
        dueDate: territorySnapshot.docs[0].data().dueDate?.toDate() || null,
        assignmentDate: territorySnapshot.docs[0].data().assignmentDate?.toDate() || null,
        history: (territorySnapshot.docs[0].data().history || []).map((h:any) => ({
            ...h, 
            completedDate: h.completedDate?.toDate() || new Date()
        }))
    } as Territory : null;

    const requestQ = query(collection(db, 'requests'), where('userId', '==', userId), where('status', '==', RequestStatus.PENDING));
    const requestSnapshot = await getDocs(requestQ);

    return { myTerritory, hasPendingRequest: !requestSnapshot.empty };
};

import React, { createContext, useState, useEffect, useContext, ReactNode } from 'react';
import { User } from '../types';
import { apiLogin, apiLogout, apiSignUp, saveFCMToken } from '../services/api';
import { auth, db, messaging } from '../firebase/config';
import { onAuthStateChanged } from 'firebase/auth';
import { doc, getDoc } from 'firebase/firestore';
import { getToken } from 'firebase/messaging';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, pass: string) => Promise<void>;
  logout: () => Promise<void>;
  signUp: (name: string, email: string, pass: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  // Função para configurar notificações Push
  const setupNotifications = async (userId: string) => {
    try {
      const msg = await messaging();
      if (!msg) return;

      const permission = await Notification.requestPermission();
      if (permission === 'granted') {
        const token = await getToken(msg, {
          // Substitua pela sua PUBLIC VAPID KEY do Firebase Console
          vapidKey: 'SUA_CHAVE_VAPID_AQUI' 
        });
        if (token) {
          await saveFCMToken(userId, token);
        }
      }
    } catch (error) {
      console.warn("Não foi possível registrar notificações Push:", error);
    }
  };

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      if (firebaseUser) {
        setLoading(true);
        try {
          let userDoc = await getDoc(doc(db, 'users', firebaseUser.uid));

          if (!userDoc.exists()) {
             await new Promise(r => setTimeout(r, 1000));
             userDoc = await getDoc(doc(db, 'users', firebaseUser.uid));
          }

          if (userDoc.exists()) {
            const data = userDoc.data();
            const loggedUser = { 
                ...data, 
                id: userDoc.id,
                name: data.name || data.nome || firebaseUser.displayName || firebaseUser.email?.split('@')[0] || 'Usuário'
            } as User;
            setUser(loggedUser);
            setupNotifications(loggedUser.id);
          } else {
            const fallback: User = {
              id: firebaseUser.uid,
              uid: firebaseUser.uid,
              name: firebaseUser.displayName || firebaseUser.email?.split('@')[0] || 'Usuário',
              email: firebaseUser.email || '',
              role: 'user',
              active: true,
              createdAt: new Date()
            };
            setUser(fallback);
          }
        } catch (error) {
          console.error("Erro crítico ao carregar perfil:", error);
        } finally {
          setLoading(false);
        }
      } else {
        setUser(null);
        setLoading(false);
      }
    });

    return () => unsubscribe();
  }, []);

  const login = async (email: string, pass: string) => {
    setLoading(true);
    try {
        const userData = await apiLogin(email, pass);
        setUser(userData);
        await setupNotifications(userData.id);
    } catch (e) {
        throw e;
    } finally {
        setLoading(false);
    }
  };

  const logout = async () => {
    await apiLogout();
    setUser(null);
  };

  const signUp = async (name: string, email: string, pass: string) => {
    setLoading(true);
    try {
        const userData = await apiSignUp(name, email, pass);
        setUser(userData);
        await setupNotifications(userData.id);
    } catch (e) {
        throw e;
    } finally {
        setLoading(false);
    }
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, signUp }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useAuth } from '../hooks/useAuth';
import { Notification as NotificationType } from '../types';
import { markNotificationsAsRead } from '../services/api';
import { db } from '../firebase/config';
import { collection, query, where, onSnapshot, orderBy, limit } from 'firebase/firestore';
import { formatDate } from '../utils/helpers';

const Header: React.FC = () => {
  const { user, logout } = useAuth();
  const [notifications, setNotifications] = useState<NotificationType[]>([]);
  const [showDropdown, setShowDropdown] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Listen for notifications in real-time
  useEffect(() => {
    if (!user) return;

    const q = query(
      collection(db, 'notifications'),
      where('userId', '==', user.id),
      orderBy('createdAt', 'desc'),
      limit(10)
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const notifs = snapshot.docs.map(doc => ({
        ...doc.data(),
        id: doc.id,
        createdAt: doc.data().createdAt?.toDate() || new Date()
      } as NotificationType));
      setNotifications(notifs);

      // Trigger Browser Notification if supported and active
      const unread = notifs.filter(n => !n.read);
      if (unread.length > 0 && document.visibilityState === 'hidden') {
         // This is a simple browser notification while the tab is open but not focused
         new window.Notification("Atualização de Território", {
           body: unread[0].message,
           icon: 'map-icon.svg'
         });
      }
    });

    return () => unsubscribe();
  }, [user]);

  // Listen for NEW REQUESTS in real-time if Admin
  useEffect(() => {
    if (!user || user.role !== 'admin') return;

    const q = query(
      collection(db, 'requests'),
      where('status', '==', 'pendente'),
      orderBy('requestDate', 'desc')
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
        if (!snapshot.empty && !snapshot.metadata.hasPendingWrites) {
            // New request came in!
            // We could show a specific admin toast here
        }
    });

    return () => unsubscribe();
  }, [user]);

  const unreadCount = notifications.filter(n => !n.read).length;

  const handleMarkAsRead = async () => {
    const unreadIds = notifications.filter(n => !n.read).map(n => n.id);
    if (unreadIds.length > 0) {
      await markNotificationsAsRead(unreadIds);
    }
  };

  const handleClickOutside = useCallback((event: MouseEvent) => {
    if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
      setShowDropdown(false);
    }
  }, []);

  useEffect(() => {
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [handleClickOutside]);

  return (
    <header className="bg-white border-b border-gray-100 sticky top-0 z-40 backdrop-blur-md bg-white/80">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-200">
            <img src="map-icon.svg" alt="Logo" className="w-8 h-8 brightness-0 invert" />
          </div>
          <div className="hidden sm:block">
            <h1 className="text-xl font-black text-gray-900 tracking-tight leading-none">territorio</h1>
            <p className="text-[10px] font-bold text-blue-600 uppercase tracking-widest mt-1">Gestão Inteligente</p>
          </div>
        </div>

        <div className="flex items-center gap-2 sm:gap-4">
          <div className="relative" ref={dropdownRef}>
            <button
              onClick={() => {
                setShowDropdown(!showDropdown);
                if (!showDropdown) handleMarkAsRead();
              }}
              className="p-2.5 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all relative"
            >
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" />
              </svg>
              {unreadCount > 0 && (
                <span className="absolute top-2 right-2 h-5 w-5 bg-red-500 text-white text-[10px] font-black flex items-center justify-center rounded-full border-2 border-white animate-bounce">
                  {unreadCount}
                </span>
              )}
            </button>

            {showDropdown && (
              <div className="absolute right-0 mt-3 w-80 bg-white rounded-2xl shadow-2xl border border-gray-100 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                <div className="p-4 bg-gray-50 border-b border-gray-100 flex justify-between items-center">
                  <h3 className="font-black text-gray-800 uppercase text-xs tracking-widest">Notificações</h3>
                  <button onClick={() => setShowDropdown(false)} className="text-gray-400 hover:text-gray-600 text-xl">&times;</button>
                </div>
                <div className="max-h-96 overflow-y-auto no-scrollbar">
                  {notifications.length > 0 ? (
                    notifications.map((n) => (
                      <div key={n.id} className={`p-4 border-b border-gray-50 last:border-0 hover:bg-gray-50 transition-colors ${!n.read ? 'bg-blue-50/30' : ''}`}>
                        <p className="text-sm font-bold text-gray-800 mb-1">{n.message}</p>
                        <p className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">{formatDate(n.createdAt)}</p>
                      </div>
                    ))
                  ) : (
                    <div className="p-10 text-center text-gray-400 italic text-sm font-medium">
                      Nenhuma notificação nova.
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>

          <div className="h-8 w-[1px] bg-gray-100 hidden sm:block"></div>

          <div className="flex items-center gap-3">
            <div className="hidden sm:block text-right">
              <p className="text-sm font-black text-gray-900 leading-none">{user?.name}</p>
              <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">
                {user?.role === 'admin' ? 'Administrador' : 'Publicador'}
              </p>
            </div>
            <button
              onClick={logout}
              className="p-2.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all"
              title="Sair"
            >
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
              </svg>
