export enum TerritoryStatus {
  AVAILABLE = 'disponivel',
  REQUESTED = 'solicitado',
  IN_USE = 'em_uso',
  CLOSED = 'fechado',
}

export enum RequestStatus {
  PENDING = 'pendente',
  APPROVED = 'aprovado',
  REJECTED = 'rejeitado',
}

export interface User {
  id: string;
  uid: string;
  email: string;
  name: string;
  role: 'admin' | 'user';
  active: boolean;
  createdAt: Date;
}

export interface TerritoryHistory {
  userId: string;
  userName: string;
  completedDate: Date;
  notes?: string;
}

export interface Territory {
  id: string;
  name: string;
  status: TerritoryStatus;
  pdfUrl: string;
  createdAt: Date;
  assignedTo: string | null;
  assignedToName: string | null;
  assignmentDate: Date | null;
  dueDate: Date | null;
  history: TerritoryHistory[];
  permanentNotes?: string;
}

export interface TerritoryRequest {
  id: string;
  userId: string;
  userName: string;
  requestDate: Date;
  status: RequestStatus;
}

export interface AppNotification {
  id: string;
  userId: string;
  message: string;
  type: 'info' | 'success' | 'warning';
  read: boolean;
  createdAt: Date;
}

import { 
    signInWithEmailAndPassword, 
    createUserWithEmailAndPassword, 
    signOut,
    updateProfile
} from 'firebase/auth';
import { 
    doc, 
    setDoc, 
    getDoc, 
    collection, 
    getDocs, 
    updateDoc, 
    deleteDoc, 
    query, 
    where, 
    addDoc, 
    Timestamp,
    runTransaction,
    limit,
    arrayUnion
} from 'firebase/firestore';
import { 
    ref, 
    uploadBytes, 
    getDownloadURL, 
    deleteObject 
} from 'firebase/storage';
import { auth, db, storage } from '../firebase/config';
import { User, Territory, TerritoryStatus, RequestStatus, TerritoryRequest, AppNotification } from '../types';

// --- AUTH FUNCTIONS ---

export const saveFCMToken = async (userId: string, token: string) => {
    const userRef = doc(db, 'users', userId);
    await updateDoc(userRef, {
        fcmTokens: arrayUnion(token)
    });
};

export const apiLogin = async (email: string, pass: string): Promise<User> => {
    try {
        const userCredential = await signInWithEmailAndPassword(auth, email, pass);
        const userId = userCredential.user.uid;

        const userRef = doc(db, 'users', userId);
        const userDoc = await getDoc(userRef);

        if (!userDoc.exists()) {
            const userData: User = {
                id: userId,
                uid: userId,
                name: userCredential.user.displayName || email.split('@')[0] || 'Usuário',
                email: userCredential.user.email || email,
                role: 'user', 
                active: true,
                createdAt: new Date()
            };
            await setDoc(userRef, {
                ...userData,
                createdAt: Timestamp.fromDate(userData.createdAt)
            });
            return userData;
        }

        const data = userDoc.data();
        return { 
            ...data, 
            id: userDoc.id,
            name: data.name || data.nome || userCredential.user.displayName || email.split('@')[0] || 'Usuário',
            createdAt: data.createdAt?.toDate() || new Date()
        } as User;
    } catch (error) {
        console.error("Erro no apiLogin:", error);
        throw error;
    }
};

export const apiSignUp = async (name: string, email: string, pass: string): Promise<User> => {
    try {
        const userCredential = await createUserWithEmailAndPassword(auth, email, pass);
        const userId = userCredential.user.uid;

        await updateProfile(userCredential.user, { displayName: name });

        const usersSnapshot = await getDocs(query(collection(db, 'users'), limit(1)));
        const isFirstUser = usersSnapshot.empty;

        const newUser: User = {
            id: userId,
            uid: userId,
            name: name || 'Usuário',
            email: email,
            role: isFirstUser ? 'admin' : 'user', 
            active: true,
            createdAt: new Date()
        };

        await setDoc(doc(db, 'users', userId), {
            ...newUser,
            createdAt: Timestamp.fromDate(newUser.createdAt)
        });

        return newUser;
    } catch (error) {
        console.error("Erro no apiSignUp:", error);
        throw error;
    }
};

export const apiLogout = async (): Promise<void> => {
    await signOut(auth);
};

// --- TERRITORY FUNCTIONS ---

export const fetchAllTerritories = async (): Promise<Territory[]> => {
    try {
        const q = query(collection(db, 'territories'));
        const querySnapshot = await getDocs(q);

        const list = querySnapshot.docs.map(doc => {
            const data = doc.data();
            const rawHistory = data.history || [];

            const history = rawHistory.map((h: any) => ({
                ...h,
                completedDate: h.completedDate instanceof Timestamp 
                    ? h.completedDate.toDate() 
                    : new Date(h.completedDate)
            })).sort((a: any, b: any) => b.completedDate.getTime() - a.completedDate.getTime());

            return {
                ...data,
                id: doc.id,
                name: data.name || 'Sem Nome',
                createdAt: data.createdAt?.toDate() || new Date(),
                assignmentDate: data.assignmentDate?.toDate() || null,
                dueDate: data.dueDate?.toDate() || null,
                history: history
            } as Territory;
        });

        return list;
    } catch (error) {
        console.error("Erro ao buscar territórios:", error);
        throw error;
    }
};

export const createTerritory = async (name: string, url: string): Promise<void> => {
    try {
        const newTerritory = {
            name: name.trim(),
            status: TerritoryStatus.AVAILABLE,
            pdfUrl: url,
            createdAt: Timestamp.now(),
            history: [],
            permanentNotes: '',
            assignedTo: null,
            assignedToName: null,
            assignmentDate: null,
            dueDate: null
        };
        await addDoc(collection(db, 'territories'), newTerritory);
    } catch (error) {
        console.error("Erro ao criar território:", error);
        throw error;
    }
};

export const uploadTerritory = async (name: string, file: File): Promise<void> => {
    try {
        const fileName = `${Date.now()}_${file.name.replace(/\s+/g, '_')}`;
        const storageRef = ref(storage, `maps/${fileName}`);
        const metadata = { contentType: file.type || 'application/pdf' };

        const snapshot = await uploadBytes(storageRef, file, metadata);
        const fileUrl = await getDownloadURL(snapshot.ref);

        await createTerritory(name, fileUrl);
    } catch (error: any) {
        console.error("Erro no upload:", error);
        throw new Error("Erro ao salvar arquivo no Storage.");
    }
};

export const updateTerritory = async (territoryId: string, data: Partial<Territory>): Promise<void> => {
    const territoryRef = doc(db, 'territories', territoryId);
    await updateDoc(territoryRef, data);
};

export const deleteTerritory = async (territoryId: string): Promise<void> => {
    const docRef = doc(db, 'territories', territoryId);
    const territoryDoc = await getDoc(docRef);
    if (territoryDoc.exists()) {
        const data = territoryDoc.data();
        if (data.pdfUrl && data.pdfUrl.includes('firebasestorage')) {
            try {
                const fileRef = ref(storage, data.pdfUrl);
                await deleteObject(fileRef);
            } catch (e) { console.error("Erro ao deletar arquivo:", e); }
        }
    }
    await deleteDoc(docRef);
};

// --- USER MANAGEMENT ---

export const fetchAllUsers = async (): Promise<User[]> => {
    try {
        const querySnapshot = await getDocs(collection(db, 'users'));
        const list = querySnapshot.docs.map(doc => {
            const data = doc.data();
            return { 
                ...data, 
                id: doc.id,
                name: data.name || data.email?.split('@')[0] || 'Sem Nome',
                createdAt: data.createdAt?.toDate() || new Date()
            } as User;
        });
        return list.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
    } catch (error) {
        console.error("Erro ao buscar usuários:", error);
        throw error;
    }
};

export const updateUserRole = async (userId: string, role: 'admin' | 'user'): Promise<void> => {
    await updateDoc(doc(db, 'users', userId), { role });
};

// --- REQUESTS & ASSIGNMENTS ---

export const fetchAllRequests = async (): Promise<TerritoryRequest[]> => {
    try {
        const q = query(collection(db, 'requests'), where('status', '==', RequestStatus.PENDING));
        const querySnapshot = await getDocs(q);
        return querySnapshot.docs.map(doc => ({
            ...doc.data(),
            id: doc.id,
            requestDate: doc.data().requestDate?.toDate() || new Date()
        } as TerritoryRequest)).sort((a, b) => b.requestDate.getTime() - a.requestDate.getTime());
    } catch (error) {
        console.error("Erro ao buscar solicitações:", error);
        throw error;
    }
};

export const requestTerritory = async (user: User): Promise<void> => {
    const q = query(collection(db, 'requests'), where('userId', '==', user.id), where('status', '==', RequestStatus.PENDING));
    const existing = await getDocs(q);
    if (!existing.empty) throw new Error("Você já possui uma solicitação pendente.");

    await addDoc(collection(db, 'requests'), {
        userId: user.id,
        userName: user.name,
        requestDate: Timestamp.now(),
        status: RequestStatus.PENDING
    });
};

export const assignTerritoryToRequest = async (requestId: string, territoryId: string): Promise<void> => {
    await runTransaction(db, async (transaction) => {
        const requestRef = doc(db, 'requests', requestId);
        const territoryRef = doc(db, 'territories', territoryId);
        const requestDoc = await transaction.get(requestRef);
        const territoryDoc = await transaction.get(territoryRef);

        if (!requestDoc.exists() || !territoryDoc.exists()) throw new Error("Erro de dados.");

        const reqData = requestDoc.data();
        const dueDate = new Date();
        dueDate.setDate(dueDate.getDate() + 30); 

        transaction.update(territoryRef, {
            status: TerritoryStatus.IN_USE,
            assignedTo: reqData.userId,
            assignedToName: reqData.userName,
            assignmentDate: Timestamp.now(),
            dueDate: Timestamp.fromDate(dueDate)
        });
        transaction.update(requestRef, { status: RequestStatus.APPROVED });

        const notifRef = doc(collection(db, 'notifications'));
        transaction.set(notifRef, {
            userId: reqData.userId,
            message: `Território ${territoryDoc.data().name} atribuído com sucesso.`,
            type: 'success',
            read: false,
            createdAt: Timestamp.now()
        });
    });
};

export const rejectRequest = async (requestId: string): Promise<void> => {
    await updateDoc(doc(db, 'requests', requestId), { status: RequestStatus.REJECTED });
};

export const submitReport = async (user: User, territory: Territory, notes: string): Promise<void> => {
    const territoryRef = doc(db, 'territories', territory.id);

    const historyEntry = {
        userId: user.id,
        userName: user.name,
        completedDate: Timestamp.now(),
        notes: notes.trim()
    };

    const currentHistory = (territory.history || []).map(h => ({
        ...h,
        completedDate: Timestamp.fromDate(h.completedDate instanceof Date ? h.completedDate : new Date(h.completedDate))
    }));

    await updateDoc(territoryRef, {
        status: TerritoryStatus.AVAILABLE,
        assignedTo: null,
        assignedToName: null,
        assignmentDate: null,
        dueDate: null,
        history: [...currentHistory, historyEntry]
    });
};

// --- NOTIFICATIONS ---

export const fetchNotifications = async (user: User): Promise<AppNotification[]> => {
    const q = query(collection(db, 'notifications'), where('userId', '==', user.id));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => ({
        ...doc.data(),
        id: doc.id,
        createdAt: doc.data().createdAt?.toDate() || new Date()
    } as AppNotification)).sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime()).slice(0, 20);
};

export const markNotificationsAsRead = async (ids: string[]): Promise<void> => {
    for (const id of ids) {
        await updateDoc(doc(db, 'notifications', id), { read: true });
    }
};

// --- PUBLISHER DATA ---

export const fetchPublisherData = async (userId: string): Promise<{ myTerritory: Territory | null, hasPendingRequest: boolean }> => {
    const territoriesQ = query(collection(db, 'territories'), where('assignedTo', '==', userId), where('status', '==', TerritoryStatus.IN_USE));
    const territorySnapshot = await getDocs(territoriesQ);
    const myTerritory = !territorySnapshot.empty ? { 
        ...territorySnapshot.docs[0].data(), 
        id: territorySnapshot.docs[0].id,
        dueDate: territorySnapshot.docs[0].data().dueDate?.toDate() || null,
        assignmentDate: territorySnapshot.docs[0].data().assignmentDate?.toDate() || null,
        history: (territorySnapshot.docs[0].data().history || []).map((h:any) => ({
            ...h, 
            completedDate: h.completedDate?.toDate() || new Date()
        }))
    } as Territory : null;

    const requestQ = query(collection(db, 'requests'), where('userId', '==', userId), where('status', '==', RequestStatus.PENDING));
    const requestSnapshot = await getDocs(requestQ);

    return { myTerritory, hasPendingRequest: !requestSnapshot.empty };
};

export enum TerritoryStatus {
  AVAILABLE = 'disponivel',
  REQUESTED = 'solicitado',
  IN_USE = 'em_uso',
  CLOSED = 'fechado',
}

export enum RequestStatus {
  PENDING = 'pendente',
  APPROVED = 'aprovado',
  REJECTED = 'rejeitado',
}

export interface User {
  id: string;
  uid: string;
  email: string;
  name: string;
  role: 'admin' | 'user';
  active: boolean;
  createdAt: Date;
}

export interface TerritoryHistory {
  userId: string;
  userName: string;
  completedDate: Date;
  notes?: string;
}

export interface Territory {
  id: string;
  name: string;
  status: TerritoryStatus;
  pdfUrl: string;
  createdAt: Date;
  assignedTo: string | null;
  assignedToName: string | null;
  assignmentDate: Date | null;
  dueDate: Date | null;
  history: TerritoryHistory[];
  permanentNotes?: string;
}

export interface TerritoryRequest {
  id: string;
  userId: string;
  userName: string;
  requestDate: Date;
  status: RequestStatus;
}

export interface AppNotification {
  id: string;
  userId: string;
  message: string;
  type: 'info' | 'success' | 'warning';
  read: boolean;
  createdAt: Date;
}

import React, { createContext, useState, useEffect, useContext, ReactNode } from 'react';
import { User } from '../types';
import { apiLogin, apiLogout, apiSignUp } from '../services/api';
import { auth, db } from '../firebase/config';
import { onAuthStateChanged } from 'firebase/auth';
import { doc, getDoc } from 'firebase/firestore';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, pass: string) => Promise<void>;
  logout: () => Promise<void>;
  signUp: (name: string, email: string, pass: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      if (firebaseUser) {
        setLoading(true);
        try {
          let userDoc = await getDoc(doc(db, 'users', firebaseUser.uid));

          if (!userDoc.exists()) {
             await new Promise(r => setTimeout(r, 1000));
             userDoc = await getDoc(doc(db, 'users', firebaseUser.uid));
          }

          if (userDoc.exists()) {
            const data = userDoc.data();
            const loggedUser = { 
                ...data, 
                id: userDoc.id,
                name: data.name || data.nome || firebaseUser.displayName || firebaseUser.email?.split('@')[0] || 'Usuário'
            } as User;
            setUser(loggedUser);
          } else {
            const fallback: User = {
              id: firebaseUser.uid,
              uid: firebaseUser.uid,
              name: firebaseUser.displayName || firebaseUser.email?.split('@')[0] || 'Usuário',
              email: firebaseUser.email || '',
              role: 'user',
              active: true,
              createdAt: new Date()
            };
            setUser(fallback);
          }
        } catch (error) {
          console.error("Erro crítico ao carregar perfil:", error);
        } finally {
          setLoading(false);
        }
      } else {
        setUser(null);
        setLoading(false);
      }
    });

    return () => unsubscribe();
  }, []);

  const login = async (email: string, pass: string) => {
    setLoading(true);
    try {
        const userData = await apiLogin(email, pass);
        setUser(userData);
    } catch (e) {
        throw e;
    } finally {
        setLoading(false);
    }
  };

  const logout = async () => {
    await apiLogout();
    setUser(null);
  };

  const signUp = async (name: string, email: string, pass: string) => {
    setLoading(true);
    try {
        const userData = await apiSignUp(name, email, pass);
        setUser(userData);
    } catch (e) {
        throw e;
    } finally {
        setLoading(false);
    }
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, signUp }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

