                                                    </button>
                                                    {m.status === TerritoryStatus.IN_USE && (
                                                        <button onClick={() => handleResetTerritory(m.id)} className="p-3 text-gray-400 hover:text-amber-600 hover:bg-amber-50 rounded-xl transition-all" title="Retomar Mapa">
