            if (!snapshot.empty) {
                const doc = snapshot.docs[0];
                const data = doc.data();
                const territoryData: Territory = {
                    id: doc.id,
                    name: data.name || 'Sem Nome',
                    status: data.status,
                    pdfUrl: data.pdfUrl,
