pdfjs.GlobalWorkerOptions.workerSrc = `https://esm.sh/pdfjs-dist@4.4.168/build/pdf.worker.min.js`;

// --- MODAIS ---

const MapViewerModal: React.FC<{ url: string; name: string; onClose: () => void }> = ({ url, name, onClose }) => {
    const [numPages, setNumPages] = useState<number | null>(null);
    const [pageNumber, setPageNumber] = useState(1);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');

    const isPdf = url.toLowerCase().includes('.pdf');

    function onDocumentLoadSuccess({ numPages }: { numPages: number }): void {
        setNumPages(numPages);
        setLoading(false);
    }

    function onDocumentLoadError(e: Error): void {
        setError('Falha ao carregar o PDF. O arquivo pode estar corrompido ou o link é inválido.');
        setLoading(false);
    }

    const goToPrevPage = () => setPageNumber(prev => Math.max(prev - 1, 1));
    const goToNextPage = () => setPageNumber(prev => Math.min(prev + 1, numPages || 1));

    return (
        <div className="fixed inset-0 bg-gray-900 bg-opacity-80 flex flex-col items-center justify-center z-50 p-2 sm:p-4 backdrop-blur-sm animate-in fade-in">
            <div className="bg-white rounded-3xl w-full h-full max-w-6xl flex flex-col overflow-hidden shadow-2xl">
                <header className="flex items-center justify-between p-4 border-b border-gray-200 bg-gray-50 flex-shrink-0">
                    <h2 className="text-lg font-black text-gray-800 truncate pr-4">{name}</h2>
                    {isPdf && numPages && (
                        <div className="flex items-center gap-2">
                            <button onClick={goToPrevPage} disabled={pageNumber <= 1} className="p-2 rounded-lg bg-gray-200 disabled:opacity-50 text-gray-700">
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" /></svg>
                            </button>
                            <span className="text-sm font-bold text-gray-600">Página {pageNumber} de {numPages}</span>
                            <button onClick={goToNextPage} disabled={pageNumber >= numPages} className="p-2 rounded-lg bg-gray-200 disabled:opacity-50 text-gray-700">
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7" /></svg>
                            </button>
                        </div>
                    )}
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-800 text-3xl font-bold leading-none p-2 rounded-full transition-colors -mr-2">&times;</button>
                </header>
                <div className="flex-grow w-full h-full bg-gray-200 overflow-auto flex items-center justify-center">
                    {loading && isPdf && <div className="animate-spin h-8 w-8 border-4 border-blue-500 border-t-transparent rounded-full"></div>}
                    {error && <div className="p-4 text-red-600 font-bold">{error}</div>}

                    {isPdf ? (
                        <Document file={url} onLoadSuccess={onDocumentLoadSuccess} onLoadError={onDocumentLoadError} loading={<div className="animate-spin h-8 w-8 border-4 border-blue-500 border-t-transparent rounded-full"></div>}>
                            <Page pageNumber={pageNumber} renderTextLayer={false} renderAnnotationLayer={false} />
                        </Document>
                    ) : (
                        <img src={url} alt={`Mapa ${name}`} className="max-w-full max-h-full object-contain" />
                    )}
                </div>
            </div>
        </div>
    );
};

