                                                {u.role}
                                            </span>
                                        </td>
                                        <td className="px-8 py-6 text-right">
                                            <button onClick={() => handlePromote(u)} className="px-4 py-2 bg-gray-100 text-gray-600 text-xs font-black rounded-lg hover:bg-gray-900 hover:text-white transition-all">
                                                ALTERAR CARGO
                                            </button>
                                        </td>
                                    </tr>
                                ))}
