                        ? h.completedDate.toDate() 
                        : new Date(h.completedDate)
                })).sort((a: any, b: any) => b.completedDate.getTime() - a.completedDate.getTime());

                return {
                    ...data,
                    id: doc.id,
                    name: data.name || 'Sem Nome',
                    createdAt: data.createdAt?.toDate() || new Date(),
                    assignmentDate: data.assignmentDate?.toDate() || null,
                    dueDate: data.dueDate?.toDate() || null,
                    history: history
                } as Territory;
            });
            setTerritories(territoriesList);
            if (loading) setLoading(false);
        }, (error) => {
            console.error("Erro ao carregar territórios:", error);
            if (loading) setLoading(false);
        });

        // Listener de Usuários
        const usersQuery = query(collection(db, 'users'));
        const unsubscribeUsers = onSnapshot(usersQuery, (snapshot) => {
            const usersList = snapshot.docs.map(doc => {
                 const data = doc.data();
                 return { 
                    ...data, 
                    id: doc.id,
                    name: data.name || data.email?.split('@')[0] || 'Sem Nome',
                    createdAt: data.createdAt?.toDate() || new Date()
                 } as User;
            }).sort((a, b) => (a.name || '').localeCompare(b.name || ''));
            setUsers(usersList);
        });

        // Listener de Solicitações
        const requestsQuery = query(collection(db, 'requests'), where('status', '==', RequestStatus.PENDING));
        const unsubscribeRequests = onSnapshot(requestsQuery, (snapshot) => {
            const reqs = snapshot.docs.map(doc => ({
                ...doc.data(),
                id: doc.id,
                requestDate: doc.data().requestDate?.toDate() || new Date()
            } as TerritoryRequest)).sort((a, b) => b.requestDate.getTime() - a.requestDate.getTime());
            setRequests(reqs);
        });

        return () => {
            unsubscribeTerritories();
            unsubscribeUsers();
            unsubscribeRequests();
        };
    }, [loading]);

    const handleFulfillRequest = async (requestId: string) => {
        if (!selectedMapForRequest) return;
        try {
            await assignTerritoryToRequest(requestId, selectedMapForRequest);
            setFulfillingRequestId(null);
            setSelectedMapForRequest('');
        } catch (e: any) { alert(e.message); }
    };

    const handleReject = async (id: string) => {
        if (!confirm("Rejeitar esta solicitação?")) return;
        await rejectRequest(id);
    };

    const handleDeleteTerritory = async (id: string) => {
        if (!confirm("Tem certeza que deseja excluir este território?")) return;
        await deleteTerritory(id);
    };

    const handleResetTerritory = async (id: string) => {
        if (!confirm("Deseja retomar este território? Ele voltará a ficar disponível sem precisar de relatório.")) return;
        await adminResetTerritory(id);
    };

    const handlePromote = async (user: User) => {
        const newRole = user.role === 'admin' ? 'user' : 'admin';
        await updateUserRole(user.id, newRole);
    };

    const sortedTerritories = useMemo(() => {
        return [...territories].sort((a, b) => {
            if (a.status === TerritoryStatus.IN_USE && b.status !== TerritoryStatus.IN_USE) return 1;
            if (b.status === TerritoryStatus.IN_USE && a.status !== TerritoryStatus.IN_USE) return -1;

            const aRecent = isRecentWork(a.history);
            const bRecent = isRecentWork(b.history);
            const aNeverWorked = (a.history || []).length === 0;
            const bNeverWorked = (b.history || []).length === 0;

            if (aNeverWorked && !bNeverWorked) return -1;
            if (bNeverWorked && !aNeverWorked) return 1;

            if (!aRecent && bRecent) return -1;
            if (aRecent && !bRecent) return 1;

            if (a.history && a.history.length > 0 && b.history && b.history.length > 0) {
                return b.history[0].completedDate.getTime() - a.history[0].completedDate.getTime();
            }

            return (a.name || '').localeCompare(b.name || '', undefined, { numeric: true });
        });
    }, [territories]);

    const availableMapsOptions = useMemo(() => {
        return sortedTerritories.filter(t => t.status === TerritoryStatus.AVAILABLE);
    }, [sortedTerritories]);

    const stats = useMemo(() => ({
        total: territories.length,
        available: territories.filter(t => t.status === TerritoryStatus.AVAILABLE && !isRecentWork(t.history)).length,
        resting: territories.filter(t => t.status === TerritoryStatus.AVAILABLE && isRecentWork(t.history)).length,
        inUse: territories.filter(t => t.status === TerritoryStatus.IN_USE).length,
    }), [territories]);

    if (loading) return (
        <div className="flex flex-col items-center justify-center p-20 space-y-4">
            <div className="animate-spin h-12 w-12 border-4 border-blue-600 border-t-transparent rounded-full"></div>
            <p className="text-gray-500 font-bold">Carregando painel...</p>
        </div>
    );

    return (
        <div className="max-w-6xl mx-auto space-y-8 pb-20">
            {showAddModal && <AddMapModal onClose={() => setShowAddModal(false)} onAdded={() => {}} />}
            {editingTerritory && <EditMapModal territory={editingTerritory} onClose={() => setEditingTerritory(null)} onSave={() => {}} />}
            {viewHistory && <TerritoryHistoryModal territory={viewHistory} onClose={() => setViewHistory(null)} />}
            {viewingMap && <MapViewerModal url={viewingMap.pdfUrl} name={viewingMap.name} onClose={() => setViewingMap(null)} />}

            <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                <div className="flex items-center gap-4">
                    <div className="w-16 h-16 bg-white rounded-full shadow-sm border border-gray-100 overflow-hidden">
                        <MapIcon className="w-full h-full"/>
                    </div>
                    <div>
                        <h1 className="text-4xl font-black text-gray-900 tracking-tight">Painel Admin</h1>
                        <p className="text-gray-500 font-medium mt-1">Gestão de Congregação</p>
                    </div>
                </div>
                <div className="flex bg-white/60 p-1.5 rounded-2xl self-start md:self-auto border-[5px] border-slate-200">
                    <button 
                        onClick={() => setActiveTab('territories')} 
                        className={`px-6 py-2 text-sm font-bold rounded-xl transition-all ${activeTab === 'territories' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                    >
                        Mapas
                    </button>
                    <button 
                        onClick={() => setActiveTab('users')} 
                        className={`px-6 py-2 text-sm font-bold rounded-xl transition-all ${activeTab === 'users' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                    >
                        Usuários
                    </button>
                </div>
            </div>

            {activeTab === 'territories' ? (
                <>
                    {/* Estatísticas */}
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                        {[
                            { label: 'Total', value: stats.total, color: 'text-gray-900' },
                            { label: 'Disponíveis', value: stats.available, color: 'text-emerald-600' },
                            { label: 'Em Descanso', value: stats.resting, color: 'text-amber-500' },
                            { label: 'Em Uso', value: stats.inUse, color: 'text-blue-600' }
                        ].map(s => (
                            <div key={s.label} className="bg-white/70 p-6 rounded-3xl border-[5px] border-slate-200 shadow-2xl shadow-violet-200/60">
                                <p className="text-xs font-black text-gray-400 uppercase mb-1">{s.label}</p>
                                <p className={`text-3xl font-black ${s.color}`}>{s.value}</p>
                            </div>
                        ))}
                    </div>

                    {/* Solicitações Pendentes */}
                    {requests.length > 0 && (
                        <div className="bg-white/50 border-[5px] border-slate-200 rounded-[2rem] p-8 shadow-2xl shadow-violet-200/40">
                            <h2 className="text-xl font-black text-blue-900 mb-6 flex items-center gap-2">
                                <span className="flex h-3 w-3 rounded-full bg-blue-600 animate-pulse"></span>
                                Solicitações Pendentes ({requests.length})
                            </h2>
                            <div className="space-y-4">
                                {requests.map(req => (
                                    <div key={req.id} className="bg-white/80 p-6 rounded-2xl shadow-lg shadow-indigo-100/50 flex flex-col md:flex-row items-center justify-between gap-6 border-[5px] border-slate-200">
                                        <div>
                                            <p className="font-black text-gray-900 text-lg">{req.userName}</p>
                                            <p className="text-sm text-gray-500 font-medium">Solicitado em {formatDate(req.requestDate)}</p>
                                        </div>

                                        <div className="flex flex-1 max-w-md items-center gap-3">
                                            {fulfillingRequestId === req.id ? (
                                                <div className="flex items-center gap-2 w-full">
                                                    <select 
                                                        value={selectedMapForRequest} 
                                                        onChange={e => setSelectedMapForRequest(e.target.value)}
                                                        className="flex-1 px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-bold text-sm outline-none focus:ring-2 focus:ring-blue-500"
                                                    >
                                                        <option value="">Selecione um mapa disponível...</option>
                                                        {availableMapsOptions.map(m => (
                                                            <option key={m.id} value={m.id}>{m.name} {isRecentWork(m.history) ? '(Em Descanso)' : ''}</option>
                                                        ))}
                                                    </select>
                                                    <button onClick={() => handleFulfillRequest(req.id)} disabled={!selectedMapForRequest} className="px-6 py-3 bg-emerald-600 text-white font-black rounded-xl hover:bg-emerald-700 disabled:bg-gray-200">OK</button>
                                                    <button onClick={() => setFulfillingRequestId(null)} className="px-4 py-3 bg-gray-100 text-gray-400 font-black rounded-xl">&times;</button>
                                                </div>
                                            ) : (
                                                <div className="flex gap-3">
                                                    <button onClick={() => setFulfillingRequestId(req.id)} className="px-8 py-3 bg-blue-600 text-white font-black rounded-xl hover:bg-blue-700 shadow-lg shadow-blue-100">Atribuir Mapa</button>
                                                    <button onClick={() => handleReject(req.id)} className="px-8 py-3 bg-gray-100 text-gray-500 font-black rounded-xl hover:bg-gray-200">Recusar</button>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Lista de Mapas */}
                    <div className="bg-white/70 rounded-3xl border-[5px] border-slate-200 shadow-2xl shadow-violet-200/60 overflow-hidden">
                        <div className="p-8 border-b-2 border-slate-200 flex justify-between items-center">
                            <h2 className="text-2xl font-black text-gray-800">Mapas da Congregação</h2>
                            <button onClick={() => setShowAddModal(true)} className="px-6 py-3 bg-gray-900 text-white font-black rounded-xl hover:bg-black transition-all transform active:scale-95 shadow-xl shadow-gray-200">
                                + NOVO MAPA
                            </button>
                        </div>
                        <div className="overflow-x-auto">
                            <table className="w-full text-left border-collapse">
                                <thead>
                                    <tr className="text-xs font-black text-indigo-900/70 uppercase tracking-widest bg-white/20">
                                        <th className="px-8 py-5">Identificação</th>
                                        <th className="px-8 py-5">Status</th>
                                        <th className="px-8 py-5">Responsável</th>
                                        <th className="px-8 py-5">Último Trabalho</th>
                                        <th className="px-8 py-5 text-right">Ações</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-200">
                                    {sortedTerritories.map(m => {
                                        const recent = isRecentWork(m.history);
                                        return (
                                            <tr key={m.id} className="group hover:bg-white/20 transition-colors">
                                                <td className="px-8 py-6">
                                                    <p className="font-black text-gray-900 text-lg">{m.name}</p>
                                                    <button onClick={() => setViewingMap(m)} className="text-xs text-blue-500 font-bold hover:underline">Ver Arquivo &rarr;</button>
                                                </td>
                                                <td className="px-8 py-6">
                                                    {m.status === TerritoryStatus.IN_USE ? (
                                                        <span className="px-4 py-1.5 bg-blue-50 text-blue-600 rounded-full text-xs font-black uppercase">Em Uso</span>
                                                    ) : recent ? (
                                                        <span className="px-4 py-1.5 bg-amber-50 text-amber-600 rounded-full text-xs font-black uppercase">Descanso</span>
                                                    ) : (
                                                        <span className="px-4 py-1.5 bg-emerald-50 text-emerald-600 rounded-full text-xs font-black uppercase">Disponível</span>
                                                    )}
                                                </td>
                                                <td className="px-8 py-6">
                                                    <p className="font-bold text-gray-700">{m.assignedToName || '-'}</p>
                                                    {m.dueDate && <p className="text-xs text-red-500 font-bold">Vence em {formatDate(m.dueDate)}</p>}
                                                </td>
                                                <td className="px-8 py-6">
                                                    <p className="text-sm font-bold text-gray-600">{m.history && m.history.length > 0 ? formatDate(m.history[0].completedDate) : 'Nunca'}</p>
                                                </td>
                                                <td className="px-8 py-6 text-right space-x-1">
                                                    <button onClick={() => setEditingTerritory(m)} className="p-3 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-xl transition-all" title="Editar Mapa">
                                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.5L15.232 5.232z"></path></svg>
                                                    </button>
                                                    <button onClick={() => setViewHistory(m)} className="p-3 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all" title="Ver Histórico">
                                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                                                    </button>
                                                    {m.status === TerritoryStatus.IN_USE && (
                                                        <button onClick={() => handleResetTerritory(m.id)} className="p-3 text-gray-400 hover:text-amber-600 hover:bg-amber-50 rounded-xl transition-all" title="Retomar Mapa">
                                                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 10h10a8 8 0 018 8v2M3 10l5 5m-5-5l5-5" /></svg>
                                                        </button>
                                                    )}
                                                    <button onClick={() => handleDeleteTerritory(m.id)} className="p-3 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all" title="Excluir">
                                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                                    </button>
                                                </td>
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </>
            ) : (
                <div className="bg-white/70 rounded-3xl border-[5px] border-slate-200 shadow-2xl shadow-violet-200/60 overflow-hidden">
                    <div className="p-8 border-b-2 border-slate-200">
                        <h2 className="text-2xl font-black text-gray-800">Usuários Cadastrados</h2>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="text-xs font-black text-indigo-900/70 uppercase tracking-widest bg-white/20">
                                    <th className="px-8 py-5">Nome</th>
                                    <th className="px-8 py-5">Email</th>
                                    <th className="px-8 py-5">Cargo</th>
                                    <th className="px-8 py-5 text-right">Ações</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-200">
                                {users.map(u => (
                                    <tr key={u.id} className="group hover:bg-white/20 transition-colors">
                                        <td className="px-8 py-6 font-black text-gray-900">{u.name}</td>
                                        <td className="px-8 py-6 font-medium text-gray-500">{u.email}</td>
                                        <td className="px-8 py-6">
                                            <span className={`px-4 py-1.5 rounded-full text-xs font-black uppercase ${u.role === 'admin' ? 'bg-purple-50 text-purple-600' : 'bg-gray-100 text-gray-500'}`}>
                                                {u.role}
                                            </span>
                                        </td>
                                        <td className="px-8 py-6 text-right">
                                            <button onClick={() => handlePromote(u)} className="px-4 py-2 bg-gray-100 text-gray-600 text-xs font-black rounded-lg hover:bg-gray-900 hover:text-white transition-all">
                                                ALTERAR CARGO
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}
        </div>
    );
};

export default AdminDashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { Territory, TerritoryRequest, TerritoryStatus, User, RequestStatus } from '../types';
import { 
    assignTerritoryToRequest, rejectRequest, 
    updateTerritory, deleteTerritory, updateUserRole, adminResetTerritory
} from '../services/api';
import { formatDate, isRecentWork } from '../utils/helpers';
import { collection, query, where, onSnapshot, Timestamp } from 'firebase/firestore';
import { db } from '../firebase/config';
import MapViewerModal from './modals/MapViewerModal';
import TerritoryHistoryModal from './modals/TerritoryHistoryModal';
import AddMapModal from './modals/AddMapModal';
import EditMapModal from './modals/EditMapModal';
import { MapIcon } from './Icon';

const AdminDashboard: React.FC = () => {
    const [territories, setTerritories] = useState<Territory[]>([]);
    const [requests, setRequests] = useState<TerritoryRequest[]>([]);
    const [users, setUsers] = useState<User[]>([]);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState<'territories' | 'users'>('territories');

    // UI States
    const [showAddModal, setShowAddModal] = useState(false);
    const [editingTerritory, setEditingTerritory] = useState<Territory | null>(null);
    const [viewHistory, setViewHistory] = useState<Territory | null>(null);
    const [viewingMap, setViewingMap] = useState<Territory | null>(null);
    const [fulfillingRequestId, setFulfillingRequestId] = useState<string | null>(null);
    const [selectedMapForRequest, setSelectedMapForRequest] = useState<string>('');

    // Listener para todos os dados em tempo real
    useEffect(() => {
        // Listener de Territórios
        const territoriesQuery = query(collection(db, 'territories'));
        const unsubscribeTerritories = onSnapshot(territoriesQuery, (snapshot) => {
            const territoriesList = snapshot.docs.map(doc => {
                const data = doc.data();
                const rawHistory = data.history || [];
                const history = rawHistory.map((h: any) => ({
                    ...h,
                    completedDate: h.completedDate instanceof Timestamp 
                        ? h.completedDate.toDate() 
                        : new Date(h.completedDate)
                })).sort((a: any, b: any) => b.completedDate.getTime() - a.completedDate.getTime());

                return {
                    ...data,
                    id: doc.id,
                    name: data.name || 'Sem Nome',
                    createdAt: data.createdAt?.toDate() || new Date(),
                    assignmentDate: data.assignmentDate?.toDate() || null,
                    dueDate: data.dueDate?.toDate() || null,
                    history: history
                } as Territory;
            });
            setTerritories(territoriesList);
            if (loading) setLoading(false);
        }, (error) => {
            console.error("Erro ao carregar territórios:", error);
            if (loading) setLoading(false);
        });

        // Listener de Usuários
        const usersQuery = query(collection(db, 'users'));
        const unsubscribeUsers = onSnapshot(usersQuery, (snapshot) => {
            const usersList = snapshot.docs.map(doc => {
                 const data = doc.data();
                 return { 
                    ...data, 
                    id: doc.id,
                    name: data.name || data.email?.split('@')[0] || 'Sem Nome',
                    createdAt: data.createdAt?.toDate() || new Date()
                 } as User;
            }).sort((a, b) => (a.name || '').localeCompare(b.name || ''));
            setUsers(usersList);
        });

        // Listener de Solicitações
        const requestsQuery = query(collection(db, 'requests'), where('status', '==', RequestStatus.PENDING));
        const unsubscribeRequests = onSnapshot(requestsQuery, (snapshot) => {
            const reqs = snapshot.docs.map(doc => ({
                ...doc.data(),
                id: doc.id,
                requestDate: doc.data().requestDate?.toDate() || new Date()
            } as TerritoryRequest)).sort((a, b) => b.requestDate.getTime() - a.requestDate.getTime());
            setRequests(reqs);
        });

        return () => {
            unsubscribeTerritories();
            unsubscribeUsers();
            unsubscribeRequests();
        };
    }, [loading]);

    const handleFulfillRequest = async (requestId: string) => {
        if (!selectedMapForRequest) return;
        try {
            await assignTerritoryToRequest(requestId, selectedMapForRequest);
            setFulfillingRequestId(null);
            setSelectedMapForRequest('');
        } catch (e: any) { alert(e.message); }
    };

    const handleReject = async (id: string) => {
        if (!confirm("Rejeitar esta solicitação?")) return;
        await rejectRequest(id);
    };

    const handleDeleteTerritory = async (id: string) => {
        if (!confirm("Tem certeza que deseja excluir este território?")) return;
        await deleteTerritory(id);
    };

    const handleResetTerritory = async (id: string) => {
        if (!confirm("Deseja retomar este território? Ele voltará a ficar disponível sem precisar de relatório.")) return;
        await adminResetTerritory(id);
    };

    const handlePromote = async (user: User) => {
        const newRole = user.role === 'admin' ? 'user' : 'admin';
        await updateUserRole(user.id, newRole);
    };

    const sortedTerritories = useMemo(() => {
        return [...territories].sort((a, b) => {
            if (a.status === TerritoryStatus.IN_USE && b.status !== TerritoryStatus.IN_USE) return 1;
            if (b.status === TerritoryStatus.IN_USE && a.status !== TerritoryStatus.IN_USE) return -1;

            const aRecent = isRecentWork(a.history);
            const bRecent = isRecentWork(b.history);
            const aNeverWorked = (a.history || []).length === 0;
            const bNeverWorked = (b.history || []).length === 0;

            if (aNeverWorked && !bNeverWorked) return -1;
            if (bNeverWorked && !aNeverWorked) return 1;

            if (!aRecent && bRecent) return -1;
            if (aRecent && !bRecent) return 1;

            if (a.history && a.history.length > 0 && b.history && b.history.length > 0) {
                return b.history[0].completedDate.getTime() - a.history[0].completedDate.getTime();
            }

            return (a.name || '').localeCompare(b.name || '', undefined, { numeric: true });
        });
    }, [territories]);

    const availableMapsOptions = useMemo(() => {
        return sortedTerritories.filter(t => t.status === TerritoryStatus.AVAILABLE);
    }, [sortedTerritories]);

    const stats = useMemo(() => ({
        total: territories.length,
        available: territories.filter(t => t.status === TerritoryStatus.AVAILABLE && !isRecentWork(t.history)).length,
        resting: territories.filter(t => t.status === TerritoryStatus.AVAILABLE && isRecentWork(t.history)).length,
        inUse: territories.filter(t => t.status === TerritoryStatus.IN_USE).length,
    }), [territories]);

    if (loading) return (
        <div className="flex flex-col items-center justify-center p-20 space-y-4">
            <div className="animate-spin h-12 w-12 border-4 border-blue-600 border-t-transparent rounded-full"></div>
            <p className="text-gray-500 font-bold">Carregando painel...</p>
        </div>
    );

    return (
        <div className="max-w-6xl mx-auto space-y-8 pb-20">
            {showAddModal && <AddMapModal onClose={() => setShowAddModal(false)} onAdded={() => {}} />}
            {editingTerritory && <EditMapModal territory={editingTerritory} onClose={() => setEditingTerritory(null)} onSave={() => {}} />}
            {viewHistory && <TerritoryHistoryModal territory={viewHistory} onClose={() => setViewHistory(null)} />}
            {viewingMap && <MapViewerModal url={viewingMap.pdfUrl} name={viewingMap.name} onClose={() => setViewingMap(null)} />}

            <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                <div className="flex items-center gap-4">
                    <div className="w-16 h-16 bg-white rounded-full shadow-sm border border-gray-100 overflow-hidden">
                        <MapIcon className="w-full h-full"/>
                    </div>
                    <div>
                        <h1 className="text-4xl font-black text-gray-900 tracking-tight">Painel Admin</h1>
                        <p className="text-gray-500 font-medium mt-1">Gestão de Congregação</p>
                    </div>
                </div>
                <div className="flex bg-white/60 p-1.5 rounded-2xl self-start md:self-auto border-2 border-slate-200">
                    <button 
                        onClick={() => setActiveTab('territories')} 
                        className={`px-6 py-2 text-sm font-bold rounded-xl transition-all ${activeTab === 'territories' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                    >
                        Mapas
                    </button>
                    <button 
                        onClick={() => setActiveTab('users')} 
                        className={`px-6 py-2 text-sm font-bold rounded-xl transition-all ${activeTab === 'users' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                    >
                        Usuários
                    </button>
                </div>
            </div>

            {activeTab === 'territories' ? (
                <>
                    {/* Estatísticas */}
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                        {[
                            { label: 'Total', value: stats.total, color: 'text-gray-900' },
                            { label: 'Disponíveis', value: stats.available, color: 'text-emerald-600' },
                            { label: 'Em Descanso', value: stats.resting, color: 'text-amber-500' },
                            { label: 'Em Uso', value: stats.inUse, color: 'text-blue-600' }
                        ].map(s => (
                            <div key={s.label} className="bg-white/70 p-6 rounded-3xl border-2 border-slate-200 shadow-2xl shadow-violet-200/60">
                                <p className="text-xs font-black text-gray-400 uppercase mb-1">{s.label}</p>
                                <p className={`text-3xl font-black ${s.color}`}>{s.value}</p>
                            </div>
                        ))}
                    </div>

                    {/* Solicitações Pendentes */}
                    {requests.length > 0 && (
                        <div className="bg-white/50 border-2 border-slate-200 rounded-[2rem] p-8 shadow-2xl shadow-violet-200/40">
                            <h2 className="text-xl font-black text-blue-900 mb-6 flex items-center gap-2">
                                <span className="flex h-3 w-3 rounded-full bg-blue-600 animate-pulse"></span>
                                Solicitações Pendentes ({requests.length})
                            </h2>
                            <div className="space-y-4">
                                {requests.map(req => (
                                    <div key={req.id} className="bg-white/80 p-6 rounded-2xl shadow-lg shadow-indigo-100/50 flex flex-col md:flex-row items-center justify-between gap-6 border-2 border-slate-200">
                                        <div>
                                            <p className="font-black text-gray-900 text-lg">{req.userName}</p>
                                            <p className="text-sm text-gray-500 font-medium">Solicitado em {formatDate(req.requestDate)}</p>
                                        </div>

                                        <div className="flex flex-1 max-w-md items-center gap-3">
                                            {fulfillingRequestId === req.id ? (
                                                <div className="flex items-center gap-2 w-full">
                                                    <select 
                                                        value={selectedMapForRequest} 
                                                        onChange={e => setSelectedMapForRequest(e.target.value)}
                                                        className="flex-1 px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-bold text-sm outline-none focus:ring-2 focus:ring-blue-500"
                                                    >
                                                        <option value="">Selecione um mapa disponível...</option>
                                                        {availableMapsOptions.map(m => (
                                                            <option key={m.id} value={m.id}>{m.name} {isRecentWork(m.history) ? '(Em Descanso)' : ''}</option>
                                                        ))}
                                                    </select>
                                                    <button onClick={() => handleFulfillRequest(req.id)} disabled={!selectedMapForRequest} className="px-6 py-3 bg-emerald-600 text-white font-black rounded-xl hover:bg-emerald-700 disabled:bg-gray-200">OK</button>
                                                    <button onClick={() => setFulfillingRequestId(null)} className="px-4 py-3 bg-gray-100 text-gray-400 font-black rounded-xl">&times;</button>
                                                </div>
                                            ) : (
                                                <div className="flex gap-3">
                                                    <button onClick={() => setFulfillingRequestId(req.id)} className="px-8 py-3 bg-blue-600 text-white font-black rounded-xl hover:bg-blue-700 shadow-lg shadow-blue-100">Atribuir Mapa</button>
                                                    <button onClick={() => handleReject(req.id)} className="px-8 py-3 bg-gray-100 text-gray-500 font-black rounded-xl hover:bg-gray-200">Recusar</button>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Lista de Mapas */}
                    <div className="bg-white/70 rounded-3xl border-2 border-slate-200 shadow-2xl shadow-violet-200/60 overflow-hidden">
                        <div className="p-8 border-b-2 border-slate-200 flex justify-between items-center">
                            <h2 className="text-2xl font-black text-gray-800">Mapas da Congregação</h2>
                            <button onClick={() => setShowAddModal(true)} className="px-6 py-3 bg-gray-900 text-white font-black rounded-xl hover:bg-black transition-all transform active:scale-95 shadow-xl shadow-gray-200">
                                + NOVO MAPA
                            </button>
                        </div>
                        <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-4 bg-slate-100/50">
                            {sortedTerritories.map(m => {
                                const recent = isRecentWork(m.history);
                                return (
                                    <div key={m.id} className="bg-white/80 p-6 rounded-2xl shadow-lg shadow-indigo-100/50 flex flex-col gap-4 border-[5px] border-slate-200">
                                        <div className="flex justify-between items-start">
                                            <div>
                                                <p className="font-black text-gray-900 text-xl">{m.name}</p>
                                                <button onClick={() => setViewingMap(m)} className="text-xs text-blue-500 font-bold hover:underline">Ver Arquivo &rarr;</button>
                                            </div>
                                            {m.status === TerritoryStatus.IN_USE ? (
                                                <span className="px-4 py-1.5 bg-blue-50 text-blue-600 rounded-full text-xs font-black uppercase">Em Uso</span>
                                            ) : recent ? (
                                                <span className="px-4 py-1.5 bg-amber-50 text-amber-600 rounded-full text-xs font-black uppercase">Descanso</span>
                                            ) : (
                                                <span className="px-4 py-1.5 bg-emerald-50 text-emerald-600 rounded-full text-xs font-black uppercase">Disponível</span>
                                            )}
                                        </div>
                                        <div className="grid grid-cols-2 gap-4">
                                            <div>
                                                <p className="text-xs font-bold text-gray-400 uppercase">Responsável</p>
                                                <p className="font-bold text-gray-700 truncate">{m.assignedToName || '-'}</p>
                                                {m.dueDate && <p className="text-xs text-red-500 font-bold">Vence em {formatDate(m.dueDate)}</p>}
                                            </div>
                                            <div>
                                                <p className="text-xs font-bold text-gray-400 uppercase">Último Trabalho</p>
                                                <p className="text-sm font-bold text-gray-600">{m.history && m.history.length > 0 ? formatDate(m.history[0].completedDate) : 'Nunca'}</p>
                                            </div>
                                        </div>
                                        <div className="border-t border-slate-200/80 mt-2 pt-4 flex justify-end gap-1">
                                             <button onClick={() => setEditingTerritory(m)} className="p-3 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-xl transition-all" title="Editar Mapa">
                                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.5L15.232 5.232z"></path></svg>
                                            </button>
                                            <button onClick={() => setViewHistory(m)} className="p-3 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all" title="Ver Histórico">
                                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                                            </button>
                                            {m.status === TerritoryStatus.IN_USE && (
                                                <button onClick={() => handleResetTerritory(m.id)} className="p-3 text-gray-400 hover:text-amber-600 hover:bg-amber-50 rounded-xl transition-all" title="Retomar Mapa">
                                                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 10h10a8 8 0 018 8v2M3 10l5 5m-5-5l5-5" /></svg>
                                                </button>
                                            )}
                                            <button onClick={() => handleDeleteTerritory(m.id)} className="p-3 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all" title="Excluir">
                                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                            </button>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                </>
            ) : (
                <div className="bg-white/70 rounded-3xl border-2 border-slate-200 shadow-2xl shadow-violet-200/60 overflow-hidden">
                    <div className="p-8 border-b-2 border-slate-200">
                        <h2 className="text-2xl font-black text-gray-800">Usuários Cadastrados</h2>
                    </div>
                    <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-4 bg-slate-100/50">
                        {users.map(u => (
                            <div key={u.id} className="bg-white/80 p-6 rounded-2xl shadow-lg flex items-center justify-between gap-4 border-[5px] border-slate-200">
                                <div className="flex-1">
                                    <p className="font-black text-gray-900 text-lg truncate">{u.name}</p>
                                    <p className="font-medium text-gray-500 text-sm truncate">{u.email}</p>
                                    <span className={`mt-2 inline-block px-3 py-1 rounded-full text-xs font-black uppercase ${u.role === 'admin' ? 'bg-purple-50 text-purple-600' : 'bg-gray-100 text-gray-500'}`}>
                                        {u.role}
                                    </span>
                                </div>
                                <div className="flex-shrink-0">
                                    <button onClick={() => handlePromote(u)} className="px-4 py-2 bg-gray-100 text-gray-600 text-xs font-black rounded-lg hover:bg-gray-900 hover:text-white transition-all">
                                        ALTERAR CARGO
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

export default AdminDashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { Territory, TerritoryRequest, TerritoryStatus, User, RequestStatus } from '../types';
import { 
    assignTerritoryToRequest, rejectRequest, 
    updateTerritory, deleteTerritory, updateUserRole, adminResetTerritory
} from '../services/api';
import { formatDate, isRecentWork } from '../utils/helpers';
import { collection, query, where, onSnapshot, Timestamp } from 'firebase/firestore';
import { db } from '../firebase/config';
import MapViewerModal from './modals/MapViewerModal';
import TerritoryHistoryModal from './modals/TerritoryHistoryModal';
import AddMapModal from './modals/AddMapModal';
import EditMapModal from './modals/EditMapModal';
import { MapIcon } from './Icon';

const AdminDashboard: React.FC = () => {
    const [territories, setTerritories] = useState<Territory[]>([]);
    const [requests, setRequests] = useState<TerritoryRequest[]>([]);
    const [users, setUsers] = useState<User[]>([]);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState<'territories' | 'users'>('territories');

    // UI States
    const [showAddModal, setShowAddModal] = useState(false);
    const [editingTerritory, setEditingTerritory] = useState<Territory | null>(null);
    const [viewHistory, setViewHistory] = useState<Territory | null>(null);
    const [viewingMap, setViewingMap] = useState<Territory | null>(null);
    const [fulfillingRequestId, setFulfillingRequestId] = useState<string | null>(null);
    const [selectedMapForRequest, setSelectedMapForRequest] = useState<string>('');

    // Listener para todos os dados em tempo real
    useEffect(() => {
        // Listener de Territórios
        const territoriesQuery = query(collection(db, 'territories'));
        const unsubscribeTerritories = onSnapshot(territoriesQuery, (snapshot) => {
            const territoriesList = snapshot.docs.map(doc => {
                const data = doc.data();
                const rawHistory = data.history || [];
                const history = rawHistory.map((h: any) => ({
                    ...h,
                    completedDate: h.completedDate instanceof Timestamp 
                        ? h.completedDate.toDate() 
                        : new Date(h.completedDate)
                })).sort((a: any, b: any) => b.completedDate.getTime() - a.completedDate.getTime());

                return {
                    ...data,
                    id: doc.id,
                    name: data.name || 'Sem Nome',
                    createdAt: data.createdAt?.toDate() || new Date(),
                    assignmentDate: data.assignmentDate?.toDate() || null,
                    dueDate: data.dueDate?.toDate() || null,
                    history: history
                } as Territory;
            });
            setTerritories(territoriesList);
            if (loading) setLoading(false);
        }, (error) => {
            console.error("Erro ao carregar territórios:", error);
            if (loading) setLoading(false);
        });

        // Listener de Usuários
        const usersQuery = query(collection(db, 'users'));
        const unsubscribeUsers = onSnapshot(usersQuery, (snapshot) => {
            const usersList = snapshot.docs.map(doc => {
                 const data = doc.data();
                 return { 
                    ...data, 
                    id: doc.id,
                    name: data.name || data.email?.split('@')[0] || 'Sem Nome',
                    createdAt: data.createdAt?.toDate() || new Date()
                 } as User;
            }).sort((a, b) => (a.name || '').localeCompare(b.name || ''));
            setUsers(usersList);
        });

        // Listener de Solicitações
        const requestsQuery = query(collection(db, 'requests'), where('status', '==', RequestStatus.PENDING));
        const unsubscribeRequests = onSnapshot(requestsQuery, (snapshot) => {
            const reqs = snapshot.docs.map(doc => ({
                ...doc.data(),
                id: doc.id,
                requestDate: doc.data().requestDate?.toDate() || new Date()
            } as TerritoryRequest)).sort((a, b) => b.requestDate.getTime() - a.requestDate.getTime());
            setRequests(reqs);
        });

        return () => {
            unsubscribeTerritories();
            unsubscribeUsers();
            unsubscribeRequests();
        };
    }, [loading]);

    const handleFulfillRequest = async (requestId: string) => {
        if (!selectedMapForRequest) return;
        try {
            await assignTerritoryToRequest(requestId, selectedMapForRequest);
            setFulfillingRequestId(null);
            setSelectedMapForRequest('');
        } catch (e: any) { alert(e.message); }
    };

    const handleReject = async (id: string) => {
        if (!confirm("Rejeitar esta solicitação?")) return;
        await rejectRequest(id);
    };

    const handleDeleteTerritory = async (id: string) => {
        if (!confirm("Tem certeza que deseja excluir este território?")) return;
        await deleteTerritory(id);
    };

    const handleResetTerritory = async (id: string) => {
        if (!confirm("Deseja retomar este território? Ele voltará a ficar disponível sem precisar de relatório.")) return;
        await adminResetTerritory(id);
    };

    const handlePromote = async (user: User) => {
        const newRole = user.role === 'admin' ? 'user' : 'admin';
        await updateUserRole(user.id, newRole);
    };

    const sortedTerritories = useMemo(() => {
        return [...territories].sort((a, b) => {
            if (a.status === TerritoryStatus.IN_USE && b.status !== TerritoryStatus.IN_USE) return 1;
            if (b.status === TerritoryStatus.IN_USE && a.status !== TerritoryStatus.IN_USE) return -1;

            const aRecent = isRecentWork(a.history);
            const bRecent = isRecentWork(b.history);
            const aNeverWorked = (a.history || []).length === 0;
            const bNeverWorked = (b.history || []).length === 0;

            if (aNeverWorked && !bNeverWorked) return -1;
            if (bNeverWorked && !aNeverWorked) return 1;

            if (!aRecent && bRecent) return -1;
            if (aRecent && !bRecent) return 1;

            if (a.history && a.history.length > 0 && b.history && b.history.length > 0) {
                return b.history[0].completedDate.getTime() - a.history[0].completedDate.getTime();
            }

            return (a.name || '').localeCompare(b.name || '', undefined, { numeric: true });
        });
    }, [territories]);

    const availableMapsOptions = useMemo(() => {
        return sortedTerritories.filter(t => t.status === TerritoryStatus.AVAILABLE);
    }, [sortedTerritories]);

    const stats = useMemo(() => ({
        total: territories.length,
        available: territories.filter(t => t.status === TerritoryStatus.AVAILABLE && !isRecentWork(t.history)).length,
        resting: territories.filter(t => t.status === TerritoryStatus.AVAILABLE && isRecentWork(t.history)).length,
        inUse: territories.filter(t => t.status === TerritoryStatus.IN_USE).length,
    }), [territories]);

    if (loading) return (
        <div className="flex flex-col items-center justify-center p-20 space-y-4">
            <div className="animate-spin h-12 w-12 border-4 border-blue-600 border-t-transparent rounded-full"></div>
            <p className="text-gray-500 font-bold">Carregando painel...</p>
        </div>
    );

    return (
        <div className="max-w-6xl mx-auto space-y-8 pb-20">
            {showAddModal && <AddMapModal onClose={() => setShowAddModal(false)} onAdded={() => {}} />}
            {editingTerritory && <EditMapModal territory={editingTerritory} onClose={() => setEditingTerritory(null)} onSave={() => {}} />}
            {viewHistory && <TerritoryHistoryModal territory={viewHistory} onClose={() => setViewHistory(null)} />}
            {viewingMap && <MapViewerModal url={viewingMap.pdfUrl} name={viewingMap.name} onClose={() => setViewingMap(null)} />}

            <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                <div className="flex items-center gap-4">
                    <div className="w-16 h-16 bg-white rounded-full shadow-md border border-slate-100 overflow-hidden">
                        <MapIcon className="w-full h-full"/>
                    </div>
                    <div>
                        <h1 className="text-4xl font-black text-gray-900 tracking-tight">Painel Admin</h1>
                        <p className="text-gray-500 font-medium mt-1">Gestão de Congregação</p>
                    </div>
                </div>
                <div className="flex bg-white p-1.5 rounded-2xl self-start md:self-auto shadow-sm border border-slate-200">
                    <button 
                        onClick={() => setActiveTab('territories')} 
                        className={`px-6 py-2 text-sm font-bold rounded-xl transition-all ${activeTab === 'territories' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                        Mapas
                    </button>
                    <button 
                        onClick={() => setActiveTab('users')} 
                        className={`px-6 py-2 text-sm font-bold rounded-xl transition-all ${activeTab === 'users' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                        Usuários
                    </button>
                </div>
            </div>

            {activeTab === 'territories' ? (
                <>
                    {/* Estatísticas - Agora sólidas */}
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                        {[
                            { label: 'Total', value: stats.total, color: 'text-gray-900' },
                            { label: 'Disponíveis', value: stats.available, color: 'text-emerald-600' },
                            { label: 'Em Descanso', value: stats.resting, color: 'text-amber-500' },
                            { label: 'Em Uso', value: stats.inUse, color: 'text-blue-600' }
                        ].map(s => (
                            <div key={s.label} className="bg-white p-6 rounded-3xl border-2 border-slate-200 shadow-xl">
                                <p className="text-xs font-black text-gray-400 uppercase mb-1">{s.label}</p>
                                <p className={`text-3xl font-black ${s.color}`}>{s.value}</p>
                            </div>
                        ))}
                    </div>

                    {/* Solicitações Pendentes - Sólidas */}
                    {requests.length > 0 && (
                        <div className="bg-white border-2 border-slate-200 rounded-[2rem] p-8 shadow-xl">
                            <h2 className="text-xl font-black text-blue-900 mb-6 flex items-center gap-2">
                                <span className="flex h-3 w-3 rounded-full bg-blue-600 animate-pulse"></span>
                                Solicitações Pendentes ({requests.length})
                            </h2>
                            <div className="space-y-4">
                                {requests.map(req => (
                                    <div key={req.id} className="bg-slate-50 p-6 rounded-2xl flex flex-col md:flex-row items-center justify-between gap-6 border-2 border-slate-100">
                                        <div>
                                            <p className="font-black text-gray-900 text-lg">{req.userName}</p>
                                            <p className="text-sm text-gray-500 font-medium">Solicitado em {formatDate(req.requestDate)}</p>
                                        </div>

                                        <div className="flex flex-1 max-w-md items-center gap-3">
                                            {fulfillingRequestId === req.id ? (
                                                <div className="flex items-center gap-2 w-full">
                                                    <select 
                                                        value={selectedMapForRequest} 
                                                        onChange={e => setSelectedMapForRequest(e.target.value)}
                                                        className="flex-1 px-4 py-3 bg-white border-2 border-slate-200 rounded-xl font-bold text-sm outline-none focus:ring-2 focus:ring-blue-500"
                                                    >
                                                        <option value="">Selecione um mapa disponível...</option>
                                                        {availableMapsOptions.map(m => (
                                                            <option key={m.id} value={m.id}>{m.name} {isRecentWork(m.history) ? '(Em Descanso)' : ''}</option>
                                                        ))}
                                                    </select>
                                                    <button onClick={() => handleFulfillRequest(req.id)} disabled={!selectedMapForRequest} className="px-6 py-3 bg-emerald-600 text-white font-black rounded-xl hover:bg-emerald-700 disabled:bg-gray-200">OK</button>
                                                    <button onClick={() => setFulfillingRequestId(null)} className="px-4 py-3 bg-gray-200 text-gray-500 font-black rounded-xl">&times;</button>
                                                </div>
                                            ) : (
                                                <div className="flex gap-3">
                                                    <button onClick={() => setFulfillingRequestId(req.id)} className="px-8 py-3 bg-blue-600 text-white font-black rounded-xl hover:bg-blue-700 shadow-md">Atribuir Mapa</button>
                                                    <button onClick={() => handleReject(req.id)} className="px-8 py-3 bg-white text-gray-500 border-2 border-slate-200 font-black rounded-xl hover:bg-slate-50">Recusar</button>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Lista de Mapas - Aqui a correção principal */}
                    <div className="bg-white rounded-3xl border-2 border-slate-200 shadow-xl overflow-hidden">
                        <div className="p-8 border-b-2 border-slate-100 flex justify-between items-center">
                            <h2 className="text-2xl font-black text-gray-800">Mapas da Congregação</h2>
                            <button onClick={() => setShowAddModal(true)} className="px-6 py-3 bg-gray-900 text-white font-black rounded-xl hover:bg-black transition-all transform active:scale-95 shadow-lg">
                                + NOVO MAPA
                            </button>
                        </div>
                        {/* Fundo levemente cinza para destacar os cartões brancos sólidos */}
                        <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6 bg-slate-50/80">
                            {sortedTerritories.map(m => {
                                const recent = isRecentWork(m.history);
                                return (
                                    <div key={m.id} className="bg-white p-6 rounded-2xl shadow-md flex flex-col gap-4 border-[5px] border-slate-200 hover:border-blue-200 transition-colors">
                                        <div className="flex justify-between items-start">
                                            <div>
                                                <p className="font-black text-gray-900 text-xl">{m.name}</p>
                                                <button onClick={() => setViewingMap(m)} className="text-xs text-blue-500 font-bold hover:underline">Ver Arquivo &rarr;</button>
                                            </div>
                                            {m.status === TerritoryStatus.IN_USE ? (
                                                <span className="px-4 py-1.5 bg-blue-100 text-blue-700 rounded-full text-[10px] font-black uppercase">Em Uso</span>
                                            ) : recent ? (
                                                <span className="px-4 py-1.5 bg-amber-100 text-amber-700 rounded-full text-[10px] font-black uppercase">Descanso</span>
                                            ) : (
                                                <span className="px-4 py-1.5 bg-emerald-100 text-emerald-700 rounded-full text-[10px] font-black uppercase">Disponível</span>
                                            )}
                                        </div>
                                        <div className="grid grid-cols-2 gap-4">
                                            <div>
                                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-wider">Responsável</p>
                                                <p className="font-bold text-gray-700 truncate">{m.assignedToName || '-'}</p>
                                                {m.dueDate && <p className="text-[10px] text-red-500 font-black mt-1">Vence em {formatDate(m.dueDate)}</p>}
                                            </div>
                                            <div>
                                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-wider">Último Trabalho</p>
                                                <p className="text-sm font-bold text-gray-600">{m.history && m.history.length > 0 ? formatDate(m.history[0].completedDate) : 'Nunca'}</p>
                                            </div>
                                        </div>
                                        <div className="border-t border-slate-100 mt-2 pt-4 flex justify-end gap-1">
                                             <button onClick={() => setEditingTerritory(m)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all" title="Editar Mapa">
                                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.5L15.232 5.232z"></path></svg>
                                            </button>
                                            <button onClick={() => setViewHistory(m)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all" title="Ver Histórico">
                                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                                            </button>
                                            {m.status === TerritoryStatus.IN_USE && (
                                                <button onClick={() => handleResetTerritory(m.id)} className="p-2 text-slate-400 hover:text-amber-600 hover:bg-amber-50 rounded-lg transition-all" title="Retomar Mapa">
                                                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M3 10h10a8 8 0 018 8v2M3 10l5 5m-5-5l5-5" /></svg>
                                                </button>
                                            )}
                                            <button onClick={() => handleDeleteTerritory(m.id)} className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all" title="Excluir">
                                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                            </button>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                </>
            ) : (
                <div className="bg-white rounded-3xl border-2 border-slate-200 shadow-xl overflow-hidden">
                    <div className="p-8 border-b-2 border-slate-100">
                        <h2 className="text-2xl font-black text-gray-800">Usuários Cadastrados</h2>
                    </div>
                    <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6 bg-slate-50/80">
                        {users.map(u => (
                            <div key={u.id} className="bg-white p-6 rounded-2xl shadow-md flex items-center justify-between gap-4 border-[5px] border-slate-200">
                                <div className="flex-1">
                                    <p className="font-black text-gray-900 text-lg truncate">{u.name}</p>
                                    <p className="font-medium text-gray-500 text-sm truncate">{u.email}</p>
                                    <span className={`mt-2 inline-block px-3 py-1 rounded-full text-[10px] font-black uppercase ${u.role === 'admin' ? 'bg-purple-100 text-purple-700' : 'bg-slate-100 text-slate-600'}`}>
                                        {u.role}
                                    </span>
                                </div>
                                <div className="flex-shrink-0">
                                    <button onClick={() => handlePromote(u)} className="px-4 py-2 bg-slate-100 text-slate-600 text-[10px] font-black rounded-lg hover:bg-gray-900 hover:text-white transition-all border border-slate-200">
                                        ALTERAR CARGO
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

export default AdminDashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { Territory, TerritoryRequest, TerritoryStatus, User, RequestStatus } from '../types';
import { 
    assignTerritoryToRequest, rejectRequest, 
    updateTerritory, deleteTerritory, updateUserRole, adminResetTerritory
} from '../services/api';
import { formatDate, isRecentWork } from '../utils/helpers';
import { collection, query, where, onSnapshot, Timestamp } from 'firebase/firestore';
import { db } from '../firebase/config';
import MapViewerModal from './modals/MapViewerModal';
import TerritoryHistoryModal from './modals/TerritoryHistoryModal';
import AddMapModal from './modals/AddMapModal';
import EditMapModal from './modals/EditMapModal';
import { MapIcon } from './Icon';

const AdminDashboard: React.FC = () => {
    const [territories, setTerritories] = useState<Territory[]>([]);
    const [requests, setRequests] = useState<TerritoryRequest[]>([]);
    const [users, setUsers] = useState<User[]>([]);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState<'territories' | 'users'>('territories');

    // UI States
    const [showAddModal, setShowAddModal] = useState(false);
    const [editingTerritory, setEditingTerritory] = useState<Territory | null>(null);
    const [viewHistory, setViewHistory] = useState<Territory | null>(null);
    const [viewingMap, setViewingMap] = useState<Territory | null>(null);
    const [fulfillingRequestId, setFulfillingRequestId] = useState<string | null>(null);
    const [selectedMapForRequest, setSelectedMapForRequest] = useState<string>('');

    // Listener para todos os dados em tempo real
    useEffect(() => {
        // Listener de Territórios
        const territoriesQuery = query(collection(db, 'territories'));
        const unsubscribeTerritories = onSnapshot(territoriesQuery, (snapshot) => {
            const territoriesList = snapshot.docs.map(doc => {
                const data = doc.data();
                const rawHistory = data.history || [];
                const history = rawHistory.map((h: any) => ({
                    ...h,
                    completedDate: h.completedDate instanceof Timestamp 
                        ? h.completedDate.toDate() 
                        : new Date(h.completedDate)
                })).sort((a: any, b: any) => b.completedDate.getTime() - a.completedDate.getTime());

                return {
                    ...data,
                    id: doc.id,
                    name: data.name || 'Sem Nome',
                    createdAt: data.createdAt?.toDate() || new Date(),
                    assignmentDate: data.assignmentDate?.toDate() || null,
                    dueDate: data.dueDate?.toDate() || null,
                    history: history
                } as Territory;
            });
            setTerritories(territoriesList);
            if (loading) setLoading(false);
        }, (error) => {
            console.error("Erro ao carregar territórios:", error);
            if (loading) setLoading(false);
        });

        // Listener de Usuários
        const usersQuery = query(collection(db, 'users'));
        const unsubscribeUsers = onSnapshot(usersQuery, (snapshot) => {
            const usersList = snapshot.docs.map(doc => {
                 const data = doc.data();
                 return { 
                    ...data, 
                    id: doc.id,
                    name: data.name || data.email?.split('@')[0] || 'Sem Nome',
                    createdAt: data.createdAt?.toDate() || new Date()
                 } as User;
            }).sort((a, b) => (a.name || '').localeCompare(b.name || ''));
            setUsers(usersList);
        });

        // Listener de Solicitações
        const requestsQuery = query(collection(db, 'requests'), where('status', '==', RequestStatus.PENDING));
        const unsubscribeRequests = onSnapshot(requestsQuery, (snapshot) => {
            const reqs = snapshot.docs.map(doc => ({
                ...doc.data(),
                id: doc.id,
                requestDate: doc.data().requestDate?.toDate() || new Date()
            } as TerritoryRequest)).sort((a, b) => b.requestDate.getTime() - a.requestDate.getTime());
            setRequests(reqs);
        });

        return () => {
            unsubscribeTerritories();
            unsubscribeUsers();
            unsubscribeRequests();
        };
    }, [loading]);

    const handleFulfillRequest = async (requestId: string) => {
        if (!selectedMapForRequest) return;
        try {
            await assignTerritoryToRequest(requestId, selectedMapForRequest);
            setFulfillingRequestId(null);
            setSelectedMapForRequest('');
        } catch (e: any) { alert(e.message); }
    };

    const handleReject = async (id: string) => {
        if (!confirm("Rejeitar esta solicitação?")) return;
        await rejectRequest(id);
    };

    const handleDeleteTerritory = async (id: string) => {
        if (!confirm("Tem certeza que deseja excluir este território?")) return;
        await deleteTerritory(id);
    };

    const handleResetTerritory = async (id: string) => {
        if (!confirm("Deseja retomar este território? Ele voltará a ficar disponível sem precisar de relatório.")) return;
        await adminResetTerritory(id);
    };

    const handlePromote = async (user: User) => {
        const newRole = user.role === 'admin' ? 'user' : 'admin';
        await updateUserRole(user.id, newRole);
    };

    const sortedTerritories = useMemo(() => {
        return [...territories].sort((a, b) => {
            if (a.status === TerritoryStatus.IN_USE && b.status !== TerritoryStatus.IN_USE) return 1;
            if (b.status === TerritoryStatus.IN_USE && a.status !== TerritoryStatus.IN_USE) return -1;

            const aRecent = isRecentWork(a.history);
            const bRecent = isRecentWork(b.history);
            const aNeverWorked = (a.history || []).length === 0;
            const bNeverWorked = (b.history || []).length === 0;

            if (aNeverWorked && !bNeverWorked) return -1;
            if (bNeverWorked && !aNeverWorked) return 1;

            if (!aRecent && bRecent) return -1;
            if (aRecent && !bRecent) return 1;

            if (a.history && a.history.length > 0 && b.history && b.history.length > 0) {
                return b.history[0].completedDate.getTime() - a.history[0].completedDate.getTime();
            }

            return (a.name || '').localeCompare(b.name || '', undefined, { numeric: true });
        });
    }, [territories]);

    const availableMapsOptions = useMemo(() => {
        return sortedTerritories.filter(t => t.status === TerritoryStatus.AVAILABLE);
    }, [sortedTerritories]);

    const stats = useMemo(() => ({
        total: territories.length,
        available: territories.filter(t => t.status === TerritoryStatus.AVAILABLE && !isRecentWork(t.history)).length,
        resting: territories.filter(t => t.status === TerritoryStatus.AVAILABLE && isRecentWork(t.history)).length,
        inUse: territories.filter(t => t.status === TerritoryStatus.IN_USE).length,
    }), [territories]);

    if (loading) return (
        <div className="flex flex-col items-center justify-center p-20 space-y-4">
            <div className="animate-spin h-12 w-12 border-4 border-blue-600 border-t-transparent rounded-full"></div>
            <p className="text-gray-500 font-bold">Carregando painel...</p>
        </div>
    );

    return (
        <div className="max-w-6xl mx-auto space-y-10 pb-20">
            {showAddModal && <AddMapModal onClose={() => setShowAddModal(false)} onAdded={() => {}} />}
            {editingTerritory && <EditMapModal territory={editingTerritory} onClose={() => setEditingTerritory(null)} onSave={() => {}} />}
            {viewHistory && <TerritoryHistoryModal territory={viewHistory} onClose={() => setViewHistory(null)} />}
            {viewingMap && <MapViewerModal url={viewingMap.pdfUrl} name={viewingMap.name} onClose={() => setViewingMap(null)} />}

            {/* Cabeçalho do Painel */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 px-1">
                <div className="flex items-center gap-4">
                    <div className="w-14 h-14 bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden flex-shrink-0">
                        <MapIcon className="w-full h-full"/>
                    </div>
                    <div>
                        <h1 className="text-3xl font-black text-gray-900 tracking-tight leading-none">Painel Administrativo</h1>
                        <p className="text-slate-500 font-bold text-sm mt-1">Gestão de Congregação</p>
                    </div>
                </div>
                <div className="flex bg-white p-1 rounded-2xl shadow-sm border border-slate-200 self-start md:self-auto">
                    <button 
                        onClick={() => setActiveTab('territories')} 
                        className={`px-6 py-2.5 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === 'territories' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
                    >
                        Mapas
                    </button>
                    <button 
                        onClick={() => setActiveTab('users')} 
                        className={`px-6 py-2.5 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === 'users' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
                    >
                        Usuários
                    </button>
                </div>
            </div>

            {activeTab === 'territories' ? (
                <>
                    {/* Estatísticas Individuais */}
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                        {[
                            { label: 'Total', value: stats.total, color: 'text-slate-900', border: 'border-slate-200' },
                            { label: 'Livres', value: stats.available, color: 'text-emerald-600', border: 'border-emerald-200' },
                            { label: 'Descanso', value: stats.resting, color: 'text-amber-500', border: 'border-amber-200' },
                            { label: 'Em Uso', value: stats.inUse, color: 'text-blue-600', border: 'border-blue-200' }
                        ].map(s => (
                            <div key={s.label} className={`bg-white p-5 rounded-3xl border-2 ${s.border} shadow-sm`}>
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{s.label}</p>
                                <p className={`text-3xl font-black ${s.color}`}>{s.value}</p>
                            </div>
                        ))}
                    </div>

                    {/* Solicitações Pendentes */}
                    {requests.length > 0 && (
                        <div className="space-y-4">
                            <h2 className="text-sm font-black text-blue-900 uppercase tracking-[0.2em] px-2 flex items-center gap-2">
                                <span className="w-2 h-2 rounded-full bg-blue-600 animate-ping"></span>
                                Solicitações ({requests.length})
                            </h2>
                            <div className="space-y-3">
                                {requests.map(req => (
                                    <div key={req.id} className="bg-white p-5 rounded-2xl flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-2 border-slate-200 shadow-sm">
                                        <div>
                                            <p className="font-black text-slate-900 text-lg">{req.userName}</p>
                                            <p className="text-xs text-slate-400 font-bold">Solicitado em {formatDate(req.requestDate)}</p>
                                        </div>
                                        <div className="flex flex-1 max-w-md items-center gap-2">
                                            {fulfillingRequestId === req.id ? (
                                                <div className="flex items-center gap-2 w-full animate-in slide-in-from-right-2">
                                                    <select 
                                                        value={selectedMapForRequest} 
                                                        onChange={e => setSelectedMapForRequest(e.target.value)}
                                                        className="flex-1 px-4 py-3 bg-slate-50 border-2 border-slate-200 rounded-xl font-bold text-sm outline-none focus:ring-2 focus:ring-blue-500"
                                                    >
                                                        <option value="">Escolher mapa...</option>
                                                        {availableMapsOptions.map(m => (
                                                            <option key={m.id} value={m.id}>{m.name} {isRecentWork(m.history) ? '(Descanso)' : ''}</option>
                                                        ))}
                                                    </select>
                                                    <button onClick={() => handleFulfillRequest(req.id)} disabled={!selectedMapForRequest} className="px-5 py-3 bg-emerald-600 text-white font-black rounded-xl hover:bg-emerald-700 disabled:opacity-50">OK</button>
                                                    <button onClick={() => setFulfillingRequestId(null)} className="p-3 text-slate-400">&times;</button>
                                                </div>
                                            ) : (
                                                <div className="flex gap-2 w-full sm:w-auto">
                                                    <button onClick={() => setFulfillingRequestId(req.id)} className="flex-1 sm:flex-none px-6 py-3 bg-blue-600 text-white font-black text-xs uppercase tracking-widest rounded-xl hover:bg-blue-700 shadow-lg shadow-blue-100">Atribuir</button>
                                                    <button onClick={() => handleReject(req.id)} className="px-6 py-3 bg-slate-100 text-slate-500 font-black text-xs uppercase tracking-widest rounded-xl hover:bg-slate-200">Recusar</button>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Grade de Mapas - Removido o contêiner branco externo */}
                    <div className="space-y-6">
                        <div className="flex justify-between items-center px-2">
                            <h2 className="text-sm font-black text-slate-900 uppercase tracking-[0.2em]">Mapas Disponíveis</h2>
                            <button onClick={() => setShowAddModal(true)} className="px-5 py-3 bg-slate-900 text-white font-black text-[10px] uppercase tracking-widest rounded-xl hover:bg-black shadow-lg">
                                + Novo Mapa
                            </button>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {sortedTerritories.map(m => {
                                const recent = isRecentWork(m.history);
                                return (
                                    <div key={m.id} className="bg-white p-6 rounded-3xl border-[5px] border-slate-200 shadow-md hover:shadow-xl transition-all duration-300">
                                        <div className="flex justify-between items-start mb-4">
                                            <div>
                                                <h3 className="font-black text-slate-900 text-2xl tracking-tight">{m.name}</h3>
                                                <button onClick={() => setViewingMap(m)} className="text-[10px] text-blue-600 font-black uppercase tracking-widest hover:underline mt-1">Ver Documento &rarr;</button>
                                            </div>
                                            {m.status === TerritoryStatus.IN_USE ? (
                                                <span className="px-3 py-1 bg-blue-100 text-blue-700 rounded-lg text-[10px] font-black uppercase tracking-wider">Em Uso</span>
                                            ) : recent ? (
                                                <span className="px-3 py-1 bg-amber-100 text-amber-700 rounded-lg text-[10px] font-black uppercase tracking-wider">Descanso</span>
                                            ) : (
                                                <span className="px-3 py-1 bg-emerald-100 text-emerald-700 rounded-lg text-[10px] font-black uppercase tracking-wider">Livre</span>
                                            )}
                                        </div>

                                        <div className="grid grid-cols-2 gap-4 py-4 border-y border-slate-50">
                                            <div>
                                                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Responsável</p>
                                                <p className="font-bold text-slate-700 text-sm truncate">{m.assignedToName || 'Ninguém'}</p>
                                                {m.dueDate && <p className="text-[9px] text-red-500 font-black mt-1 uppercase">Vence: {formatDate(m.dueDate)}</p>}
                                            </div>
                                            <div>
                                                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Último Relatório</p>
                                                <p className="text-sm font-bold text-slate-600">{m.history && m.history.length > 0 ? formatDate(m.history[0].completedDate) : 'Sem registro'}</p>
                                            </div>
                                        </div>

                                        <div className="mt-4 flex justify-end gap-1">
                                             <button onClick={() => setEditingTerritory(m)} className="p-2.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all" title="Editar">
                                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.5L15.232 5.232z"></path></svg>
                                            </button>
                                            <button onClick={() => setViewHistory(m)} className="p-2.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all" title="Histórico">
                                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                                            </button>
                                            {m.status === TerritoryStatus.IN_USE && (
                                                <button onClick={() => handleResetTerritory(m.id)} className="p-2.5 text-slate-400 hover:text-amber-600 hover:bg-amber-50 rounded-xl transition-all" title="Retomar">
                                                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M3 10h10a8 8 0 018 8v2M3 10l5 5m-5-5l5-5" /></svg>
                                                </button>
                                            )}
                                            <button onClick={() => handleDeleteTerritory(m.id)} className="p-2.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all" title="Excluir">
                                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                            </button>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                </>
            ) : (
                <div className="space-y-6">
                    <h2 className="text-sm font-black text-slate-900 uppercase tracking-[0.2em] px-2">Gerenciamento de Usuários</h2>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {users.map(u => (
                            <div key={u.id} className="bg-white p-6 rounded-3xl border-[5px] border-slate-200 shadow-md flex items-center justify-between gap-4">
                                <div className="flex-1 overflow-hidden">
                                    <p className="font-black text-slate-900 text-xl truncate">{u.name}</p>
                                    <p className="font-bold text-slate-400 text-xs truncate mb-2">{u.email}</p>
                                    <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider ${u.role === 'admin' ? 'bg-indigo-100 text-indigo-700' : 'bg-slate-100 text-slate-500'}`}>
                                        {u.role}
                                    </span>
                                </div>
                                <button onClick={() => handlePromote(u)} className="px-4 py-3 bg-slate-50 text-slate-600 text-[10px] font-black rounded-xl hover:bg-slate-900 hover:text-white transition-all border-2 border-slate-200 flex-shrink-0">
                                    ALTERAR
                                </button>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

export default AdminDashboard;

export enum TerritoryStatus {
  AVAILABLE = 'disponivel',
  REQUESTED = 'solicitado',
  IN_USE = 'em_uso',
  CLOSED = 'fechado',
}

export enum RequestStatus {
  PENDING = 'pendente',
  APPROVED = 'aprovado',
  REJECTED = 'rejeitado',
}

export interface User {
  id: string;
  uid: string;
  email: string;
  name: string;
  role: 'admin' | 'user';
  active: boolean;
  createdAt: Date;
}

export interface TerritoryHistory {
  userId: string;
  userName: string;
  assignmentDate: Date;
  completedDate: Date;
  notes?: string;
}

export interface Territory {
  id: string;
  name: string;
  status: TerritoryStatus;
  pdfUrl: string;
  createdAt: Date;
  assignedTo: string | null;
  assignedToName: string | null;
  assignmentDate: Date | null;
  dueDate: Date | null;
  history: TerritoryHistory[];
  permanentNotes?: string;
}

export interface TerritoryRequest {
  id: string;
  userId: string;
  userName: string;
  requestDate: Date;
  status: RequestStatus;
}

export interface AppNotification {
  id: string;
  userId: string;
  message: string;
  type: 'info' | 'success' | 'warning';
  read: boolean;
  createdAt: Date;
}

import { 
    signInWithEmailAndPassword, 
    createUserWithEmailAndPassword, 
    signOut,
    updateProfile
} from 'firebase/auth';
import { 
    doc, 
    setDoc, 
    getDoc, 
    collection, 
    getDocs, 
    updateDoc, 
    deleteDoc, 
    query, 
    where, 
    addDoc, 
    Timestamp,
    runTransaction,
    limit,
    arrayUnion
} from 'firebase/firestore';
import { 
    ref, 
    uploadBytes, 
    getDownloadURL, 
    deleteObject,
    updateMetadata
} from 'firebase/storage';
import { auth, db, storage } from '../firebase/config';
import { User, Territory, TerritoryStatus, RequestStatus, TerritoryRequest, AppNotification, TerritoryHistory } from '../types';

// --- AUTH FUNCTIONS ---

export const saveFCMToken = async (userId: string, token: string) => {
    const userRef = doc(db, 'users', userId);
    await updateDoc(userRef, {
        fcmTokens: arrayUnion(token)
    });
};

export const apiLogin = async (email: string, pass: string): Promise<User> => {
    try {
        const userCredential = await signInWithEmailAndPassword(auth, email, pass);
        const userId = userCredential.user.uid;

        const userRef = doc(db, 'users', userId);
        const userDoc = await getDoc(userRef);

        if (!userDoc.exists()) {
            const userData: User = {
                id: userId,
                uid: userId,
                name: userCredential.user.displayName || email.split('@')[0] || 'Usuário',
                email: userCredential.user.email || email,
                role: 'user', 
                active: true,
                createdAt: new Date()
            };
            await setDoc(userRef, {
                ...userData,
                createdAt: Timestamp.fromDate(userData.createdAt)
            });
            return userData;
        }

        const data = userDoc.data();
        return { 
            ...data, 
            id: userDoc.id,
            name: data.name || data.nome || userCredential.user.displayName || email.split('@')[0] || 'Usuário',
            createdAt: data.createdAt?.toDate() || new Date()
        } as User;
    } catch (error: any) {
        console.error("Erro no apiLogin:", error);
        if (error.code === 'auth/invalid-credential' || error.code === 'auth/wrong-password' || error.code === 'auth/user-not-found') {
            throw new Error("E-mail ou senha incorretos. Verifique seus dados.");
        }
        if (error.code === 'auth/too-many-requests') {
            throw new Error("Muitas tentativas sem sucesso. Tente novamente mais tarde.");
        }
        throw new Error("Erro ao acessar o sistema. Tente novamente.");
    }
};

export const apiSignUp = async (name: string, email: string, pass: string): Promise<User> => {
    try {
        const userCredential = await createUserWithEmailAndPassword(auth, email, pass);
        const userId = userCredential.user.uid;

        await updateProfile(userCredential.user, { displayName: name });

        const usersSnapshot = await getDocs(query(collection(db, 'users'), limit(1)));
        const isFirstUser = usersSnapshot.empty;

        const newUser: User = {
            id: userId,
            uid: userId,
            name: name || 'Usuário',
            email: email,
            role: isFirstUser ? 'admin' : 'user', 
            active: true,
            createdAt: new Date()
        };

        await setDoc(doc(db, 'users', userId), {
            ...newUser,
            createdAt: Timestamp.fromDate(newUser.createdAt)
        });

        return newUser;
    } catch (error: any) {
        console.error("Erro no apiSignUp:", error);
        if (error.code === 'auth/email-already-in-use') {
            throw new Error("Este e-mail já está sendo utilizado.");
        }
        if (error.code === 'auth/weak-password') {
            throw new Error("A senha deve ter pelo menos 6 caracteres.");
        }
        throw new Error("Erro ao criar conta. Tente novamente.");
    }
};

export const apiLogout = async (): Promise<void> => {
    await signOut(auth);
};

// --- HELPERS ---
const hydrateHistory = (rawHistory: any[]): TerritoryHistory[] => {
    if (!rawHistory || rawHistory.length === 0) return [];

    return rawHistory.map((h: any) => {
        const completedDate = h.completedDate instanceof Timestamp 
            ? h.completedDate.toDate() 
            : new Date(h.completedDate || Date.now());

        let assignmentDate;
        if (h.assignmentDate) {
            assignmentDate = h.assignmentDate instanceof Timestamp 
                ? h.assignmentDate.toDate() 
                : new Date(h.assignmentDate);
        } else {
            assignmentDate = completedDate; // Fallback para registros antigos
        }

        return {
            ...h,
            assignmentDate,
            completedDate,
        };
    }).sort((a, b) => b.completedDate.getTime() - a.completedDate.getTime());
};


// --- TERRITORY FUNCTIONS ---

export const fetchAllTerritories = async (): Promise<Territory[]> => {
    try {
        const q = query(collection(db, 'territories'));
        const querySnapshot = await getDocs(q);

        const list = querySnapshot.docs.map(doc => {
            const data = doc.data();
            return {
                ...data,
                id: doc.id,
                name: data.name || 'Sem Nome',
                createdAt: data.createdAt?.toDate() || new Date(),
                assignmentDate: data.assignmentDate?.toDate() || null,
                dueDate: data.dueDate?.toDate() || null,
                history: hydrateHistory(data.history || [])
            } as Territory;
        });

        return list;
    } catch (error) {
        console.error("Erro ao buscar territórios:", error);
        throw error;
    }
};

export const createTerritory = async (name: string, url: string): Promise<void> => {
    try {
        const newTerritory = {
            name: name.trim(),
            status: TerritoryStatus.AVAILABLE,
            pdfUrl: url,
            createdAt: Timestamp.now(),
            history: [],
            permanentNotes: '',
            assignedTo: null,
            assignedToName: null,
            assignmentDate: null,
            dueDate: null
        };
        await addDoc(collection(db, 'territories'), newTerritory);
    } catch (error) {
        console.error("Erro ao criar território:", error);
        throw error;
    }
};

export const uploadTerritory = async (name: string, file: File): Promise<void> => {
    try {
        const fileName = `${Date.now()}_${file.name.replace(/\s+/g, '_')}`;
        const storageRef = ref(storage, `maps/${fileName}`);

        const metadata = { 
            contentType: file.type || 'application/pdf',
            contentDisposition: 'inline'
        };

        const snapshot = await uploadBytes(storageRef, file, metadata);

        const fileUrl = await getDownloadURL(snapshot.ref);
        await createTerritory(name, fileUrl);

    } catch (error: any) {
        console.error("Erro no upload:", error);
        throw new Error("Erro ao salvar arquivo no Storage.");
    }
};

export const updateTerritory = async (territoryId: string, data: Partial<Territory>): Promise<void> => {
    const territoryRef = doc(db, 'territories', territoryId);
    await updateDoc(territoryRef, data);
};

export const deleteTerritory = async (territoryId: string): Promise<void> => {
    const docRef = doc(db, 'territories', territoryId);
    const territoryDoc = await getDoc(docRef);
    if (territoryDoc.exists()) {
        const data = territoryDoc.data();
        if (data.pdfUrl && data.pdfUrl.includes('firebasestorage')) {
            try {
                const fileRef = ref(storage, data.pdfUrl);
                await deleteObject(fileRef);
            } catch (e) { console.error("Erro ao deletar arquivo:", e); }
        }
    }
    await deleteDoc(docRef);
};

export const adminResetTerritory = async (territoryId: string, adminUser: User): Promise<void> => {
    const territoryRef = doc(db, 'territories', territoryId);

    await runTransaction(db, async (transaction) => {
        const territoryDoc = await transaction.get(territoryRef);
        if (!territoryDoc.exists()) throw new Error("Território não encontrado.");

        const territoryData = territoryDoc.data();
        let newHistory = territoryData.history || [];

        // Adiciona um registro histórico apenas se o território estava de fato com alguém
        if (territoryData.assignedTo) {
            const historyEntry = {
                userId: territoryData.assignedTo,
                userName: territoryData.assignedToName,
                assignmentDate: territoryData.assignmentDate, // Já está como Timestamp do Firestore
                completedDate: Timestamp.now(),
                notes: `Território retomado pelo administrador (${adminUser.name}).`
            };
            newHistory.push(historyEntry);
        }

        transaction.update(territoryRef, {
            status: TerritoryStatus.AVAILABLE,
            assignedTo: null,
            assignedToName: null,
            assignmentDate: null,
            dueDate: null,
            history: newHistory
        });
    });
};


// --- USER MANAGEMENT ---

export const fetchAllUsers = async (): Promise<User[]> => {
    try {
        const querySnapshot = await getDocs(collection(db, 'users'));
        const list = querySnapshot.docs.map(doc => {
            const data = doc.data();
            return { 
                ...data, 
                id: doc.id,
                name: data.name || data.email?.split('@')[0] || 'Sem Nome',
                createdAt: data.createdAt?.toDate() || new Date()
            } as User;
        });
        return list.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
    } catch (error) {
        console.error("Erro ao buscar usuários:", error);
        throw error;
    }
};

export const updateUserRole = async (userId: string, role: 'admin' | 'user'): Promise<void> => {
    await updateDoc(doc(db, 'users', userId), { role });
};

// --- REQUESTS & ASSIGNMENTS ---

export const fetchAllRequests = async (): Promise<TerritoryRequest[]> => {
    try {
        const q = query(collection(db, 'requests'), where('status', '==', RequestStatus.PENDING));
        const querySnapshot = await getDocs(q);
        return querySnapshot.docs.map(doc => ({
            ...doc.data(),
            id: doc.id,
            requestDate: doc.data().requestDate?.toDate() || new Date()
        } as TerritoryRequest)).sort((a, b) => b.requestDate.getTime() - a.requestDate.getTime());
    } catch (error) {
        console.error("Erro ao buscar solicitações:", error);
        throw error;
    }
};

export const requestTerritory = async (user: User): Promise<void> => {
    const q = query(collection(db, 'requests'), where('userId', '==', user.id), where('status', '==', RequestStatus.PENDING));
    const existing = await getDocs(q);
    if (!existing.empty) throw new Error("Você já possui uma solicitação pendente.");

    await addDoc(collection(db, 'requests'), {
        userId: user.id,
        userName: user.name,
        requestDate: Timestamp.now(),
        status: RequestStatus.PENDING
    });

    // Notificar todos os administradores
    const qAdmins = query(collection(db, 'users'), where('role', '==', 'admin'));
    const adminsSnapshot = await getDocs(qAdmins);

    adminsSnapshot.forEach(adminDoc => {
        const adminId = adminDoc.id;
        addDoc(collection(db, 'notifications'), {
            userId: adminId,
            message: `${user.name} solicitou um novo território.`,
            type: 'info',
            read: false,
            createdAt: Timestamp.now()
        });
    });
};

export const assignTerritoryToRequest = async (requestId: string, territoryId: string): Promise<void> => {
    await runTransaction(db, async (transaction) => {
        const requestRef = doc(db, 'requests', requestId);
        const territoryRef = doc(db, 'territories', territoryId);
        const requestDoc = await transaction.get(requestRef);
        const territoryDoc = await transaction.get(territoryRef);

        if (!requestDoc.exists() || !territoryDoc.exists()) throw new Error("Erro de dados.");

        const reqData = requestDoc.data();
        const dueDate = new Date();
        dueDate.setDate(dueDate.getDate() + 30); 

        transaction.update(territoryRef, {
            status: TerritoryStatus.IN_USE,
            assignedTo: reqData.userId,
            assignedToName: reqData.userName,
            assignmentDate: Timestamp.now(),
            dueDate: Timestamp.fromDate(dueDate)
        });
        transaction.update(requestRef, { status: RequestStatus.APPROVED });

        const notifRef = doc(collection(db, 'notifications'));
        transaction.set(notifRef, {
            userId: reqData.userId,
            message: `Território ${territoryDoc.data().name} atribuído com sucesso.`,
            type: 'success',
            read: false,
            createdAt: Timestamp.now()
        });
    });
};

export const rejectRequest = async (requestId: string): Promise<void> => {
    await updateDoc(doc(db, 'requests', requestId), { status: RequestStatus.REJECTED });
};

export const submitReport = async (user: User, territory: Territory, notes: string): Promise<void> => {
    const territoryRef = doc(db, 'territories', territory.id);

    const historyEntry = {
        userId: user.id,
        userName: user.name,
        assignmentDate: territory.assignmentDate ? Timestamp.fromDate(territory.assignmentDate) : Timestamp.now(),
        completedDate: Timestamp.now(),
        notes: notes.trim()
    };

    const currentHistory = territory.history.map(h => ({
        ...h,
        assignmentDate: Timestamp.fromDate(h.assignmentDate),
        completedDate: Timestamp.fromDate(h.completedDate)
    }));

    await updateDoc(territoryRef, {
        status: TerritoryStatus.AVAILABLE,
        assignedTo: null,
        assignedToName: null,
        assignmentDate: null,
        dueDate: null,
        history: [...currentHistory, historyEntry]
    });
};

// --- NOTIFICATIONS ---

export const fetchNotifications = async (user: User): Promise<AppNotification[]> => {
    const q = query(collection(db, 'notifications'), where('userId', '==', user.id));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => ({
        ...doc.data(),
        id: doc.id,
        createdAt: doc.data().createdAt?.toDate() || new Date()
    } as AppNotification)).sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime()).slice(0, 20);
};

export const markNotificationsAsRead = async (ids: string[]): Promise<void> => {
    for (const id of ids) {
        await updateDoc(doc(db, 'notifications', id), { read: true });
    }
};

// --- PUBLISHER DATA ---

export const fetchPublisherData = async (userId: string): Promise<{ myTerritory: Territory | null, hasPendingRequest: boolean }> => {
    const territoriesQ = query(collection(db, 'territories'), where('assignedTo', '==', userId), where('status', '==', TerritoryStatus.IN_USE));
    const territorySnapshot = await getDocs(territoriesQ);

    let myTerritory: Territory | null = null;
    if (!territorySnapshot.empty) {
        const doc = territorySnapshot.docs[0];
        const data = doc.data();
        myTerritory = {
            id: doc.id,
            name: data.name || 'Sem Nome',
            status: data.status,
            pdfUrl: data.pdfUrl,
            createdAt: data.createdAt?.toDate() || new Date(),
            assignedTo: data.assignedTo,
            assignedToName: data.assignedToName,
            assignmentDate: data.assignmentDate?.toDate() || null,
            dueDate: data.dueDate?.toDate() || null,
            permanentNotes: data.permanentNotes || '',
            history: hydrateHistory(data.history || [])
        };
    }

    const requestQ = query(collection(db, 'requests'), where('userId', '==', userId), where('status', '==', RequestStatus.PENDING));
    const requestSnapshot = await getDocs(requestQ);

    return { myTerritory, hasPendingRequest: !requestSnapshot.empty };
};

import React, { useState, useEffect, useMemo } from 'react';
import { Territory, TerritoryRequest, TerritoryStatus, User, RequestStatus } from '../types';
import { 
    assignTerritoryToRequest, rejectRequest, 
    updateTerritory, deleteTerritory, updateUserRole, adminResetTerritory
} from '../services/api';
import { formatDate, isRecentWork } from '../utils/helpers';
import { collection, query, where, onSnapshot, Timestamp } from 'firebase/firestore';
import { db } from '../firebase/config';
import MapViewerModal from './modals/MapViewerModal';
import TerritoryHistoryModal from './modals/TerritoryHistoryModal';
import AddMapModal from './modals/AddMapModal';
import EditMapModal from './modals/EditMapModal';
import { MapIcon } from './Icon';
import { useAuth } from '../hooks/useAuth';

const AdminDashboard: React.FC = () => {
    const { user } = useAuth();
    const [territories, setTerritories] = useState<Territory[]>([]);
    const [requests, setRequests] = useState<TerritoryRequest[]>([]);
    const [users, setUsers] = useState<User[]>([]);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState<'territories' | 'users'>('territories');

    // UI States
    const [showAddModal, setShowAddModal] = useState(false);
    const [editingTerritory, setEditingTerritory] = useState<Territory | null>(null);
    const [viewHistory, setViewHistory] = useState<Territory | null>(null);
    const [viewingMap, setViewingMap] = useState<Territory | null>(null);
    const [fulfillingRequestId, setFulfillingRequestId] = useState<string | null>(null);
    const [selectedMapForRequest, setSelectedMapForRequest] = useState<string>('');

    // Listener para todos os dados em tempo real
    useEffect(() => {
        const territoriesQuery = query(collection(db, 'territories'));
        const unsubscribeTerritories = onSnapshot(territoriesQuery, (snapshot) => {
            const territoriesList = snapshot.docs.map(doc => {
                const data = doc.data();
                const rawHistory = data.history || [];
                const history = rawHistory.map((h: any) => {
                    const completed = h.completedDate?.toDate() ?? new Date();
                    return {
                        ...h,
                        assignmentDate: h.assignmentDate?.toDate() ?? completed,
                        completedDate: completed
                    };
                }).sort((a,b) => b.completedDate.getTime() - a.completedDate.getTime());

                return {
                    ...data,
                    id: doc.id,
                    name: data.name || 'Sem Nome',
                    createdAt: data.createdAt?.toDate() || new Date(),
                    assignmentDate: data.assignmentDate?.toDate() || null,
                    dueDate: data.dueDate?.toDate() || null,
                    history: history
                } as Territory;
            });
            setTerritories(territoriesList);
            if (loading) setLoading(false);
        });

        const usersQuery = query(collection(db, 'users'));
        const unsubscribeUsers = onSnapshot(usersQuery, (snapshot) => {
            const usersList = snapshot.docs.map(doc => {
                 const data = doc.data();
                 return { 
                    ...data, 
                    id: doc.id,
                    name: data.name || data.email?.split('@')[0] || 'Sem Nome',
                    createdAt: data.createdAt?.toDate() || new Date()
                 } as User;
            }).sort((a, b) => (a.name || '').localeCompare(b.name || ''));
            setUsers(usersList);
        });

        const requestsQuery = query(collection(db, 'requests'), where('status', '==', RequestStatus.PENDING));
        const unsubscribeRequests = onSnapshot(requestsQuery, (snapshot) => {
            const reqs = snapshot.docs.map(doc => ({
                ...doc.data(),
                id: doc.id,
                requestDate: doc.data().requestDate?.toDate() || new Date()
            } as TerritoryRequest)).sort((a, b) => b.requestDate.getTime() - a.requestDate.getTime());
            setRequests(reqs);
        });

        return () => {
            unsubscribeTerritories();
            unsubscribeUsers();
            unsubscribeRequests();
        };
    }, [loading]);

    const handleFulfillRequest = async (requestId: string) => {
        if (!selectedMapForRequest) return;
        try {
            await assignTerritoryToRequest(requestId, selectedMapForRequest);
            setFulfillingRequestId(null);
            setSelectedMapForRequest('');
        } catch (e: any) { alert(e.message); }
    };

    const handleReject = async (id: string) => {
        if (!confirm("Rejeitar esta solicitação?")) return;
        await rejectRequest(id);
    };

    const handleDeleteTerritory = async (id: string) => {
        if (!confirm("Tem certeza que deseja excluir este território?")) return;
        await deleteTerritory(id);
    };

    const handleResetTerritory = async (id: string) => {
        if (!user) {
            alert("Erro: usuário administrador não encontrado.");
            return;
        }
        if (!confirm("Deseja retomar este território? Ele voltará a ficar disponível e a ação será registrada no histórico.")) return;
        await adminResetTerritory(id, user);
    };

    const handlePromote = async (user: User) => {
        const newRole = user.role === 'admin' ? 'user' : 'admin';
        await updateUserRole(user.id, newRole);
    };

    const sortedTerritories = useMemo(() => {
        return [...territories].sort((a, b) => {
            if (a.status === TerritoryStatus.IN_USE && b.status !== TerritoryStatus.IN_USE) return 1;
            if (b.status === TerritoryStatus.IN_USE && a.status !== TerritoryStatus.IN_USE) return -1;
            const aRecent = isRecentWork(a.history);
            const bRecent = isRecentWork(b.history);
            const aNeverWorked = (a.history || []).length === 0;
            const bNeverWorked = (b.history || []).length === 0;
            if (aNeverWorked && !bNeverWorked) return -1;
            if (bNeverWorked && !aNeverWorked) return 1;
            if (!aRecent && bRecent) return -1;
            if (aRecent && !bRecent) return 1;
            if (a.history && a.history.length > 0 && b.history && b.history.length > 0) {
                return b.history[0].completedDate.getTime() - a.history[0].completedDate.getTime();
            }
            return (a.name || '').localeCompare(b.name || '', undefined, { numeric: true });
        });
    }, [territories]);

    const availableMapsOptions = useMemo(() => {
        return sortedTerritories.filter(t => t.status === TerritoryStatus.AVAILABLE);
    }, [sortedTerritories]);

    const stats = useMemo(() => ({
        total: territories.length,
        available: territories.filter(t => t.status === TerritoryStatus.AVAILABLE && !isRecentWork(t.history)).length,
        resting: territories.filter(t => t.status === TerritoryStatus.AVAILABLE && isRecentWork(t.history)).length,
        inUse: territories.filter(t => t.status === TerritoryStatus.IN_USE).length,
    }), [territories]);

    if (loading) return (
        <div className="flex flex-col items-center justify-center p-20 space-y-4">
            <div className="animate-spin h-12 w-12 border-4 border-blue-600 border-t-transparent rounded-full"></div>
            <p className="text-gray-500 font-bold text-center">Carregando painel...</p>
        </div>
    );

    return (
        <div className="max-w-6xl mx-auto space-y-8 pb-20">
            {showAddModal && <AddMapModal onClose={() => setShowAddModal(false)} onAdded={() => {}} />}
            {editingTerritory && <EditMapModal territory={editingTerritory} onClose={() => setEditingTerritory(null)} onSave={() => {}} />}
            {viewHistory && <TerritoryHistoryModal territory={viewHistory} onClose={() => setViewHistory(null)} />}
            {viewingMap && <MapViewerModal url={viewingMap.pdfUrl} name={viewingMap.name} onClose={() => setViewingMap(null)} />}

            {/* Cabeçalho Limpo - Sem Container */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 px-1">
                <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-white rounded-xl shadow-sm border border-slate-200 flex-shrink-0">
                        <MapIcon className="w-full h-full"/>
                    </div>
                    <div>
                        <h1 className="text-2xl font-black text-slate-900 tracking-tight leading-none">Administração</h1>
                        <p className="text-slate-400 font-bold text-xs mt-1 uppercase tracking-wider">Gestão Territorial</p>
                    </div>
                </div>
                <div className="flex bg-white p-1 rounded-2xl shadow-sm border border-slate-200 self-start md:self-auto">
                    <button 
                        onClick={() => setActiveTab('territories')} 
                        className={`px-5 py-2.5 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === 'territories' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
                    >
                        Mapas
                    </button>
                    <button 
                        onClick={() => setActiveTab('users')} 
