                                                <button onClick={() => setViewingMap(m)} className="text-[9px] text-blue-600 font-black uppercase tracking-widest hover:underline mt-0.5">Ver Documento</button>
                                            </div>
                                            {m.status === TerritoryStatus.IN_USE ? (
