                    const completed = h.completedDate?.toDate() ?? new Date();
                    return {
                        ...h,
                        assignmentDate: h.assignmentDate?.toDate() ?? completed,
                        completedDate: completed
                    };
                }).sort((a,b) => b.completedDate.getTime() - a.completedDate.getTime());

                return {
