                                    const recent = isRecentWork(m.history);
                                    const isOverdue = m.status === TerritoryStatus.IN_USE && (getDaysRemaining(m.dueDate) ?? 0) < 0;

                                    let borderColor = 'border-slate-200';
                                    if (isOverdue) {
                                        borderColor = 'border-red-300';
                                    } else if (m.status === TerritoryStatus.IN_USE) {
                                        borderColor = 'border-blue-200';
                                    } else if (recent) {
                                        borderColor = 'border-amber-200';
                                    } else {
                                        borderColor = 'border-emerald-200';
                                    }

                                    return (
                                        <div key={m.id} className={`bg-white p-5 rounded-2xl border-2 ${borderColor} ${isOverdue ? 'bg-red-50/50' : ''} shadow-sm transition-all duration-300`}>
                                            <div className="flex justify-between items-start mb-4">
                                                <div><h3 className="font-black text-slate-900 text-xl tracking-tight">{m.name}</h3><button onClick={() => setViewingMap(m)} className="text-[9px] text-blue-600 font-black uppercase tracking-widest hover:underline mt-0.5">Ver Documento</button></div>
                                                {isOverdue ? (
                                                    <span className="px-2.5 py-1 bg-red-100 text-red-700 rounded-md text-[9px] font-black uppercase tracking-wider border border-red-200">Atrasado</span>
                                                ) : m.status === TerritoryStatus.IN_USE ? (
                                                    <span className="px-2.5 py-1 bg-blue-50 text-blue-600 rounded-md text-[9px] font-black uppercase tracking-wider border border-blue-100">Em Uso</span>
                                                ) : recent ? (
                                                    <span className="px-2.5 py-1 bg-amber-50 text-amber-600 rounded-md text-[9px] font-black uppercase tracking-wider border border-amber-100">Descanso</span>
                                                ) : (
                                                    <span className="px-2.5 py-1 bg-emerald-50 text-emerald-600 rounded-md text-[9px] font-black uppercase tracking-wider border border-emerald-100">Livre</span>
                                                )}
                                            </div>
                                            <div className="grid grid-cols-2 gap-4 py-3 border-y border-slate-50">
                                                {m.status === TerritoryStatus.IN_USE ? (
                                                    <>
                                                        <div>
                                                            <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-0.5">Responsável</p>
                                                            <p className="font-bold text-slate-700 text-xs truncate">{m.assignedToName || '-'}</p>
                                                            {m.dueDate && <p className={`text-[8px] font-black mt-0.5 uppercase ${isOverdue ? 'text-red-600' : 'text-slate-400'}`}>Expira: {formatDate(m.dueDate)}</p>}
                                                        </div>
                                                        <div>
                                                            <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-0.5">Designado em</p>
                                                            <p className="text-xs font-bold text-slate-600">{formatDate(m.assignmentDate)}</p>
                                                        </div>
                                                    </>
                                                ) : (
                                                    <>
                                                        <div>
                                                            <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-0.5">Último Responsável</p>
                                                            <p className="font-bold text-slate-700 text-xs truncate">{m.history?.[0]?.userName || '-'}</p>
                                                        </div>
                                                        <div>
                                                            <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-0.5">Devolvido em</p>
                                                            <p className="text-xs font-bold text-slate-600">{m.history?.[0] ? formatDate(m.history[0].completedDate) : 'Nunca'}</p>
                                                        </div>
                                                    </>
                                                )}
                                            </div>
                                            <div className="mt-4 flex justify-end gap-1">
                                                <button onClick={() => setEditingTerritory(m)} className="p-2 text-slate-400 hover:text-blue-600 rounded-lg transition-all"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.5L15.232 5.232z"></path></svg></button>
                                                <button onClick={() => setViewHistory(m)} className="p-2 text-slate-400 hover:text-indigo-600 rounded-lg transition-all"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg></button>
                                                {m.status === TerritoryStatus.IN_USE && (<button onClick={() => handleResetTerritory(m.id)} className="p-2 text-slate-400 hover:text-amber-600 rounded-lg transition-all"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M3 10h10a8 8 0 018 8v2M3 10l5 5m-5-5l5-5" /></svg></button>)}
                                                <button onClick={() => handleDeleteTerritory(m.id)} className="p-2 text-slate-400 hover:text-red-600 rounded-lg transition-all"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        ) : (
                            <div className="text-center py-16 bg-white rounded-2xl border-2 border-slate-200 col-span-1 md:col-span-2">
                                <p className="font-bold text-slate-500">Nenhum território encontrado.</p>
                                <p className="text-sm text-slate-400 mt-1">Tente ajustar os filtros ou adicione um novo mapa.</p>
                            </div>
                        )}
                    </div>
                </>
            ) : activeTab === 'users' ? (
                <div className="space-y-4">
                    <h2 className="text-[11px] font-black text-slate-900 uppercase tracking-[0.2em] px-2">Gestão de Usuários</h2>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                        {users.map(u => (
                            <div key={u.id} className="bg-white p-5 rounded-2xl border-2 border-slate-200 flex items-center justify-between gap-4">
                                <div className="flex-1 overflow-hidden"><p className="font-black text-slate-900 text-lg leading-tight truncate">{u.name}</p><p className="font-bold text-slate-400 text-[10px] truncate mb-2">{u.email}</p><span className={`px-2 py-0.5 rounded-md text-[8px] font-black uppercase tracking-wider ${u.role === 'admin' ? 'bg-indigo-50 text-indigo-600 border border-indigo-100' : 'bg-slate-50 text-slate-500 border border-slate-100'}`}>{u.role}</span></div>
                                <button onClick={() => handlePromote(u)} className="px-3 py-2.5 bg-slate-50 text-slate-600 text-[9px] font-black rounded-lg border border-slate-200 uppercase tracking-tighter">Cargo</button>
                            </div>
                        ))}
                    </div>
                </div>
            ) : (
                <AssignmentsReport territories={territories} />
            )}
        </div>
    );
};

export default AdminDashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { Territory } from '../types';
import { formatDate, generateServiceYearOptions } from '../utils/helpers';

interface ReportEntry {
  territoryName: string;
  userName: string;
  assignmentDate: Date;
  completedDate: Date;
  id: string;
}

const AssignmentsReport: React.FC<{ territories: Territory[] }> = ({ territories }) => {
  const serviceYearOptions = useMemo(() => generateServiceYearOptions(), []);
  const [filterPeriod, setFilterPeriod] = useState<string>('last-6-months');
  const [filteredData, setFilteredData] = useState<ReportEntry[]>([]);

  const filterOptions = [
    { label: 'Últimos 6 meses', value: 'last-6-months' },
    { label: 'Últimos 12 meses', value: 'last-12-months' },
    ...serviceYearOptions,
  ];

  useEffect(() => {
    const allHistoryEntries: ReportEntry[] = territories.flatMap(t =>
      (t.history || []).map((h, index) => ({
        territoryName: t.name,
        userName: h.userName,
        assignmentDate: h.assignmentDate,
        completedDate: h.completedDate,
        id: `${t.id}-${index}`
      }))
    );

    let startDate: Date | null = null;
    let endDate: Date = new Date();

    if (filterPeriod === 'last-6-months') {
        startDate = new Date();
        startDate.setMonth(startDate.getMonth() - 6);
    } else if (filterPeriod === 'last-12-months') {
        startDate = new Date();
        startDate.setMonth(startDate.getMonth() - 12);
    } else if (filterPeriod.startsWith('sy-')) {
        const selectedYear = serviceYearOptions.find(opt => opt.value === filterPeriod);
        if (selectedYear) {
            startDate = selectedYear.startDate;
            endDate = selectedYear.endDate;
        }
    }

    if (startDate) {
        const data = allHistoryEntries.filter(entry => {
            const completed = entry.completedDate;
            return completed >= startDate! && completed <= endDate;
        });
        data.sort((a, b) => b.completedDate.getTime() - a.completedDate.getTime());
        setFilteredData(data);
    }
  }, [territories, filterPeriod, serviceYearOptions]);

  const handleExportCsv = async () => {
    const headers = "Publicador,Território,Data de Designação,Data de Devolução\n";
    const csvContent = filteredData.map(row => 
        `"${row.userName}","${row.territoryName}","${formatDate(row.assignmentDate)}","${formatDate(row.completedDate)}"`
    ).join("\n");

    const fullCsv = headers + csvContent;
    const blob = new Blob([`\uFEFF${fullCsv}`], { type: 'text/csv;charset=utf-8;' });
    const file = new File([blob], "relatorio_designacoes.csv", { type: "text/csv" });

    if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        try {
            await navigator.share({
                files: [file],
                title: 'Relatório de Designações',
                text: 'Segue o relatório de designações de território.'
            });
        } catch (err) { console.error("Erro ao compartilhar:", err); }
    } else {
        const link = document.createElement("a");
        const url = URL.createObjectURL(blob);
        link.href = url;
        link.download = "relatorio_designacoes.csv";
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    }
  };

  const handleExportPdf = () => {
      const selectedOption = filterOptions.find(opt => opt.value === filterPeriod);
      const periodLabel = selectedOption ? selectedOption.label : 'Período selecionado';

      const tableContent = filteredData.map(row => `
          <tr>
              <td>${row.userName}</td>
              <td>${row.territoryName}</td>
              <td>${formatDate(row.assignmentDate)}</td>
              <td>${formatDate(row.completedDate)}</td>
          </tr>
      `).join('');

      const printWindow = window.open('', '_blank');
      printWindow?.document.write(`
          <html>
              <head>
                  <title>Relatório de Designações</title>
                  <style>
                      body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; padding: 20px; }
                      table { width: 100%; border-collapse: collapse; margin-top: 20px; }
                      th, td { border: 1px solid #ddd; padding: 12px; text-align: left; }
                      th { background-color: #f2f2f2; font-weight: bold; }
                      h1, h2 { color: #333; }
                      @media print {
                          body { -webkit-print-color-adjust: exact; }
                          button { display: none; }
                      }
                  </style>
              </head>
              <body>
                  <h1>Relatório de Designações</h1>
                  <h2>Período: ${periodLabel}</h2>
                  <table>
                      <thead>
                          <tr>
                              <th>Publicador</th>
                              <th>Território</th>
                              <th>Designado Em</th>
                              <th>Devolvido Em</th>
                          </tr>
                      </thead>
                      <tbody>
                          ${tableContent}
                      </tbody>
                  </table>
                  <script>setTimeout(() => { window.print(); window.close(); }, 500);</script>
              </body>
          </html>
      `);
      printWindow?.document.close();
  };

  return (
    <div className="space-y-6">
        <div className="bg-white p-5 rounded-2xl border-2 border-slate-200 flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div className="flex-1">
                 <label className="block text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Filtrar por Período</label>
                 <select 
                    value={filterPeriod} 
                    onChange={e => setFilterPeriod(e.target.value)}
                    className="w-full md:w-auto px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg font-bold text-sm outline-none shadow-sm"
                >
                    <option value="last-6-months">Últimos 6 meses</option>
                    <option value="last-12-months">Últimos 12 meses</option>
                    <optgroup label="Ano de Serviço">
                        {serviceYearOptions.map(opt => <option key={opt.value} value={opt.value}>{opt.label}</option>)}
                    </optgroup>
                 </select>
            </div>
            <div className="flex items-center gap-2">
                <button onClick={handleExportCsv} className="flex items-center gap-2 px-4 py-3 bg-emerald-600 text-white font-black text-[10px] uppercase tracking-wider rounded-lg shadow-sm hover:bg-emerald-700 transition-colors">
                    <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a8 8 0 100 16 8 8 0 000-16zM7 6a1 1 0 011-1h4a1 1 0 110 2H8a1 1 0 01-1-1zm3 10a1 1 0 01-1-1v-4a1 1 0 112 0v4a1 1 0 01-1 1z" /></svg>
                    EXCEL
                </button>
                <button onClick={handleExportPdf} className="flex items-center gap-2 px-4 py-3 bg-red-600 text-white font-black text-[10px] uppercase tracking-wider rounded-lg shadow-sm hover:bg-red-700 transition-colors">
                    <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M4 4a2 2 0 012-2h8a2 2 0 012 2v12a2 2 0 01-2 2H6a2 2 0 01-2-2V4zm4 10.5a.5.5 0 00.5.5h3a.5.5 0 000-1h-3a.5.5 0 00-.5.5zM8 11.5a.5.5 0 00.5.5h3a.5.5 0 000-1h-3a.5.5 0 00-.5.5zM8 9.5a.5.5 0 00.5.5h3a.5.5 0 000-1h-3a.5.5 0 00-.5.5z" clipRule="evenodd" /></svg>
                    PDF
                </button>
            </div>
        </div>

        <div className="bg-white rounded-2xl border-2 border-slate-200 overflow-hidden">
            <div className="overflow-x-auto">
                <table className="w-full text-sm">
                    <thead className="bg-slate-50">
                        <tr>
                            <th className="px-5 py-3 text-left text-[10px] font-black text-slate-500 uppercase tracking-wider">Publicador</th>
                            <th className="px-5 py-3 text-left text-[10px] font-black text-slate-500 uppercase tracking-wider">Território</th>
                            <th className="px-5 py-3 text-left text-[10px] font-black text-slate-500 uppercase tracking-wider">Designado em</th>
                            <th className="px-5 py-3 text-left text-[10px] font-black text-slate-500 uppercase tracking-wider">Devolvido em</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {filteredData.length > 0 ? filteredData.map(entry => (
                            <tr key={entry.id}>
                                <td className="px-5 py-4 font-bold text-slate-800 whitespace-nowrap">{entry.userName}</td>
                                <td className="px-5 py-4 font-bold text-slate-600 whitespace-nowrap">{entry.territoryName}</td>
                                <td className="px-5 py-4 font-bold text-slate-500 whitespace-nowrap">{formatDate(entry.assignmentDate)}</td>
                                <td className="px-5 py-4 font-bold text-slate-500 whitespace-nowrap">{formatDate(entry.completedDate)}</td>
                            </tr>
                        )) : (
                            <tr>
                                <td colSpan={4} className="text-center py-16 text-slate-400 font-bold italic">Nenhum registro encontrado para este período.</td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    </div>
  );
};

export default AssignmentsReport;
